def _load_tunable_settings_from_db():
    """Bot ishga tushganda — owner avval panel orqali o'zgartirgan sozlamalar
    bo'lsa, ularni bazadan o'qib, standart qiymatlar o'rniga qo'llaydi."""
    for varname, _label, caster in TUNABLE_SETTINGS:
        try:
            raw = get_setting(f"tune_{varname}")
            if raw is not None:
                globals()[varname] = caster(raw)
        except Exception:
            pass  # xato bo'lsa ham standart qiymat bilan davom etadi


_load_tunable_settings_from_db()


def _bot_settings_panel_text_and_kb():
    kb = types.InlineKeyboardMarkup(row_width=1)
    lines = ["⚙️ <b>Bot sozlamalari</b> (kod yozmasdan o'zgartirish)\n"]
    for varname, label, _caster in TUNABLE_SETTINGS:
        current = globals().get(varname)
        lines.append(f"• {label}: <b>{current}</b>")
        kb.add(types.InlineKeyboardButton(f"✏️ {label}", callback_data=f"admin|tune_edit|{varname}"))
    lines.append("\n✏️ tugmasini bosib, yangi (butun) sonni yuboring.")
    return "\n".join(lines), kb


