@bot.callback_query_handler(func=lambda c: c.data.startswith("admin|tune_edit|"))
def cb_admin_tune_edit(call):
    maybe_capture_owner(call.from_user)
    if not is_owner(call.from_user.id):
        bot.answer_callback_query(call.id, "⛔ Ruxsat yo'q.", show_alert=True)
        return
    varname = call.data.split("|", 2)[2]
    entry = next((t for t in TUNABLE_SETTINGS if t[0] == varname), None)
    if not entry:
        bot.answer_callback_query(call.id, "❌ Topilmadi.", show_alert=True)
        return
    bot.answer_callback_query(call.id)
    _TUNE_EDIT_STATE[call.from_user.id] = varname
    bot.send_message(
        call.message.chat.id,
        f"✏️ <b>{entry[1]}</b>\n\nHozirgi qiymat: <b>{globals().get(varname)}</b>\n"
        f"Yangi (butun) sonni yuboring:",
    )


def _handle_tune_setting_input(message):
    uid = message.from_user.id
    if not is_owner(uid):
        _TUNE_EDIT_STATE.pop(uid, None)
        return
    varname = _TUNE_EDIT_STATE.get(uid)
    entry = next((t for t in TUNABLE_SETTINGS if t[0] == varname), None)
    if not entry:
        _TUNE_EDIT_STATE.pop(uid, None)
        return
    _, label, caster = entry
    raw = (message.text or "").strip()
    try:
        value = caster(raw)
        if value <= 0 and varname not in TUNABLE_ALLOW_NEGATIVE:
            raise ValueError
    except Exception:
        if varname in TUNABLE_ALLOW_NEGATIVE:
            bot.reply_to(message, "❌ Noto'g'ri qiymat. Butun son yuboring (manfiy ham bo'lishi mumkin), masalan: <code>-10</code>")
        else:
            bot.reply_to(message, "❌ Noto'g'ri qiymat. Musbat butun son yuboring, masalan: <code>5</code>")
        return
    _old_val = globals().get(varname)
    globals()[varname] = value
    try:
        set_setting(f"tune_{varname}", value)
    except Exception:
        _logger.error("Sozlama bazaga saqlanmadi (%s) — restartdan keyin eskisiga qaytadi", varname, exc_info=True)
    try:
        _oc_recompute_derived()   # 👑 DAY_VOTE_SECONDS = umumiy − muhokama
        oc_log_external(uid, varname, label, _old_val, value, "legacy-panel")
    except Exception:
        pass
    if varname.startswith("HC_"):
        _hc_clamp_rate()   # 🔧 v8: kurs chegaralari o'zgarsa — joriy kurs darhol moslanadi
    _TUNE_EDIT_STATE.pop(uid, None)
    bot.reply_to(message, f"✅ <b>{label}</b> yangilandi: <b>{value}</b>\nBu qiymat darhol amal qiladi va bot qayta ishga tushsa ham saqlanadi.")


HC_BUY_PRESETS = [1, 2, 5, 10, 20, 50]


def hc_spread():
    """Kurs atrofidagi spred (ulush). Kamida (max-min)/(max+min) — shu bilan 'arzon sotib olib qimmat sotish'
    (arbitraj) matematik jihatdan yopiladi, owner chegaralarni qanday o'zgartirmasin."""
    lo, hi = float(HC_RATE_MIN_MULT), float(HC_RATE_MAX_MULT)
    floor_h = (hi - lo) / (hi + lo) if hi + lo > 0 else 0.0
    return min(0.99, max(float(HC_SPREAD_PCT) / 100.0, floor_h))


def hc_buy_rate(rate=None):
    """1 🪙 ni sotib olish narxi (💎) — kursdan yuqori (butun songa yuqoriga yaxlitlanadi)."""
    r = HC_DIAMOND_RATE if rate is None else rate
    return max(1, math.ceil(r * (1 + hc_spread()) + 1e-9))


def hc_sell_rate(rate=None):
    """1 🪙 ni sotganda olinadigan 💎 — kursdan past (butun songa pastga yaxlitlanadi)."""
    r = HC_DIAMOND_RATE if rate is None else rate
    return max(0, math.floor(r * (1 - hc_spread()) - 1e-9))


def hc_stars_diamond_equiv():
    """Stars bilan 1 🪙 narxi (💎 ekvivalentida): BAZAVIY kurs, lekin hech qachon coin sotishdan
    olinadigan maksimal 💎 dan past emas → Stars→coin→💎 aylanma foyda bermaydi."""
    sell_max = math.floor(HC_BASE_DIAMOND_RATE * HC_RATE_MAX_MULT * (1 - hc_spread()) + 1e-9)
    return max(int(HC_BASE_DIAMOND_RATE), sell_max)


def hc_star_price(qty):
    """⭐ Stars narxi — QAT'IY (kursga bog'liq emas): soni × bazaviy 💎 × (1 💎 = necha ⭐)."""
    return max(1, int(qty) * hc_stars_diamond_equiv() * DIAMOND_STARS_RATE)


_HC_LAST_TRADE = {}


def _hc_cooldown_ok(uid):
    now = time.time()
    last = _HC_LAST_TRADE.get(uid, 0)
    if now - last < HC_TRADE_COOLDOWN_SEC:
        return False
    _HC_LAST_TRADE[uid] = now
    if len(_HC_LAST_TRADE) > 5000:
        for k in [k for k, t in _HC_LAST_TRADE.items() if now - t > 60]:
            _HC_LAST_TRADE.pop(k, None)
    return True


def hc_sell_for_diamonds(uid, qty):
    """(ok, xabar, olingan_💎, kurs) — Hunter Coin'ni joriy kurs (spred bilan) bo'yicha SOTISH. Atomik."""
    try:
        qty = int(qty)
    except Exception:
        return False, "Miqdor butun son bo'lishi kerak.", 0, 0
    if not (1 <= qty <= 1000):
        return False, "Miqdor 1 dan 1000 gacha bo'lishi kerak.", 0, 0
    if not _hc_cooldown_ok(uid):
        return False, "Iltimos, bir necha soniya kuting.", 0, 0
    rate = hc_sell_rate()
    gain = qty * rate
    with db_lock:
        cur.execute("UPDATE users SET coin = coin - ?, diamond = diamond + ? WHERE user_id=? AND coin >= ?", (qty, gain, uid, qty))
        ok = cur.rowcount > 0
        conn.commit()
    if not ok:
        return False, f"Coin yetarli emas: {qty} 🪙 kerak.", 0, rate
    return True, f"{qty} 🪙 sotildi (+{gain} 💎, sotish kursi: 1 🪙 = {rate} 💎).", gain, rate


def hc_buy_with_diamonds(uid, qty):
    """(ok, xabar, narx, kurs) — Hunter Coin'ni 💎 Olmosga JORIY KURS bo'yicha sotib olish. Atomik."""
    try:
        qty = int(qty)
    except Exception:
        return False, "Miqdor butun son bo'lishi kerak.", 0, 0
    if not (1 <= qty <= 1000):
        return False, "Miqdor 1 dan 1000 gacha bo'lishi kerak.", 0, 0
    if not _hc_cooldown_ok(uid):
        return False, "Iltimos, bir necha soniya kuting.", 0, 0
    rate = hc_buy_rate()
    cost = qty * rate
    with db_lock:
        cur.execute("UPDATE users SET diamond = diamond - ?, coin = coin + ? WHERE user_id=? AND diamond >= ?", (cost, qty, uid, cost))
        ok = cur.rowcount > 0
        conn.commit()
    if not ok:
        return False, f"Olmos yetarli emas: {qty} 🪙 = {cost} 💎 (kurs: 1 🪙 = {rate} 💎).", cost, rate
    return True, f"{qty} 🪙 sotib olindi (−{cost} 💎, kurs: 1 🪙 = {rate} 💎).", cost, rate


def _som_per_diamond():
    """Owner belgilagan 1 💎 ning taxminiy so'm qiymati (/som_kurs). Belgilanmagan bo'lsa — None."""
    try:
        v = float(get_setting("som_per_diamond") or 0)
        return v if v > 0 else None
    except Exception:
        return None


def open_diamond_to_coin_menu(chat_id, uid, call=None):
    u = user_dict(uid)
    rate = hc_buy_rate()
    sell = hc_sell_rate()
    cur_rate = hc_diamond_rate_int()
    chg = (HC_DIAMOND_RATE - HC_BASE_DIAMOND_RATE) / float(HC_BASE_DIAMOND_RATE) * 100.0
    chg_icon = "🟢📈" if chg > 0.05 else ("🔴📉" if chg < -0.05 else "⚪️")
    upd = time.strftime("%H:%M", time.localtime(globals().get("HC_LAST_UPDATE_TS", time.time())))
    som = _som_per_diamond()
    lines = [
        "🪙 <b>Hunter Coin bozori</b>",
        "",
        f"💰 Balansingiz: <b>{u['coin']}</b> 🪙  •  <b>{u['diamond']}</b> 💎",
        "",
        f"📊 Joriy narx: <b>1 🪙 = {cur_rate} 💎</b>",
    ]
    if som:
        lines.append(f"💵 Taxminiy qiymati: <b>≈ {int(round(cur_rate * som)):,}</b> so'm".replace(",", " "))
    lines += [
        f"{chg_icon} Bazaviy narxdan: <b>{chg:+.1f}%</b>  •  🕒 {upd}",
        f"🟢 Olish: <b>{rate}</b> 💎   🔴 Sotish: <b>{sell}</b> 💎",
        "",
        "ℹ️ <b>Qanday ishlaydi?</b>",
        f"• Narx har {HC_MARKET_UPDATE_MINUTES} daqiqada o'zgaradi",
        "• 🪙 do'konda Oltin o'q, Duelda g'alaba va Klan litsenziyasi uchun sarflanadi",
        "• Do'stingizga o'tkazish: xabariga <b>reply</b> qilib <code>/coin</code> (1 🪙)",
        "• Ko'proq: <code>/hc_sotib 3</code> • <code>/hc_sot 3</code>",
    ]
    kb = types.InlineKeyboardMarkup(row_width=2)
    kb.add(types.InlineKeyboardButton("🟢 1 🪙 olish", callback_data="hcbuy|1"),
           types.InlineKeyboardButton("🔴 1 🪙 sotish", callback_data="hcsell|1"))
    kb.add(types.InlineKeyboardButton("🔄 Kursni yangilash", callback_data="hcrefresh"))
    kb.add(types.InlineKeyboardButton("⬅️ Do'konga qaytish", callback_data="shopback"))
    text = "\n".join(lines)
    if call:
        smart_render(call, text, kb)
    else:
        bot.send_message(chat_id, text, reply_markup=kb)


