@bot.message_handler(commands=["som_kurs"])
def cmd_som_kurs(message):
    """👑 Owner: /som_kurs <so'm> — 1 💎 ning taxminiy so'm qiymati (Hunter Coin bozorida ko'rinadi). 0 — o'chirish."""
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    if not is_owner(message.from_user.id):
        return
    parts = (message.text or "").split()
    if len(parts) < 2 or not parts[1].replace(".", "", 1).isdigit():
        bot.send_message(message.chat.id, "Foydalanish: <code>/som_kurs 1500</code> — 1 💎 = 1500 so'm (0 — o'chirish).")
        return
    set_setting("som_per_diamond", parts[1])
    bot.send_message(message.chat.id, f"✅ 1 💎 ≈ {parts[1]} so'm — bozor ekranida ko'rinadi.")


