    kb.add(types.InlineKeyboardButton("🔁 Standart narxlarga qaytarish", callback_data="admin|elite_price_reset"))
    lines.append("\n✏️ tugmasini bosib, yangi narxni <code>olmos stars</code> formatida yozing (masalan: <code>50 120</code>).")
