def _adm3_kb(*rows):
    kb = types.InlineKeyboardMarkup()
    for r in rows:
        kb.row(*[types.InlineKeyboardButton(t, callback_data=d) for t, d in r])
    kb.add(types.InlineKeyboardButton("⬅️ Boshqaruv", callback_data="adm3|home"),
           types.InlineKeyboardButton("🏠 Menyu", callback_data="menu|main_back"))
    return kb


def _adm3_scalar(q, args=()):
    try:
        with db_lock:
            cur.execute(q, args)
            r = cur.fetchone()
        return (r[0] or 0) if r else 0
    except Exception:
        return 0


def _adm3_dash_text():
    now = time.time()
    total = _adm3_scalar("SELECT COUNT(*) FROM users")
    n24 = _adm3_scalar("SELECT COUNT(*) FROM users WHERE first_seen>?", (now - 86400,))
    n7 = _adm3_scalar("SELECT COUNT(*) FROM users WHERE first_seen>?", (now - 7 * 86400,))
    banned = _adm3_scalar("SELECT COUNT(*) FROM users WHERE banned=1")
    gtoday = int(get_setting("games_day_" + time.strftime("%Y-%m-%d")) or 0)
    active = [g for g in GAMES.values() if g.get("phase") in ("night", "day")]
    lobbies = [g for g in GAMES.values() if g.get("phase") == "waiting"]
    in_play = sum(len(g.get("players", {})) for g in active)
    groups = len(list_known_groups())
    bsubs = 0
    try:
        with db_lock:
            cur.execute("SELECT value FROM bot_settings WHERE key LIKE 'bildir_%'")
            for (v,) in cur.fetchall():
                bsubs += len(json.loads(v or "[]"))
    except Exception:
        pass
    return (
        "📊 <b>DASHBOARD</b>\n\n"
        f"👥 Foydalanuvchilar: <b>{total}</b>\n"
        f"🆕 Yangi (24 soat): <b>{n24}</b> · (7 kun): <b>{n7}</b>\n"
        f"🚫 Bloklangan: <b>{banned}</b>\n\n"
        f"🎮 Bugun tugagan o'yinlar: <b>{gtoday}</b>\n"
        f"▶️ Hozir o'ynalayotgan: <b>{len(active)}</b> ({in_play} o'yinchi)\n"
        f"🛋 Ochiq lobbilar: <b>{len(lobbies)}</b>\n"
        f"💬 Ma'lum guruhlar: <b>{groups}</b>\n"
        f"🔔 Bildirish obunachilari: <b>{bsubs}</b>\n"
        f"🏷 Versiya: <b>{BOT_VERSION}</b>\n"
        f"⏱ Uptime: {int((now - _BOT_START_TS) // 3600)} soat · 🧵 {threading.active_count()} oqim"
    )


def _adm3_lang_text():
    langs, genders = collections.Counter(), collections.Counter()
    try:
        with db_lock:
            cur.execute("SELECT charges FROM users")
            rows = cur.fetchall()
        for (c,) in rows:
            try:
                d = json.loads(c or "{}")
            except Exception:
                continue
            if d.get("lang_chosen"):
                langs[d.get("lang", "uz")] += 1
            genders[d.get("gender") or "?"] += 1
    except Exception:
        pass
    lab = dict(LANG_LIST)
    lines = ["🌍 <b>TILLAR VA JINS</b>\n"]
    for code, n in langs.most_common(12):
        lines.append(f"{lab.get(code, code)}: <b>{n}</b>")
    if not langs:
        lines.append("Hali til tanlanmagan.")
    lines.append(f"\n👨 Erkak: <b>{genders.get('male', 0)}</b> · 👩 Ayol: <b>{genders.get('female', 0)}</b> · ❔ Noma'lum: <b>{genders.get('?', 0)}</b>")
    return "\n".join(lines)


def _adm3_stuck_games():
    now = time.time()
    out = []
    for cid, g in list(GAMES.items()):
        ph = g.get("phase")
        dl = g.get("phase_deadline") or 0
        if ph in ("night", "day") and dl and now - dl > 300:
            out.append((cid, g, f"{ph}: muddat {(now - dl) / 60:.0f} daq. o'tgan"))
    return out


def _adm3_cancel_game(cid):
    g = GAMES.pop(cid, None)
    if not g:
        return False
    for t in list(g.get("timers", [])):
        try:
            t.cancel()
        except Exception:
            pass
    try:
        if g.get("join_msg_id"):
            _close_join_message(cid, g["join_msg_id"])
    except Exception:
        pass
    try:
        save_games_state()
    except Exception:
        pass
    return True


