def _prime_level_arg(parts, idx, default=3):
    """Buyruqdagi ixtiyoriy PRIME darajasi (1/2/3). Noto'g'ri bo'lsa None."""
    if len(parts) <= idx:
        return default
    return int(parts[idx]) if parts[idx] in ("1", "2", "3") else None


@bot.message_handler(commands=["elite_ber", "prime_ber"])
def cmd_owner_elite_ber(message):
    """👑 Bot egasi — istalgan foydalanuvchiga qo'lda, xohlagan muddatga
    PRIME (VIP) beradi. Mavjud grant_elite_days() funksiyasidan
    foydalanadi — shu sababli sotib olingan PRIME bilan 100% mos (qo'shiladi).
    Foydalanish: kimningdir xabariga reply qilib /elite_ber <kun> [daraja 1/2/3]
    (daraja ko'rsatilmasa — 3)."""
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    if not is_owner(message.from_user.id):
        return
    parts = message.text.split()
    level = _prime_level_arg(parts, 2) if len(parts) in (2, 3) else None
    if not message.reply_to_message or len(parts) not in (2, 3) or not parts[1].lstrip("-").isdigit() or level is None:
        bot.send_message(
            message.chat.id,
            "Foydalanish: kimningdir xabariga reply qilib <code>/elite_ber &lt;kun&gt; [daraja 1/2/3]</code>\n"
            "Masalan: <code>/elite_ber 30 2</code> — 30 kunlik PRIME 2. Daraja yozilmasa — PRIME 3.",
        )
        return
    days = int(parts[1])
    if days <= 0 or days > 3650:
        bot.send_message(message.chat.id, "❌ Kunlar soni 1 dan 3650 gacha bo'lishi kerak.")
        return
    target = message.reply_to_message.from_user
    user_dict(target.id, target.first_name)
    new_until = grant_elite_days(target.id, days, level)
    bot.send_message(
        message.chat.id,
        f"👑 {mention(target.id, target.first_name)}ga <b>{days} kunlik</b> {prime_name(level)} berildi!\n"
        f"📅 Amal qilish muddati: <b>{time.strftime('%d.%m.%Y', time.localtime(new_until))}</b> gacha.",
    )
    safe_send(target.id, elite_success_text(days, new_until, level))


@bot.message_handler(commands=["elite_kun", "elite_qolgan"])
def cmd_owner_elite_kun(message):
    """👑 Bot egasi — istalgan foydalanuvchining PRIME muddati necha kun
    qolganini tekshiradi. Foydalanish: kimningdir xabariga reply qilib /elite_kun."""
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    if not is_owner(message.from_user.id):
        return
    if not message.reply_to_message:
        bot.send_message(
            message.chat.id,
            "Foydalanish: kimningdir xabariga reply qilib <code>/elite_kun</code>",
        )
        return
    target = message.reply_to_message.from_user
    user_dict(target.id, target.first_name)
    if is_elite(target.id):
        ch = get_charges(target.id)
        now_ts = time.time()
        rows = []
        for lv in (1, 2, 3):
            u = ch.get(_PRIME_KEYS[lv], 0) or 0
            if u > now_ts:
                rows.append(f"• {prime_name(lv)}: <b>{int((u - now_ts) // 86400) + 1} kun</b> "
                            f"({time.strftime('%d.%m.%Y', time.localtime(u))} gacha)")
        if not rows:
            rows.append(f"• {prime_name(3)}: maxsus toifa orqali doimiy")
        bot.send_message(
            message.chat.id,
            f"👑 {mention(target.id, target.first_name)} — amaldagi daraja: <b>{prime_name(prime_level(target.id, ch))}</b>\n"
            + "\n".join(rows),
        )
    else:
        bot.send_message(message.chat.id, f"👤 {mention(target.id, target.first_name)}da PRIME faol emas.")


@bot.message_handler(commands=["elite_kamaytir"])
def cmd_owner_elite_kamaytir(message):
    """👑 Bot egasi — istalgan foydalanuvchining PRIME muddatidan xohlagan
    kun sonini ayiradi (agar natija 0 yoki manfiy bo'lsa, PRIME butunlay
    o'chadi). Foydalanish: kimningdir xabariga reply qilib /elite_kamaytir <kun>."""
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    if not is_owner(message.from_user.id):
        return
    parts = message.text.split()
    level = _prime_level_arg(parts, 2, default=0) if len(parts) in (2, 3) else None
    if not message.reply_to_message or len(parts) not in (2, 3) or not parts[1].isdigit() or level is None:
        bot.send_message(
            message.chat.id,
            "Foydalanish: kimningdir xabariga reply qilib <code>/elite_kamaytir &lt;kun&gt; [daraja 1/2/3]</code>\n"
            "Daraja yozilmasa — hozir amaldagi eng yuqori daraja qisqartiriladi.",
        )
        return
    days = int(parts[1])
    if days <= 0:
        bot.send_message(message.chat.id, "❌ Kunlar soni musbat bo'lishi kerak.")
        return
    target = message.reply_to_message.from_user
    user_dict(target.id, target.first_name)
    if not is_elite(target.id):
        bot.send_message(message.chat.id, f"👤 {mention(target.id, target.first_name)}da PRIME faol emas.")
        return
    ch = get_charges(target.id)
    level = level or max((lv for lv in (1, 2, 3) if (ch.get(_PRIME_KEYS[lv], 0) or 0) > time.time()), default=3)
    _k = _PRIME_KEYS[level]
    current_until = ch.get(_k, 0)
    if not current_until or current_until <= time.time():
        bot.send_message(message.chat.id, f"👤 {mention(target.id, target.first_name)}da {prime_name(level)} faol emas.")
        return
    new_until = current_until - days * 86400
    if new_until <= time.time():
        set_charge_value(target.id, _k, 0)
        bot.send_message(
            message.chat.id,
            f"👑 {mention(target.id, target.first_name)}ning PRIME muddati <b>{days} kun</b>ga qisqartirildi — "
            "muddat tugagani sababli PRIME butunlay o'chirildi.",
        )
    else:
        set_charge_value(target.id, _k, new_until)
        bot.send_message(
            message.chat.id,
            f"👑 {mention(target.id, target.first_name)}ning {prime_name(level)} muddati <b>{days} kun</b>ga qisqartirildi — "
            f"endi <b>{int((new_until - time.time()) // 86400) + 1} kun</b> qoldi.",
        )


@bot.message_handler(commands=["elite_olib_qoy"])
def cmd_owner_elite_olib_qoy(message):
    """👑 Bot egasi — istalgan foydalanuvchining PRIME a'zoligini butunlay
    (muddatidan qat'i nazar) darhol olib tashlaydi. Foydalanish: kimningdir
    xabariga reply qilib /elite_olib_qoy."""
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    if not is_owner(message.from_user.id):
        return
    parts = message.text.split()
    level = _prime_level_arg(parts, 1, default=0) if len(parts) in (1, 2) else None
    if not message.reply_to_message or level is None:
        bot.send_message(
            message.chat.id,
            "Foydalanish: kimningdir xabariga reply qilib <code>/elite_olib_qoy [daraja 1/2/3]</code>\n"
            "Daraja yozilmasa — barcha PRIME darajalari olib tashlanadi.",
        )
        return
    target = message.reply_to_message.from_user
    user_dict(target.id, target.first_name)
    if not is_elite(target.id):
        bot.send_message(message.chat.id, f"👤 {mention(target.id, target.first_name)}da PRIME allaqachon faol emas.")
        return
    if level:
        set_charge_value(target.id, _PRIME_KEYS[level], 0)
        what = prime_name(level)
    else:
        prime_clear(target.id)   # barcha PRIME darajalari
        what = "PRIME a'zoligi (barcha darajalar)"
    bot.send_message(message.chat.id, f"🚫 {mention(target.id, target.first_name)}ning {what} olib tashlandi.")
    safe_send(target.id, f"👑 Sizning {what} bot egasi tomonidan bekor qilindi.")


