# Scope bo'yicha moslashtirish: faqat shaxsiy chatda / faqat guruhda ma'noli buyruqlar
PM_ONLY_COMMANDS = {"taxallus", "arvoh", "savol", "premium", "juft_bozor", "juft_sot", "tasodifiy_juft",
                    "theron"}
GROUP_ONLY_COMMANDS = {"ngame", "join", "tark_et", "zahar", "gps", "kompas", "tutun", "fonar", "qayta_tanlash",
                       "geroy_bashorat", "osh", "duel", "para", "dpara",
                       "give", "money", "coin", "solishtir", "hisob", "chiqish"}
_GROUP_DESC_OVERRIDE = {"start": "▶️ O'yinni boshlash"}

TG_MENU_LIMIT = 100
_CMD_NAME_RE = re.compile(r"^[a-z0-9_]{1,32}$")


def _valid_menu_entry(c, d):
    return bool(_CMD_NAME_RE.match(c)) and 3 <= len(d) <= 256


def _dedupe_cmds(items):
    seen, out = set(), []
    for c, d in items:
        if c in seen:
            continue
        seen.add(c)
        out.append((c, d))
    return out


