def _OWNER_EXTRA_FOR_MENU():
    return [(c, d) for c, d in OWNER_EXTRA_COMMANDS if c not in _OWNER_MENU_NOISE and _valid_menu_entry(c, d)]


def build_command_menu(role, chat_kind):
    """role: 'user' | 'admin' | 'owner'; chat_kind: 'private' | 'group'.
    Telegram menyusi (≤100) uchun [(cmd, desc)] qaytaradi (tartib = muhimlik tartibi)."""
    if role != "owner":
        if chat_kind == "private":
            return list(_V3_PRIVATE_MENU)
        return (list(_V3_GROUP_ADMIN_MENU) + list(_V3_GROUP_USER_MENU)) if role == "admin" else list(_V3_GROUP_USER_MENU)
    if chat_kind == "private":
        return list(_V3_PRIVATE_MENU) + [(c, d) for c, d in _OWNER_EXTRA_FOR_MENU() if c not in dict(_V3_PRIVATE_MENU)][:90]
    return list(_V3_GROUP_ADMIN_MENU) + list(_V3_GROUP_USER_MENU) + [(c, d) for c, d in _OWNER_EXTRA_FOR_MENU()][:80]
    user = [(c, d) for c, d in USER_COMMANDS
            if (c not in GROUP_ONLY_COMMANDS if chat_kind == "private" else c not in PM_ONLY_COMMANDS)]
    if chat_kind == "group":
        user = [(c, _GROUP_DESC_OVERRIDE.get(c, d)) for c, d in user]
    if role == "user":
        items = user
    elif role == "admin":
        items = ADMIN_COMMANDS + user
    else:  # owner — HAMMA muhim buyruqlar ko'rinadi (give, money va h.k. ham, chatdan qat'i nazar)
        full_user = [(c, _GROUP_DESC_OVERRIDE.get(c, d) if chat_kind == "group" else d) for c, d in USER_COMMANDS]
        udict = dict(full_user)
        prio = [(c, udict[c]) for c in _OWNER_PRIORITY_USER_CMDS if c in udict]
        odict = [(c, d) for c, d in OWNER_EXTRA_COMMANDS if c not in _OWNER_MENU_NOISE]
        rest_user = [(c, d) for c, d in full_user if c not in _OWNER_PRIORITY_USER_CMDS]
        items = (prio + ADMIN_COMMANDS + odict + rest_user)
    items = [(c, d) for c, d in _dedupe_cmds(items) if _valid_menu_entry(c, d)]
    return items[:TG_MENU_LIMIT]


def _set_owner_group_menus(throttle=0.25):
    """Owner HAR BIR guruhda ham o'z (to'liq) menyusini ko'radi (ChatMember scope)."""
    try:
        with db_lock:
            cur.execute("SELECT chat_id FROM known_groups")
            groups = [r[0] for r in cur.fetchall()]
    except Exception:
        groups = []
    cmds = [types.BotCommand(c, d) for c, d in build_command_menu("owner", "group")]
    for gid in groups:
        try:
            bot.set_my_commands(commands=cmds, scope=types.BotCommandScopeChatMember(chat_id=gid, user_id=OWNER_ID_FROM_ENV))
        except Exception:
            pass   # bot guruhda yo'q / huquq yo'q — e'tiborsiz
        if throttle:
            time.sleep(throttle)


def set_bot_commands_for_all_scopes():
    """🤖 Telegram'ga rollar bo'yicha alohida menyularni yuboradi:
      • 👤 shaxsiy chat (hamma)        — user/private
      • 👤 guruhlar (hamma)            — user/group
      • 👮 guruh adminlari             — admin/group (o'yin-boshlash buyruqlari + oddiylari)
      • 👑 owner shaxsiy chati         — owner/private (barcha owner buyruqlari birinchi)
      • 👑 owner har bir guruhda       — owner/group
    Menyu faqat qulaylik; ruxsat har bir buyruqning o'zida server tomonda tekshiriladi."""
    def push(items, scope=None):
        cmds = [types.BotCommand(c, d) for c, d in items]
        if scope is None:
            bot.set_my_commands(commands=cmds)
        else:
            bot.set_my_commands(commands=cmds, scope=scope)
    jobs = [
        ("shaxsiy", build_command_menu("user", "private"), types.BotCommandScopeAllPrivateChats()),
        ("standart", build_command_menu("user", "private"), None),
        ("guruh", build_command_menu("user", "group"), types.BotCommandScopeAllGroupChats()),
        ("guruh adminlari", build_command_menu("admin", "group"), types.BotCommandScopeAllChatAdministrators()),
        ("owner", build_command_menu("owner", "private"), types.BotCommandScopeChat(chat_id=OWNER_ID_FROM_ENV)),
    ]
    for _sc in (types.BotCommandScopeAllPrivateChats(), types.BotCommandScopeAllGroupChats(),
                types.BotCommandScopeAllChatAdministrators(), types.BotCommandScopeChat(chat_id=OWNER_ID_FROM_ENV)):
        try:   # eski (v2 va undan oldingi) menyular qolib ketmasin
            bot.delete_my_commands(scope=_sc)
        except Exception:
            pass
    for name, items, scope in jobs:
        try:
            push(items, scope)
            _logger.info("buyruqlar menyusi o'rnatildi: %s (%d ta)", name, len(items))
        except Exception as e:
            _logger.warning("%s buyruqlar menyusini o'rnatishda xatolik: %s", name, e)
    threading.Thread(target=_set_owner_group_menus, daemon=True).start()


@bot.message_handler(commands=["versiya", "version"])
def cmd_versiya(message):
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    if is_owner(message.from_user.id):
        bot.send_message(message.chat.id, f"🏷 Ishlayotgan versiya: <b>{BOT_VERSION}</b>")


@bot.message_handler(commands=["menyu_yangila"])
def cmd_menyu_yangila(message):
    """🔄 Bot egasi — buyruqlar menyularini (foydalanuvchi / admin / owner) qo'lda qayta o'rnatadi."""
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    if not is_owner(message.from_user.id):
        return
    set_bot_commands_for_all_scopes()
    bot.send_message(message.chat.id, "✅ Buyruqlar menyusi qayta o'rnatildi: 👤 foydalanuvchi · 👮 guruh admini · 👑 owner.")


