def build_help_messages(is_admin=False, is_owner_user=False):
    """Rolga mos yordam xabarlari ro'yxati (har biri 4096 belgidan kichik)."""
    _vis = [(c, d) for c, d in _dedupe_cmds(USER_COMMANDS + HIDDEN_USER_COMMANDS) if c not in _HELP_HIDDEN]
    msgs = [_categorized_help("🆘 <b>Yordam — foydalanuvchi buyruqlari</b>", _HELP_CATEGORIES, _vis) +
            "\n\n💡 <i>Telegramda \"/\" belgisini bosganda menyuda eng kerakli buyruqlar chiqadi; to'liq ro'yxat shu yerda. "
            "Muqobil nomlar ham ishlaydi: " + ", ".join(f"/{a}" for a in sorted(COMMAND_ALIASES)
                                                         if COMMAND_ALIASES[a] in {c for c, _ in _vis}) + ".</i>"]
    if is_admin or is_owner_user:
        admin_items = _dedupe_cmds(ADMIN_COMMANDS + HIDDEN_ADMIN_COMMANDS)
        msgs.append("👮 <b>Guruh admini buyruqlari</b> (guruhda)\n" +
                    "\n".join(f"/{c} — {_html.escape(d, quote=False)}" for c, d in admin_items))
    if is_owner_user:
        msgs.append(_categorized_help("👑 <b>Owner buyruqlari</b> (faqat bot egasi)", _OWNER_HELP_CATEGORIES, OWNER_EXTRA_COMMANDS))
    out = []
    for m_ in msgs:   # xavfsizlik: 4096 dan oshsa qatorlar bo'yicha bo'ladi
        if len(m_) <= 3900:
            out.append(m_)
            continue
        cur_part = ""
        for line in m_.split("\n"):
            if len(cur_part) + len(line) + 1 > 3800 and cur_part:
                out.append(cur_part)
                cur_part = line
            else:
                cur_part = line if not cur_part else cur_part + "\n" + line
        if cur_part:
            out.append(cur_part)
    return out


def _build_help_text(show_admin_section):
    """Eski nom (moslik uchun) — birinchi (foydalanuvchi) xabarni qaytaradi."""
    return build_help_messages(is_admin=bool(show_admin_section))[0]


@bot.message_handler(commands=["yordam", "help"])
def cmd_yordam(message):
    """🆘 Rolga moslashgan to'liq buyruqlar ro'yxati."""
    maybe_capture_owner(message.from_user)
    try:
        is_group_admin = False
        if message.chat.type in ("group", "supergroup"):
            try:
                member = bot.get_chat_member(message.chat.id, message.from_user.id)
                is_group_admin = member.status in ("administrator", "creator")
            except Exception:
                is_group_admin = False
        owner_flag = is_owner(message.from_user.id)
        if owner_flag and message.chat.type != "private":
            # owner buyruqlari guruhda ko'rsatilmaydi (maxfiylik) — faqat shaxsiy chatda
            msgs = build_help_messages(is_admin=True, is_owner_user=False)
        else:
            msgs = build_help_messages(is_admin=is_group_admin or owner_flag, is_owner_user=owner_flag)
        for t in msgs:
            bot.send_message(message.chat.id, t)
    except Exception as e:
        notify_owner_of_error("cmd_yordam (/yordam)", e)
        bot.send_message(message.chat.id, "🆘 Yordam menyusini ko'rsatishda xatolik yuz berdi, birozdan so'ng qayta urinib ko'ring.")


def _owner_help_pages():
    """[(tugma_nomi, sahifa_matni)] — har bir bo'lim alohida SAHIFA (xabar uzunligi muammosiz)."""
    desc = dict(OWNER_EXTRA_COMMANDS)
    pages, used = [], set()
    for title, cmds in _OWNER_HELP_CATEGORIES:
        cmds = [c for c in cmds if c in desc]
        if not cmds:
            continue
        used.update(cmds)
        pages.append((title, f"{title}\n\n" + "\n".join(f"/{_html.escape(c, quote=False)} — {_html.escape(str(desc[c]), quote=False)}" for c in cmds)))
    rest = [c for c, _ in OWNER_EXTRA_COMMANDS if c not in used]
    if rest:
        extra = "\n".join(f"/{_html.escape(c, quote=False)} — {_html.escape(str(desc[c]), quote=False)}" for c in rest)
        if pages and pages[-1][0].endswith("Boshqa"):
            pages[-1] = (pages[-1][0], pages[-1][1] + "\n" + extra)
        else:
            pages.append(("🧩 Boshqa", "🧩 <b>Boshqa</b>\n\n" + extra))
    admin_items = _dedupe_cmds(ADMIN_COMMANDS + HIDDEN_ADMIN_COMMANDS)
    pages.append(("👮 Guruh admini", "👮 <b>Guruh admini buyruqlari</b> (guruhda)\n\n" +
                  "\n".join(f"/{c} — {_html.escape(d, quote=False)}" for c, d in admin_items)))
    out = []
    for name, text in pages:
        out.append((re.sub(r"</?b>", "", name), text if len(text) <= 3500 else text[:3500].rsplit("\n", 1)[0]))
    return out


def _owner_help_menu_kb(pages):
    kb = types.InlineKeyboardMarkup(row_width=2)
    kb.add(*[types.InlineKeyboardButton(name, callback_data=f"ownhelp|{i}") for i, (name, _t) in enumerate(pages)])
    return kb


