_KNOWN_COMMANDS = ({c.lower() for c, _ in USER_COMMANDS + HIDDEN_USER_COMMANDS + ADMIN_COMMANDS + HIDDEN_ADMIN_COMMANDS + OWNER_EXTRA_COMMANDS}
                   | set(COMMAND_ALIASES) | {"yordam", "help", "menyu_yangila"}
                   | {"inventar", "kuchlarim", "top", "balltop", "homiylar", "geroyim", "almazdokon", "ismuslubi", "ismrangi",
                      "olmos_coin", "elite", "klan", "turnir", "til", "taklif", "theron"})
# (fayl oxirida ro'yxatdan o'tgan BARCHA handlerlarning buyruqlari ham shu yerga qo'shiladi)


def _is_unknown_command(m):
    t = getattr(m, "text", None) or ""
    if not t.startswith("/"):
        return False
    parts = t[1:].split()
    if not parts:
        return False
    return parts[0].split("@")[0].lower() not in _KNOWN_COMMANDS


@bot.message_handler(func=_is_unknown_command)
def cmd_noma_lum_buyruq(message):
    """🙂 Notanish buyruq — o'chirilgan: endi hech qanday javob yubormaydi (jim qoladi)."""
    maybe_capture_owner(message.from_user)
    pass


# ================================================================================
#  💾 AVTOMATIK ZAXIRA NUSXA (#6) — har 24 soatda bir marta, o'z-o'zidan
#
#  Foydalanuvchilar bazasi + barcha o'yin holatlari (GAMES, shu jumladan
#  squad_mode/couple_mode rejimlari)
#  JSON qilib serverga saqlanadi VA bot egasining shaxsiy chatiga hujjat sifatida
#  yuboriladi — shunda server butunlay yo'qolib qolsa ham, sizda oxirgi 24 soatlik
#  zaxira nusxa Telegram'da saqlanib qoladi.
# ================================================================================

AUTO_BACKUP_INTERVAL = 24 * 60 * 60  # 24 soat
AUTO_BACKUP_PATH = "/tmp/hunter_mafia_auto_backup.json"


def check_heroes_table_integrity():
    """🛡 Backup paytida heroes jadvali BUTUNLIGINI tekshiradi:
    - hero_key HEROES lug'atida mavjud bo'lgan haqiqiy kalitmi
    - level 1..HERO_MAX_LEVEL oralig'idami
    - temp_until manfiy emasmi
    Qaytaradi: (jami_qator, muammoli_qatorlar_soni, muammolar_matni_ro'yxati)."""
    problems = []
    try:
        with db_lock:
            cur.execute("SELECT user_id, hero_key, level, temp_until FROM heroes")
            rows = cur.fetchall()
        for user_id, hero_key, level, temp_until in rows:
            if hero_key not in HEROES:
                problems.append(f"user_id={user_id}: noma'lum hero_key '{hero_key}'")
                continue
            if level is None or not (1 <= level <= HERO_MAX_LEVEL):
                problems.append(f"user_id={user_id} ({hero_key}): noto'g'ri level={level}")
            if temp_until is not None and temp_until < 0:
                problems.append(f"user_id={user_id} ({hero_key}): manfiy temp_until={temp_until}")
        return len(rows), len(problems), problems
    except Exception as e:
        log_hero_error("check_heroes_table_integrity", e)
        return 0, -1, [f"Tekshiruv bajarilmadi: {e}"]


def _send_db_snapshot():
    """💾 To'liq baza surati (HAMMA jadval: klan, juftlik, bozor, reyting va h.k.) —
    sqlite3 backup API bilan izchil nusxa, gzip qilinadi va egasiga yuboriladi.
    JSON zaxira faqat foydalanuvchi/geroylarni oladi; bu esa butun bazani saqlaydi."""
    import gzip, shutil, tempfile
    tmpdir = tempfile.mkdtemp(prefix="hm_snap_")
    raw = os.path.join(tmpdir, "hunter_mafia.db")
    gz = raw + ".gz"
    try:
        dst = sqlite3.connect(raw)
        try:
            with db_lock:
                conn.backup(dst)
        finally:
            dst.close()
        with open(raw, "rb") as fi, gzip.open(gz, "wb", compresslevel=6) as fo:
            shutil.copyfileobj(fi, fo)
        size_mb = os.path.getsize(gz) / 1048576
        if size_mb > 49:
            bot.send_message(OWNER_ID_FROM_ENV, f"⚠️ Baza surati {size_mb:.0f} MB — Telegram limiti (50 MB) dan katta, yuborilmadi. Railway diskidan oling.")
            return
        with open(gz, "rb") as f:
            bot.send_document(
                OWNER_ID_FROM_ENV, f, visible_file_name="hunter_mafia_" + time.strftime("%Y%m%d_%H%M") + ".db.gz",
                caption=(f"🗄 <b>To'liq baza surati</b> ({size_mb:.1f} MB)\n"
                         "<i>Tiklash: faylni ochib (.gz → .db), Railway'dagi hunter_mafia.db o'rniga qo'ying.</i>"),
            )
    except Exception as e:
        log_hero_error("_send_db_snapshot", e)
    finally:
        shutil.rmtree(tmpdir, ignore_errors=True)


def _run_auto_backup():
    try:
        with db_lock:
            cur.execute("SELECT * FROM users")
            user_rows = cur.fetchall()
            cur.execute("SELECT user_id, hero_key, level, acquired_at, temp_until FROM heroes")
            hero_rows = cur.fetchall()
            cur.execute("SELECT user_id, hero_key, ability_name, used_at FROM hero_ability_log")
            hero_log_rows = cur.fetchall()
        users_data = [dict(zip(USER_COLS, r)) for r in user_rows]
        heroes_data = [
            {"user_id": r[0], "hero_key": r[1], "level": r[2], "acquired_at": r[3], "temp_until": r[4]}
            for r in hero_rows
        ]
        hero_log_data = [
            {"user_id": r[0], "hero_key": r[1], "ability_name": r[2], "used_at": r[3]}
            for r in hero_log_rows
        ]
        backup_payload = {
            "backup_version": 2,
            "users": users_data,
            "heroes": heroes_data,
            "hero_ability_log": hero_log_data,
        }
        with open(AUTO_BACKUP_PATH, "w", encoding="utf-8") as f:
            json.dump(backup_payload, f, ensure_ascii=False, indent=2)

        # 🛡 heroes jadvali butunligini tekshirib, muammo bo'lsa captionda ogohlantirish beramiz
        total_heroes, bad_count, problems = check_heroes_table_integrity()
        integrity_line = f"🛡 Geroy jadvali: {total_heroes} ta yozuv, muammo: {bad_count if bad_count >= 0 else 'tekshirib bo\u2019lmadi'}"

        with open(AUTO_BACKUP_PATH, "rb") as f:
            bot.send_document(
                OWNER_ID_FROM_ENV, f,
                caption=(
                    f"💾 <b>Avtomatik zaxira nusxa</b>\n"
                    f"🕐 {time.strftime('%d.%m.%Y %H:%M')}\n"
                    f"👥 {len(users_data)} ta foydalanuvchi\n"
                    f"🏆 {len(heroes_data)} ta geroy, {len(hero_log_data)} ta mahorat-tarixi yozuvi\n"
                    f"{integrity_line}\n\n"
                    f"<i>Kerak bo'lsa, bu faylni /bazani_tikla orqali tiklashingiz mumkin.</i>"
                ),
            )
        _send_db_snapshot()
        if bad_count > 0:
            bot.send_message(
                OWNER_ID_FROM_ENV,
                "⚠️ <b>Geroy jadvalida muammoli yozuvlar topildi:</b>\n" + "\n".join(problems[:20])
                + (f"\n… va yana {bad_count - 20} ta" if bad_count > 20 else ""),
            )
    except Exception as e:
        _logger.warning("Avtomatik zaxira nusxa olishda xatolik: %s", e)
        log_hero_error("_run_auto_backup", e)
    finally:
        # ⏳ har doim o'zini qayta rejalashtiradi — botning butun umri davomida davom etadi
        t = threading.Timer(AUTO_BACKUP_INTERVAL, _run_auto_backup)
        t.daemon = True
        t.start()


def start_auto_backup_loop():
    """Bot ishga tushganda bir marta chaqiriladi — birinchi zaxira nusxani DARHOL
    emas, 5 daqiqadan keyin oladi (bot to'liq ishga tushib ulgursin deb), keyin
    esa har 24 soatda o'z-o'zini qayta ishga tushiradi."""
    t = threading.Timer(300, _run_auto_backup)  # birinchi safar — 5 daqiqadan keyin
    t.daemon = True
    t.start()


# ================================================================================
#  🩺 "MUZLAB QOLISH" (FREEZE) QAROVCHISI — WATCHDOG
#  Ba'zan (juda kam hollarda) bot tashqi sabab bilan — masalan barcha ishchi
#  threadlar to'xtab qolgan yoki tarmoq darajasida "yarim ochiq" ulanish qolib
#  ketgan hollarda — hech qanday xatolik chiqarmasdan shunchaki javob berishni
#  to'xtatib qo'yishi mumkin (haqiqiy "qotib qolish"). Bu holatni tashqi log orqali
#  emas, botning O'ZI payqab, holatni saqlab, O'ZINI avtomatik qayta ishga
#  tushiradi — foydalanuvchi yoki admin qo'lda serverga kirib restart qilishi shart
#  bo'lmaydi.
# ================================================================================
_WATCHDOG_INTERVAL = 300       # har 5 daqiqada bir marta tekshiradi
_WATCHDOG_MAX_FAILS = 3        # ketma-ket 3 marta (~15 daqiqa) javobsiz bo'lsa — qayta ishga tushadi


def _freeze_watchdog():
    fails = 0
    while True:
        time.sleep(_WATCHDOG_INTERVAL)
        try:
            bot.get_me()  # Telegram API bilan eng oddiy "tirikmisan?" so'rovi
            fails = 0
        except Exception as e:
            fails += 1
            _logger.warning("🩺 Watchdog: bot javob bermadi (%s/%s): %s", fails, _WATCHDOG_MAX_FAILS, e)
        if fails >= _WATCHDOG_MAX_FAILS:
            _logger.error("🚨 Watchdog: bot %s daqiqadan beri muzlab qolgan — o'zini qayta ishga tushirmoqda!",
                           (_WATCHDOG_INTERVAL * _WATCHDOG_MAX_FAILS) // 60)
            try:
                save_games_state()  # aktiv o'yinlar yo'qolib ketmasin
            except Exception:
                _logger.error("Watchdog: qayta ishga tushishdan oldin o'yin holati saqlanmadi", exc_info=True)
            try:
                conn.commit()
            except Exception:
                _logger.error("Watchdog: qayta ishga tushishdan oldin commit bajarilmadi", exc_info=True)
            # os.execv — jarayonni O'ZI, tashqi supervisor/systemd/Docker'ga
            # bog'liq bo'lmagan holda, bir zumda qayta ishga tushiradi.
            os.execv(sys.executable, [sys.executable] + sys.argv)


def start_freeze_watchdog():
    t = threading.Thread(target=_freeze_watchdog, daemon=True)
    t.start()


# ================================================================================
# 🩺 O'YIN BOSQICHI QOTIB QOLISHIGA QARSHI "SUG'URTA"
# Har bir bosqich (tun / muhokama / ovoz / osish tasdig'i) o'z taymeri bilan tugaydi. Agar biror
# kutilmagan sabab bilan taymer o'lib qolsa (yoki yo'qolsa) — o'yin abadiy qotib qolardi. Bu oqim
# har 15 soniyada tekshiradi: bosqich muddati 45 soniyadan ortiq o'tib ketgan, hech qaysi oqim
# o'yin qulfini ushlab turmagan bo'lsa — kerakli bosqich yakunlovchisini majburan ishga tushiradi.
# Bir muddat uchun faqat BIR marta urinadi (takroriy ishga tushish yo'q).
# ================================================================================
_STALL_CHECK_INTERVAL = 15
_STALL_GRACE_SECONDS = 45


def _stall_resolver_for(chat_id, game):
    """Qotib qolgan bosqichni davom ettiradigan funksiya (yoki None)."""
    if game.get("confirm_vote"):
        return resolve_hang_confirmation
    phase = game.get("phase")
    if phase == "night":
        return resolve_night
    if phase == "day":
        sub = game.get("day_sub_phase")
        if sub == "voting":
            return resolve_day
        if sub == "discussion":
            return open_day_voting
    return None


def _kick_stalled_games_once(now=None):
    """Qotib qolgan o'yinlar sonini qaytaradi (qaysi biri majburan davom ettirildi)."""
    now = now or time.time()
    kicked = 0
    for chat_id, game in list(GAMES.items()):
        try:
            deadline = game.get("phase_deadline")
            if not deadline or now < deadline + _STALL_GRACE_SECONDS:
                continue
            if game.get("_stall_kick_for") == deadline:
                continue   # shu muddat uchun allaqachon urinib ko'rilgan
            lock = _glock(chat_id)
            if not lock.acquire(blocking=False):
                continue   # boshqa oqim hozir shu o'yin ustida ishlayapti — qotib qolmagan
            lock.release()
            resolver = _stall_resolver_for(chat_id, game)
            if resolver is None:
                continue
            game["_stall_kick_for"] = deadline
            _logger.error("🩺 Qotib qolgan bosqich aniqlandi (chat=%s, bosqich=%s) — %s soniya kechikkan, majburan davom ettirilmoqda.",
                          chat_id, game.get("phase"), int(now - deadline))

            def _run(fn=resolver, cid=chat_id):
                try:
                    fn(cid)
                except Exception as exc:
                    notify_owner_of_error("qotgan bosqichni davom ettirish", exc)
            threading.Thread(target=_run, daemon=True, name=f"stallkick-{chat_id}").start()
            kicked += 1
        except Exception:
            _logger.warning("qotish tekshiruvida xato (chat=%s)", chat_id, exc_info=True)
    return kicked


def _game_stall_watchdog():
    while True:
        time.sleep(_STALL_CHECK_INTERVAL)
        _kick_stalled_games_once()


def start_game_stall_watchdog():
    threading.Thread(target=_game_stall_watchdog, daemon=True, name="stall-watchdog").start()


