# ------------------------------------------------------------------ 🆘 YORDAM (Mini App <-> bot egasi)
def _decode_photo(photo):
    """data:image/...;base64,XXXX → bytes (1 MB gacha) yoki None."""
    if not photo or not isinstance(photo, str):
        return None
    try:
        head, _, b64 = photo.partition(",")
        if not head.startswith("data:image/") or "base64" not in head:
            return None
        raw = base64.b64decode(b64, validate=True)
        return raw if 0 < len(raw) <= 1000000 else None
    except Exception:
        return None


def support_send(uid, name, text, photo=None):
    """Foydalanuvchi xabarini saqlaydi va bot egasiga yuboradi. (ok, xato_matni)"""
    text = (text or "").strip()
    photo_bytes = _decode_photo(photo)
    if photo and photo_bytes is None:
        return False, "Rasm yaroqsiz yoki 1 MB dan katta."
    if not text and photo_bytes:
        text = "📷 Rasm"
    if not text:
        return False, "Xabar bo'sh."
    if len(text) > 1000:
        return False, "Xabar juda uzun (1000 belgigacha)."
    if not _rate_ok(uid, "support", 5, 60):
        return False, "Juda tez yozyapsiz — bir daqiqadan keyin urinib ko'ring."
    with db_lock:
        cur.execute("INSERT INTO support_msgs (user_id, direction, text, ts) VALUES (?, 'in', ?, ?)",
                    (uid, text, time.time()))
        conn.commit()
    owner = _owner_uid()
    if owner:
        note = (f"🆘 <b>Yordam so'rovi</b>\n👤 {mention(uid, name or 'Foydalanuvchi')}  (ID: <code>{uid}</code>)\n\n"
                f"{esc(text)}\n\n↩️ Javob: <code>/javob {uid} matn</code>")
        if photo_bytes:
            try:
                bot.send_photo(owner, io.BytesIO(photo_bytes), caption=note)
            except Exception:
                safe_send(owner, note)
        else:
            safe_send(owner, note)
    return True, ""


def support_thread(uid, limit=40):
    with db_lock:
        cur.execute("SELECT direction, text, ts FROM support_msgs WHERE user_id=? ORDER BY id DESC LIMIT ?", (uid, limit))
        rows = cur.fetchall()
    return [{"from": "me" if d == "in" else "operator", "text": t,
             "time": time.strftime("%H:%M", time.localtime(ts))} for d, t, ts in reversed(rows)]


@bot.message_handler(commands=["javob"])
def cmd_javob(message):
    """🆘 FAQAT bot egasi: /javob <user_id> <matn> — foydalanuvchining yordam so'roviga javob."""
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    if not is_owner(message.from_user.id):
        return
    parts = (message.text or "").split(maxsplit=2)
    if len(parts) < 3 or not parts[1].lstrip("-").isdigit():
        bot.send_message(message.chat.id, "❌ Foydalanish: <code>/javob 123456789 Javob matni</code>")
        return
    target, reply = int(parts[1]), parts[2].strip()
    with db_lock:
        cur.execute("INSERT INTO support_msgs (user_id, direction, text, ts) VALUES (?, 'out', ?, ?)",
                    (target, reply[:1000], time.time()))
        conn.commit()
    ok = safe_send(target, f"🆘 <b>Yordam xizmati javobi:</b>\n\n{esc(reply)}")
    bot.send_message(message.chat.id, "✅ Javob yuborildi." if ok else "⚠️ Saqlandi, lekin foydalanuvchiga yuborib bo'lmadi (bot bloklangan bo'lishi mumkin) — Mini App'da ko'radi.")


@bot.message_handler(commands=["yangilik"])
def cmd_yangilik(message):
    """📢 FAQAT bot egasi: /yangilik Sarlavha | tavsif — Mini App'dagi bildirishnomalarga yangilik qo'shadi."""
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    if not is_owner(message.from_user.id):
        return
    raw = (message.text or "").split(maxsplit=1)
    if len(raw) < 2 or not raw[1].strip():
        bot.send_message(message.chat.id, "❌ Foydalanish: <code>/yangilik Sarlavha | tavsif</code>")
        return
    title, _, desc = raw[1].partition("|")
    news_add(title.strip(), desc.strip())
    bot.send_message(message.chat.id, "✅ Yangilik qo'shildi.")


