def _hw2_profile(uid):
    now=time.time()
    with db_lock:
        cur.execute('SELECT * FROM hunter_world2_profiles WHERE user_id=?',(uid,))
        r=cur.fetchone()
        if not r:
            idx=abs(int(uid)) % len(_HW2_ORIGINS)
            origin,title,arch=_HW2_ORIGINS[idx]
            name=(user_dict(uid).get('name') or 'Hunter')[:40]
            cur.execute('INSERT INTO hunter_world2_profiles(user_id,character_name,origin,title,archetype,created_at,updated_at) VALUES(?,?,?,?,?,?,?)',
                        (uid,name,origin,title,arch,now,now))
            conn.commit()
            cur.execute('SELECT * FROM hunter_world2_profiles WHERE user_id=?',(uid,))
            r=cur.fetchone()
    cols=[d[1] for d in cur.description]
    return dict(zip(cols,r))

def _hw2_save(uid, **changes):
    if not changes: return _hw2_profile(uid)
    changes['updated_at']=time.time()
    sets=', '.join(f'{_sql_ident(k, _HW2_PROFILE_COLUMNS)}=?' for k in changes)
    vals=list(changes.values())+[uid]
    with db_lock:
        cur.execute(f'UPDATE hunter_world2_profiles SET {sets} WHERE user_id=?',vals)
        conn.commit()
    return _hw2_profile(uid)

def _hw2_log(uid, kind, key, text, xp=0, fate=0):
    with db_lock:
        cur.execute('INSERT INTO hunter_world2_events(user_id,kind,event_key,text,reward_xp,reward_fate,created_at) VALUES(?,?,?,?,?,?,?)',
                    (uid,kind,key,text,xp,fate,time.time()))
        conn.commit()

def _hw2_level(xp):
    return max(1, 1 + int(xp // 100))

def _hunter_world_game_result(uid, won, role, chat_id):
    """Bridge a completed Mafia match into Hunter World progression."""
    try:
        p = _hw2_profile(uid)
        xp = 30 if won else 12
        fate = 2 if won else 1
        outcome = "g‘alaba" if won else "mag‘lubiyat"
        path = p.get('path') or 'Kuzatuvchi'
        if won and path == 'Kuzatuvchi': path = 'Ovchi'
        elif (not won) and path == 'Ovchi': path = 'Kuzatuvchi'
        nx = int(p.get('xp') or 0) + xp
        nf = int(p.get('fate') or 0) + fate
        nl = _hw2_level(nx)
        chapter = min(10, max(1, 1 + nl // 3))
        _hw2_save(uid, xp=nx, fate=nf, level=nl, path=path, chapter=chapter, season_score=int(p.get('season_score') or 0)+xp)
        cp=_character_progress(uid, xp=xp, destiny=fate)
        if cp and cp.get('leveled_up'):
            _hw2_legacy(uid,'level_up',f'Level {cp["level"]}: yangi bosqich',f'{outcome.capitalize()} orqali qahramon yangi darajaga ko‘tarildi.')
        with db_lock:
            cur.execute('UPDATE hunter_world2_quests SET progress=MIN(goal,progress+1) WHERE user_id=? AND quest_key IN (?,?)', (uid,'first_step','fate_reader'))
            conn.commit()
        _hw2_log(uid, 'mafia', f'game:{chat_id}', f'Mafia {outcome}: {role or "Noma’lum"}. World yo‘ling davom etdi.', xp, fate)
        # O‘yin natijasi faction reputatsiyasiga ham ta’sir qiladi.
        rtxt=(role or '').lower()
        if any(x in rtxt for x in ('mafia','don','killer','godfather')):
            fk='shadow_court'
        elif any(x in rtxt for x in ('doctor','commissioner','sheriff','police')):
            fk='emerald_guard'
        elif any(x in rtxt for x in ('seer','oracle','medium')):
            fk='star_seers'
        else:
            fk='free_hunters'
        _hw2_change_faction(uid, fk, 3 if won else 1)
        territory_result=_hw2_territory_influence(uid, bool(won))
        if territory_result and territory_result.get('captured'):
            _hw2_legacy(uid,'territory','Hudud qo‘lga olindi',f'Mafia {outcome} natijasida klan ta’siri yetarli bo‘lib, {territory_result["captured"]} hududi o‘zgardi.')
        return True
    except Exception:
        _logger.exception('Hunter World game bridge failed for %s', uid)
        return False


def _hw2_quests(uid, profile):
    with db_lock:
        for key,(_title,_desc,goal,_xp,_fate) in _HW2_QUESTS.items():
            cur.execute('INSERT OR IGNORE INTO hunter_world2_quests(user_id,quest_key,progress,goal,claimed) VALUES(?,?,?,?,0)',(uid,key,0,goal))
        cur.execute('SELECT quest_key,progress,goal,claimed FROM hunter_world2_quests WHERE user_id=?',(uid,))
        rows=cur.fetchall()
    out=[]
    for key,progress,goal,claimed in rows:
        title,desc,qgoal,qxp,qfate=_HW2_QUESTS.get(key,(key,key,goal,20,1))
        out.append({'key':key,'title':title,'description':desc,'progress':min(progress,qgoal),'goal':qgoal,
                    'xp':qxp,'fate':qfate,'claimed':bool(claimed),'ready':progress>=qgoal and not claimed})
    return out

def _hw2_feed(uid, kind, title, text):
    with db_lock:
        cur.execute('INSERT INTO hunter_world2_feed(user_id,kind,title,text,created_at) VALUES(?,?,?,?,?)',(uid,kind,title,text,time.time())); conn.commit()

def _hw2_legacy(uid, kind, title, text):
    with db_lock:
        cur.execute('INSERT INTO hunter_world2_legacy(user_id,kind,title,text,created_at) VALUES(?,?,?,?,?)',
                    (uid,kind,title,text,time.time()))
        conn.commit()
    _hw2_feed(uid,kind,title,text)

def _hw2_season_board(uid, limit=10):
    with db_lock:
        cur.execute('SELECT user_id,character_name,season_score FROM hunter_world2_profiles ORDER BY season_score DESC, updated_at ASC LIMIT ?', (limit,))
        rows=cur.fetchall()
    return [{'user_id':int(r[0]),'name':r[1],'score':int(r[2] or 0),'me':int(r[0])==int(uid)} for r in rows]

def _hw2_world_summary(uid):
    with db_lock:
        cur.execute('SELECT COUNT(*) FROM hunter_world2_profiles'); players=int(cur.fetchone()[0] or 0)
        cur.execute('SELECT COUNT(*) FROM hunter_world2_events WHERE user_id=?',(uid,)); events=int(cur.fetchone()[0] or 0)
        cur.execute('SELECT COUNT(*) FROM hunter_world2_quests WHERE user_id=? AND claimed=1',(uid,)); claimed=int(cur.fetchone()[0] or 0)
        cur.execute('SELECT COUNT(*) FROM territories WHERE owner_id=?',(uid,)); personal_territories=int(cur.fetchone()[0] or 0)
    return {'players':players,'events':events,'quests_claimed':claimed,'personal_territories':personal_territories}

_HW2_FACTIONS={'emerald_guard':('Zumrad qo‘riqchilari','Tartib va himoya','🛡️'),'shadow_court':('Soya kengashi','Sir va yashirin yo‘llar','🌑'),'star_seers':('Yulduz ko‘ruvchilari','Taqdir va signal','🔮'),'free_hunters':('Erkin ovchilar','Mustaqillik va jasorat','🏹')}
_HW2_NPC_REL_DEFAULTS={'Liora':(8,2,0,6),'Kael':(3,8,2,2)}
_HW2_QUEST_CHAIN={'first_hunt':[('start','Izni tanla','Tumanli darvozadagi izni kuzat','neutral',20,1),('ally','Ittifoqchi tanla','Liora yoki Kael yo‘lini och','trust',35,2),('gate','Darvoza','Olingan ishonch bilan yopiq darvozani och','faction',60,3),('legacy','Meros','Qaroringni xronikaga muhrla','legacy',90,4)]}

def _hw2_factions(uid):
    with db_lock:
        for k in _HW2_FACTIONS: cur.execute('INSERT OR IGNORE INTO hunter_world2_factions(user_id,faction_key,reputation,updated_at) VALUES(?,?,0,?)',(uid,k,time.time()))
        cur.execute('SELECT faction_key,reputation FROM hunter_world2_factions WHERE user_id=?',(uid,)); rows=cur.fetchall()
    return [{'key':k,'name':_HW2_FACTIONS[k][0],'desc':_HW2_FACTIONS[k][1],'icon':_HW2_FACTIONS[k][2],'reputation':int(r)} for k,r in rows]

def _hw2_change_faction(uid,key,delta):
    if key not in _HW2_FACTIONS:return
    with db_lock:
        cur.execute('INSERT OR IGNORE INTO hunter_world2_factions(user_id,faction_key,reputation,updated_at) VALUES(?,?,0,?)',(uid,key,time.time()))
        cur.execute('UPDATE hunter_world2_factions SET reputation=MAX(-100,MIN(100,reputation+?)),updated_at=? WHERE user_id=? AND faction_key=?',(int(delta),time.time(),uid,key)); conn.commit()

def _hw2_npc_rel(uid,npc):
    vals=_HW2_NPC_REL_DEFAULTS.get(npc,(0,0,0,0))
    with db_lock:
        cur.execute('INSERT OR IGNORE INTO hunter_world2_npc_rel(user_id,npc_key,trust,respect,fear,loyalty,updated_at) VALUES(?,?,?,?,?,?,?)',(uid,npc,*vals,time.time()))
        cur.execute('SELECT trust,respect,fear,loyalty FROM hunter_world2_npc_rel WHERE user_id=? AND npc_key=?',(uid,npc)); r=cur.fetchone()
    return {'npc':npc,'trust':int(r[0]),'respect':int(r[1]),'fear':int(r[2]),'loyalty':int(r[3])}

def _hw2_change_npc_rel(uid,npc,**delta):
    _hw2_npc_rel(uid,npc); a={k:int(delta.get(k,0)) for k in ('trust','respect','fear','loyalty')}
    with db_lock:
        cur.execute('UPDATE hunter_world2_npc_rel SET trust=MAX(0,MIN(100,trust+?)),respect=MAX(0,MIN(100,respect+?)),fear=MAX(0,MIN(100,fear+?)),loyalty=MAX(0,MIN(100,loyalty+?)),updated_at=? WHERE user_id=? AND npc_key=?',(a['trust'],a['respect'],a['fear'],a['loyalty'],time.time(),uid,npc)); conn.commit()
    return _hw2_npc_rel(uid,npc)

def _hw2_chain(uid,key='first_hunt'):
    steps=_HW2_QUEST_CHAIN[key]
    with db_lock:
        cur.execute("INSERT OR IGNORE INTO hunter_world2_quest_chain(user_id,chain_key,step,branch,completed,updated_at) VALUES(?,?,0,'neutral',0,?)",(uid,key,time.time()))
        cur.execute('SELECT step,branch,completed FROM hunter_world2_quest_chain WHERE user_id=? AND chain_key=?',(uid,key)); r=cur.fetchone()
    step,branch,done=int(r[0]),r[1],bool(r[2])
    return {'key':key,'step':step,'branch':branch,'completed':done,'steps':[{'key':x[0],'title':x[1],'text':x[2],'branch':x[3],'xp':x[4],'fate':x[5],'active':i==step and not done,'done':i<step or done} for i,x in enumerate(steps)]}

def _hw2_chain_advance(uid,key,choice):
    c=_hw2_chain(uid,key); steps=_HW2_QUEST_CHAIN[key]; step=c['step']
    if c['completed']: return False,'Quest zanjiri yakunlangan.'
    branch=c['branch']
    if step==0: branch='guard' if choice=='protect' else 'shadow' if choice=='betray' else 'seer'
    elif step==1: branch='liora' if choice=='liora' else 'kael'
    xp,fate=steps[step][4],steps[step][5]; p=_hw2_profile(uid); nx=p['xp']+xp
    _hw2_save(uid,xp=nx,fate=p['fate']+fate,level=_hw2_level(nx),season_score=p['season_score']+xp)
    done=step+1>=len(steps)
    with db_lock:
        cur.execute('UPDATE hunter_world2_quest_chain SET step=?,branch=?,completed=?,updated_at=? WHERE user_id=? AND chain_key=?',(step+1,branch,int(done),time.time(),uid,key)); conn.commit()
    _hw2_log(uid,'quest_chain',f'{key}:{step}',steps[step][1],xp,fate)
    _hw2_feed(uid,'quest_chain','Quest zanjiri',f'{steps[step][1]} — yo‘l: {branch}')
    if done:_hw2_legacy(uid,'quest_chain','Meros muhrlandi',f'Quest zanjiri {branch} yo‘li bilan yakunlandi.')
    return True,'Quest zanjiri davom etdi.'

def world23_chain(uid, choice):
    c=_hw2_chain(uid,'first_hunt')
    if c['completed']: return False,'Quest zanjiri allaqachon yakunlangan.',world23_state(uid)
    step=int(c['step'])
    allowed={0:{'observe','hunt','protect','betray'},1:{'liora','kael'},2:{'open','wait'},3:{'seal','leave'}}
    if step >= len(_HW2_QUEST_CHAIN['first_hunt']):
        return False,'Quest zanjiri bosqichi topilmadi.',world23_state(uid)
    if choice not in allowed.get(step,set()):
        return False,'Bu bosqich uchun tanlov mavjud emas.',world23_state(uid)
    ok,msg=_hw2_chain_advance(uid,'first_hunt',choice)
    return ok,msg,world23_state(uid)

def _hw2_territory_influence(uid,won):
    owner=find_member_clan(uid)
    if not owner:return None
    delta=2 if won else 1
    with db_lock:
        cur.execute('INSERT OR IGNORE INTO hunter_world2_territory_influence(owner_id,points,updated_at) VALUES(?,?,?)',(owner,0,time.time()))
        cur.execute('UPDATE hunter_world2_territory_influence SET points=points+?,updated_at=? WHERE owner_id=?',(delta,time.time(),owner))
        cur.execute('SELECT points FROM hunter_world2_territory_influence WHERE owner_id=?',(owner,)); pts=int(cur.fetchone()[0])
    if pts<10:return {'clan_id':owner,'points':pts,'captured':None}
    with db_lock: cur.execute('UPDATE hunter_world2_territory_influence SET points=points-10 WHERE owner_id=?',(owner,)); conn.commit()
    land=None
    try: land=v10_capture_territory(owner,None)
    except Exception: pass
    if land:
        _hw2_legacy(uid,'territory','Dunyo hududi o‘zgardi',f'{land} endi klan ta’sirida.')
        _hw2_log(uid,'territory','capture',f'{land} hududi klan ta’siri orqali o‘zgardi.',15,1)
    return {'clan_id':owner,'points':0,'captured':land}

def _hw2_clan_control(uid):
    owner=find_member_clan(uid)
    if not owner:return {'member':False,'clan_id':None,'name':'','points':0,'threshold':10,'progress':0,'territories':0}
    with db_lock:
        cur.execute('SELECT points FROM hunter_world2_territory_influence WHERE owner_id=?',(owner,)); r=cur.fetchone(); pts=int(r[0] if r else 0)
        cur.execute('SELECT COUNT(*) FROM territories WHERE owner_id=?',(owner,)); terr=int(cur.fetchone()[0] or 0)
    try:
        cl=get_clan(owner); name=cl.get('name') if isinstance(cl,dict) else 'Clan'
    except Exception: name='Clan'
    return {'member':True,'clan_id':owner,'name':name or 'Clan','points':pts,'threshold':10,'progress':min(100,pts*10),'territories':terr}

def world23_state(uid):
    """Hunter World FINAL state: identity -> story -> living world -> progression.
    One response contains everything the Mini App needs, while keeping rewards in XP/Fate
    rather than pay-to-win combat power.
    """
    p=_hw2_profile(uid)
    level=_hw2_level(p['xp'])
    rarity='Legendary' if level>=20 else 'Mythic' if level>=10 else 'Epic' if level>=5 else 'Starter'
    if rarity != p['rarity']:
        p=_hw2_save(uid, rarity=rarity, level=level)

    trait=_character_trait(uid)
    with db_lock:
        cur.execute('SELECT kind,event_key,text,reward_xp,reward_fate,created_at FROM hunter_world2_events WHERE user_id=? ORDER BY id DESC LIMIT 20',(uid,))
        erows=cur.fetchall()
    events=[{'kind':k,'key':key,'text':txt,'xp':xp,'fate':fate,'time':time.strftime('%d.%m %H:%M',time.localtime(ts))} for k,key,txt,xp,fate,ts in reversed(erows)]
    quests=_hw2_quests(uid,p)
    try:
        u=user_dict(uid); games=int(u.get('games',0) or 0); wins=int(u.get('wins',0) or 0); winrate=round(wins/games*100,1) if games else 0
    except Exception:
        games=wins=0; winrate=0

    # Descriptive achievements: they unlock story/cosmetic presentation, not raw combat power.
    ach_defs=[
        ('first_game','Birinchi ov','Birinchi Mafia o‘yinini tugat',games>=1,'🎮'),
        ('first_choice','Birinchi tanlov','Taqdir yo‘lida qaror qil',any(e['kind']=='choice' for e in events),'🌌'),
        ('npc_friend','Ishonch urug‘i','NPC bilan aloqa qil',int(p['npc_trust'] or 0)>=12,'🤝'),
        ('survivor','Omon qoluvchi','10 ta o‘yinga yet',games>=10,'🛡️'),
        ('winner','Ovchi g‘olib','5 ta g‘alabaga yet',wins>=5,'🏆'),
        ('mythic','Afsona uyg‘ondi','World Level 10 ga yet',level>=10,'☄️'),
    ]
    ach_items=[{'key':k,'name':n,'description':d,'unlocked':ok,'icon':ic} for k,n,d,ok,ic in ach_defs]
    unlocked=sum(1 for x in ach_items if x['unlocked'])

    # A deterministic daily scene makes the world feel alive without external AI.
    day=time.strftime('%Y-%m-%d',time.localtime())
    scenes=[
        ('Tumanli darvoza','Qal’a darvozasida noma’lum iz paydo bo‘ldi.','Izni kuzatish',20,1),
        ('Yo‘qolgan signal','Yulduz portidan qisqa signal keldi.','Signalni tekshirish',25,1),
        ('Soya savdosi','Bozor ostida sirli savdogar paydo bo‘ldi.','Bitimni kuzatish',20,2),
        ('Qora sham','Qora sham yonib, eski xronikani uyg‘otdi.','Xronikani ochish',30,2),
        ('Tungi kuzatuv','Shahar tomlarida kimdir seni kuzatmoqda.','Kuzatuvchini topish',25,1),
    ]
    scene=scenes[(abs(int(uid))+sum(map(ord,day)))%len(scenes)]
    claimed=any(e['kind']=='daily' and e['key']==day for e in events)
    daily_event={'day':day,'title':scene[0],'text':scene[1],'task':scene[2],'xp':scene[3],'fate':scene[4],'claimed':claimed}

    npc_name='Liora' if p['chapter']<3 else 'Kael'
    rel=_hw2_npc_rel(uid,npc_name)
    if rel['trust']>=60 and rel['loyalty']>=30:
        npc_text=f'{npc_name} seni yaqin ittifoqchi deb biladi. Yashirin yo‘l ochildi.'
    elif rel['respect']>=35:
        npc_text=f'{npc_name} qarorlaringni jiddiy qabul qilmoqda. Keyingi sinov qattiqroq bo‘ladi.'
    elif rel['fear']>=35:
        npc_text=f'{npc_name} ehtiyotkor gapirmoqda. U sendan nimanidir yashiryapti.'
    elif p['npc_choice']:
        npc_text='Oldingi tanloving hali ham uning munosabatida aks etmoqda.'
    else:
        npc_text='Taqdir yo‘li seni kutmoqda.'
    npc_choices=[{'key':'trust','label':'🤝 Ishonchni tanlash'},{'key':'secret','label':'🔐 Sirni ochish'},{'key':'challenge','label':'⚔️ Sinovga kirish'}]
    season_days=30-(int(time.strftime('%j',time.localtime()))%30)

    # Clan context is intentionally descriptive; clan power remains governed by the existing clan system.
    clan_war={'member':False,'name':'','power':0,'wins':0,'losses':0}
    try:
        cl=find_member_clan(uid)
        if cl:
            cname=cl.get('name') if isinstance(cl,dict) else (cl[1] if len(cl)>1 else 'Clan')
            clan_war.update({'member':True,'name':cname or 'Clan'})
    except Exception: pass

    story_choices=[{'key':k,'label':v[0],'text':v[1],'xp':v[2],'fate':v[3]} for k,v in _HW2_CHOICES.items()]
    character={
        'character_name':p['character_name'],'origin':p['origin'],'title':p['title'],'path':p['path'],
        'level':p['level'],'xp':p['xp'],'fate':p['fate'],'fate_points':p['fate'],
        'rarity':p['rarity'],'weapon':p['weapon'],'aura':p['aura'],'archetype':p['archetype'],
        'temperament':trait['temperament'],'skill_key':trait['skill_key'],'skill_name':trait['skill_name'],
        'skill_text':trait['skill_text'],'character_level':int(0),'character_xp':0,'destiny_points':0,
    }
    with db_lock:
        cur.execute('SELECT character_level,character_xp,destiny_points,starter_done FROM hunter_character_identity WHERE user_id=?',(uid,)); cr=cur.fetchone()
    if cr:
        character['character_level'],character['character_xp'],character['destiny_points']=int(cr[0] or 1),int(cr[1] or 0),int(cr[2] or 0)
        character['starter_done']=bool(cr[3])

    chronicle=events
    story_text=events[-1]['text'] if events else 'Birinchi eshik ochildi. Taqdiringni o‘zing yozasan.'
    role_evolution=[]
    if games:
        role_evolution=[{'role':'Hunter','evolution':'Afsona' if wins>=20 else 'Prime' if wins>=10 else 'Usta' if wins>=3 else 'Boshlovchi','level':max(1,min(20,1+wins//3)),'games':games,'wins':wins,'xp':wins*25+games*5}]
    character_journey=_character_after_select(uid,_avatar_user(uid))
    board=_hw2_season_board(uid,10)
    with db_lock:
        cur.execute('SELECT kind,title,text,created_at FROM hunter_world2_legacy WHERE user_id=? ORDER BY id DESC LIMIT 8',(uid,))
        lrows=cur.fetchall()
        cur.execute('SELECT id,name,owner_id,captured_at FROM territories ORDER BY id LIMIT 24')
        trows=cur.fetchall()
    legacy=[{'kind':r[0],'title':r[1],'text':r[2],'time':time.strftime('%d.%m %H:%M',time.localtime(r[3]))} for r in lrows]
    world_map=[]
    for tid,tname,owner_id,captured_at in trows:
        owner='Siz' if owner_id==uid else None
        if owner_id and owner_id!=uid:
            try:
                cl=get_clan(owner_id); owner=cl.get('name') if isinstance(cl,dict) else 'Boshqa Hunter'
            except Exception: owner='Boshqa Hunter'
        world_map.append({'id':tid,'name':tname,'owner':owner,'owned':owner_id==uid,'captured_at':captured_at})
    summary=_hw2_world_summary(uid)
    clan_control=_hw2_clan_control(uid)
    with db_lock:
        cur.execute('SELECT kind,title,text,created_at FROM hunter_world2_feed WHERE user_id=? ORDER BY id DESC LIMIT 10',(uid,)); frows=cur.fetchall()
    world_feed=[{'kind':r[0],'title':r[1],'text':r[2],'time':time.strftime('%d.%m %H:%M',time.localtime(r[3]))} for r in frows]
    effects=[]
    reps={f['key']:f['reputation'] for f in _hw2_factions(uid)}
    if max(reps.values() or [0])>=25: effects.append({'type':'faction','text':'25+ reputatsiya: maxsus fraksiya dialogi ochildi'})
    if rel['trust']>=30: effects.append({'type':'npc','text':f'{npc_name} ishonchi 30+: qo‘shimcha suhbat yo‘li ochildi'})
    if legacy: effects.append({'type':'legacy','text':'Meros saqlangan: keyingi sahnalar oldingi qarorlarni hisobga oladi'})
    if not effects: effects=[{'type':'world','text':'Muhim qarorlar keyingi hikoyaga ta’sir qiladi'}]
    return {
        'character':character,
        'character_journey':character_journey,
        'story':{'chapter':p['chapter'],'chapter_title':p['title'],'text':story_text,'choices':story_choices},
        'destiny':{'points':p['fate'],'path':p['path'],'choices':story_choices},
        'daily_event':daily_event,'quests':quests,'achievements':{'unlocked':unlocked,'total':len(ach_items),'items':ach_items},
        'chronicle':chronicle,'events':events,'stats':{'games':games,'wins':wins,'winrate':winrate},
        'npc':{'name':npc_name,'trust':p['npc_trust'],'text':npc_text,'choices':npc_choices,'day':day},
        'npc_story':{'name':npc_name,'chapter':p['chapter'],'trust':p['npc_trust'],'text':npc_text,'choices':npc_choices},
        'story_quests':quests,
        'role_evolution':role_evolution,
        'season':{'key':'S001','name':'Hunter Season · Living World','score':p['season_score'],'days_left':season_days},
        'season_score':p['season_score'],'season_leaderboard':[],
        'clan_war':clan_war,'loadout':json.loads(p['loadout'] or '{}'),
        'season_leaderboard':board,
        'legacy':legacy,
        'world_map':world_map,
        'world_summary':summary,
        'clan_control':clan_control,
        'world_feed':world_feed,
        'factions':_hw2_factions(uid),
        'npc_relationships':[_hw2_npc_rel(uid,'Liora'),_hw2_npc_rel(uid,'Kael')],
        'quest_chain':_hw2_chain(uid),
        'legacy_effects':effects,
    }

def world2_choice(uid,key):
    if key not in _HW2_CHOICES: return False,'Bunday taqdir tanlovi yo‘q.',world23_state(uid)
    label,text,xp,fate,path=_HW2_CHOICES[key]
    p=_hw2_profile(uid)
    nx=p['xp']+xp; nf=p['fate']+fate; lvl=_hw2_level(nx); chapter=min(12,1+nx//120)
    _hw2_save(uid,xp=nx,fate=nf,level=lvl,path=path,chapter=chapter,season_score=p['season_score']+xp)
    _character_progress(uid,xp=xp,destiny=fate)
    _hw2_log(uid,'choice',key,text,xp,fate)
    _hw2_feed(uid,'choice','Taqdir tanlovi',text)
    with db_lock:
        cur.execute('UPDATE hunter_world2_quests SET progress=MIN(goal,progress+1) WHERE user_id=? AND quest_key="first_step"',(uid,))
        conn.commit()
    return True,'Taqdir o‘zgardi.',world23_state(uid)

def world23_npc(uid,key):
    if key not in _HW2_NPC:return False,'NPC bu tanlovni tanimadi.',world23_state(uid)
    name,text,trust=_HW2_NPC[key]; p=_hw2_profile(uid)
    if key=='trust': rel=_hw2_change_npc_rel(uid,'Liora',trust=trust,respect=2,loyalty=4); _hw2_change_faction(uid,'emerald_guard',4); chain='liora'
    elif key=='secret': rel=_hw2_change_npc_rel(uid,'Liora',trust=trust,respect=1,loyalty=6); _hw2_change_faction(uid,'star_seers',5); chain='liora'
    else: rel=_hw2_change_npc_rel(uid,'Kael',trust=3,respect=trust,loyalty=2); _hw2_change_faction(uid,'free_hunters',5); chain='kael'
    if rel['trust']>=30:text+=' Ishonch kuchaydi: qo‘shimcha dialog yo‘li ochildi.'
    _hw2_save(uid,npc_choice=key,npc_trust=min(100,p['npc_trust']+trust),season_score=p['season_score']+trust); _character_progress(uid,xp=10,destiny=1); _hw2_log(uid,'npc',key,text,10,1)
    with db_lock: cur.execute('UPDATE hunter_world2_quests SET progress=MIN(goal,progress+1) WHERE user_id=? AND quest_key="living_world"',(uid,)); conn.commit()
    _hw2_chain_advance(uid,'first_hunt',chain)
    _hw2_feed(uid,'npc','NPC qarori',text)
    return True,'Hikoya yo‘li o‘zgardi.',world23_state(uid)

def world23_quest(uid,key):
    if key not in _HW2_QUESTS: return False,'Quest topilmadi.',world23_state(uid)
    title,desc,goal,xp,fate=_HW2_QUESTS[key]
    with db_lock:
        cur.execute('SELECT progress,claimed FROM hunter_world2_quests WHERE user_id=? AND quest_key=?',(uid,key)); r=cur.fetchone()
        if not r: return False,'Quest hali yaratilmagan.',world23_state(uid)
        if r[1]: return False,'Quest mukofoti allaqachon olingan.',world23_state(uid)
        if r[0] < goal: return False,'Quest hali tayyor emas.',world23_state(uid)
        cur.execute('UPDATE hunter_world2_quests SET claimed=1 WHERE user_id=? AND quest_key=?',(uid,key)); conn.commit()
    p=_hw2_profile(uid); _hw2_save(uid,xp=p['xp']+xp,fate=p['fate']+fate,level=_hw2_level(p['xp']+xp),season_score=p['season_score']+xp)
    _character_progress(uid,xp=xp,destiny=fate)
    _hw2_log(uid,'quest',key,f'{title}: mukofot olindi',xp,fate)
    return True,'Quest mukofoti olindi.',world23_state(uid)

def world21_event(uid):
    p=_hw2_profile(uid); xp=20; fate=1
    _hw2_save(uid,xp=p['xp']+xp,fate=p['fate']+fate,level=_hw2_level(p['xp']+xp),season_score=p['season_score']+xp)
    _character_progress(uid,xp=xp,destiny=fate)
    _hw2_log(uid,'event','daily', 'Living World voqeasi bajarildi.',xp,fate)
    return True,'Event bajarildi.',world23_state(uid)

def world21_equip(uid,kind,value):
    p=_hw2_profile(uid); loadout=json.loads(p['loadout'] or '{}'); loadout[str(kind)]=str(value)
    _hw2_save(uid,loadout=json.dumps(loadout,ensure_ascii=False))
    return True,'Loadout yangilandi.',world23_state(uid)

def world_state(uid):
    """🌍 Mini App uchun: Hunter World — hudud xaritasi, afsonalar, taqdir, kartalar."""
    with db_lock:
        cur.execute("SELECT id, name, owner_id, captured_at FROM territories ORDER BY id")
        trows = cur.fetchall()
        cur.execute("SELECT id, text, ts, likes FROM legends ORDER BY ts DESC LIMIT 15")
        lrows = cur.fetchall()
        cur.execute("SELECT card_id, count FROM user_cards WHERE user_id=?", (uid,))
        crows = cur.fetchall()
    territories, owned = [], 0
    for tid, name, owner_id, captured_at in trows:
        owner_name = None
        if owner_id:
            clan = get_clan(owner_id)
            owner_name = clan["name"] if clan else None
            owned += 1
        status = v11_territory_status_label(tid, owner_id, captured_at)
        territories.append({"name": name, "owner": owner_name, "capital": "👑" in status, "fortified": "🛡" in status})
    legends = [{"id": r[0], "text": _strip_html_for_miniapp(r[1]), "when": time.strftime("%d.%m %H:%M", time.localtime(r[2])), "likes": r[3] or 0}
               for r in lrows]
    destiny_title, destiny_text = compute_destiny(uid)
    owned_cards = {r[0]: r[1] for r in crows}
    catalog = {k: v["name"] for k, v in CHARACTER_CARDS.items()}
    return {
        "territories": territories, "owned_count": owned,
        "legends": legends,
        "destiny": {"title": _strip_html_for_miniapp(destiny_title), "text": _strip_html_for_miniapp(destiny_text)},
        "cards": {"owned": owned_cards, "catalog": catalog},
    }


def hero_state(uid):
    catalog = []
    for k, h in HEROES.items():
        catalog.append({
            "key": k, "name": h["name"], "rarity": h.get("rarity", "Nodir"), "desc": h.get("desc", ""),
            "abilities": [{"name": a["name"], "desc": a["desc"], "unlock": a["unlock"]} for a in h["abilities"]],
            "price_diamond": hero_price(k, "buy_diamond"), "price_stars": hero_price(k, "buy_stars"),
        })
    hero = get_hero(uid)
    out = {"has_hero": bool(hero), "catalog": catalog, "max_level": HERO_MAX_LEVEL}
    if hero:
        nxt = hero["level"] + 1
        out["hero"] = {
            "key": hero["key"], "name": hero["name"], "level": hero["level"],
            "rarity": HEROES.get(hero["key"], {}).get("rarity", "Nodir"),
            "auto": hero_auto_enabled(uid),
            "abilities": [{"name": a["name"], "desc": a["desc"], "unlock": a["unlock"],
                           "unlocked": hero["level"] >= a["unlock"]} for a in hero["abilities"]],
            "next_cost_diamond": hero_level_up_cost(hero["level"], hero["key"]),
            "next_cost_stars": hero_price(hero["key"], f"lv{nxt}_stars") if hero["level"] < HERO_MAX_LEVEL else None,
        }
    return out


def hero_action(uid, action, key=None):
    """(ok, xabar) — Mini App'dan geroy amallari (Stars to'lovlari faqat bot ichida)."""
    if action == "toggle_auto":
        if not get_hero(uid):
            return False, "Sizda geroy yo'q."
        set_charge_value(uid, "hero_auto", 0 if hero_auto_enabled(uid) else 1)
        return True, "Avto-rejim yangilandi."
    if action == "buy":
        if key not in HEROES:
            return False, "Bunday geroy yo'q."
        if get_hero(uid):
            return False, "Sizda allaqachon geroy bor."
        price = hero_price(key, "buy_diamond")
        with db_lock:
            cur.execute("UPDATE users SET diamond = diamond - ? WHERE user_id=? AND diamond >= ?", (price, uid, price))
            paid = cur.rowcount > 0
            conn.commit()
        if not paid:
            return False, f"Yetarli olmos yo'q ({price} 💎 kerak)."
        if not _grant_hero(uid, key):
            add_balance_as('refund', uid, diamond=price, ledger=False)
            return False, "Sizda allaqachon geroy bor."
        return True, f"{HEROES[key]['name']} endi sizniki!"
    if action == "levelup":
        hero = get_hero(uid)
        if not hero:
            return False, "Sizda geroy yo'q."
        cost = hero_level_up_cost(hero["level"], hero["key"])
        if cost is None:
            return False, "Geroyingiz eng yuqori darajada."
        with db_lock:
            cur.execute("UPDATE users SET diamond = diamond - ? WHERE user_id=? AND diamond >= ?", (cost, uid, cost))
            paid = cur.rowcount > 0
            if paid:
                cur.execute("UPDATE heroes SET level=? WHERE user_id=? AND level=?", (hero["level"] + 1, uid, hero["level"]))
                if cur.rowcount == 0:
                    cur.execute("UPDATE users SET diamond = diamond + ? WHERE user_id=?", (cost, uid))
                    paid = False
            conn.commit()
        if not paid:
            return False, f"Yetarli olmos yo'q ({cost} 💎 kerak)."
        return True, f"Geroy {hero['level'] + 1}-darajaga ko'tarildi!"
    return False, "Noma'lum amal."


# ------------------------------------------------------------------ 💞 TAQDIR BOZORI ("Taqdirni bog'lash")
# Foydalanuvchi o'ziga narx (💎) qo'yib e'lon beradi. Kim shu narxni to'lasa — pul
# AVTOMATIK sotuvchiga o'tadi va ikkalasi juft (para) bo'ladi. Hammasi BITTA atomik
# bazadagi amal: pul o'tishi va juftlik yaratilishi yarim bo'lib qolmaydi.
FATE_MIN_PRICE = 1
FATE_MAX_PRICE = 100000


def _is_single(uid):
    return not (user_dict(uid).get("married_to") or 0)


def fate_list(uid, price, quote=""):
    user_dict(uid)
    if not oc_feature_on("fate"):   # 👑 Owner Center
        return False, "Taqdir bozori hozircha o'chirilgan."
    if is_banned(uid):
        return False, "Siz bloklangansiz."
    if not _is_single(uid):
        return False, "Siz allaqachon juftlikdasiz."
    try:
        price = int(price)
    except Exception:
        return False, "Narx butun son bo'lishi kerak."
    if not (FATE_MIN_PRICE <= price <= FATE_MAX_PRICE):
        return False, f"Narx {FATE_MIN_PRICE} dan {FATE_MAX_PRICE} 💎 gacha bo'lishi kerak."
    quote = re.sub(r"\s+", " ", (quote or "").strip())[:80]
    with db_lock:
        cur.execute("INSERT OR REPLACE INTO fate_listings (seller_id, price, quote, active, created_at) VALUES (?,?,?,1,?)",
                    (uid, price, quote, time.time()))
        conn.commit()
    return True, f"Taqdiringiz {price} 💎 ga e'lon qilindi."


def fate_unlist(uid):
    with db_lock:
        cur.execute("UPDATE fate_listings SET active=0 WHERE seller_id=?", (uid,))
        conn.commit()
    return True, "E'lon o'chirildi."


def pair_free_count():
    with db_lock:
        cur.execute("SELECT COUNT(*) FROM users WHERE COALESCE(married_to,0)=0 AND COALESCE(banned,0)=0")
        return int(cur.fetchone()[0] or 0)


def fate_market(uid):
    now = time.time()
    with db_lock:
        cur.execute(
            "SELECT f.seller_id, f.price, f.quote, u.name, f.boosted_until FROM fate_listings f "
            "JOIN users u ON u.user_id=f.seller_id "
            "WHERE f.active=1 AND COALESCE(u.married_to,0)=0 AND COALESCE(u.banned,0)=0 AND f.seller_id != ? "
            "ORDER BY (f.boosted_until > ?) DESC, f.created_at DESC LIMIT 40", (uid, now))
        rows = cur.fetchall()
        cur.execute("SELECT price, quote, active, boosted_until FROM fate_listings WHERE seller_id=?", (uid,))
        mine = cur.fetchone()
    return {
        "listings": [{"seller_id": r[0], "price": r[1], "quote": r[2] or "", "name": r[3] or "Foydalanuvchi",
                       "boosted": bool(r[4] and r[4] > now)} for r in rows],
        "mine": ({"price": mine[0], "quote": mine[1] or "", "active": bool(mine[2]),
                   "boosted": bool(mine[3] and mine[3] > now),
                   "boosted_left": max(0, int(mine[3] - now)) if mine[3] and mine[3] > now else 0}
                  if mine else None),
        "single": _is_single(uid), "free_count": pair_free_count(),
        "boost_price": FATE_BOOST_PRICE, "boost_hours": FATE_BOOST_HOURS,
    }


# ------------------------------------------------------------------ ✨ TAQDIR E'LONINI "KO'TARISH" (VIP ko'rinish)
FATE_BOOST_PRICE = 50     # 💎 — 24 soatga e'lonni ro'yxat boshiga chiqaradi + oltin nur beradi
FATE_BOOST_HOURS = 24


def fate_boost(uid):
    """(ok, xabar) — o'z Taqdir e'lonini 24 soatga eng tepaga va ko'zga tashlanadigan qilib chiqaradi."""
    with db_lock:
        cur.execute("SELECT price, active FROM fate_listings WHERE seller_id=?", (uid,))
        row = cur.fetchone()
        if not row or not row[1]:
            return False, "Avval o'zingizni Taqdir bozoriga qo'ying (E'lon qilish)."
        cur.execute("UPDATE users SET diamond = diamond - ? WHERE user_id=? AND diamond >= ?",
                    (FATE_BOOST_PRICE, uid, FATE_BOOST_PRICE))
        if cur.rowcount == 0:
            return False, f"Yetarli olmos yo'q ({FATE_BOOST_PRICE} 💎 kerak)."
        until = time.time() + FATE_BOOST_HOURS * 3600
        cur.execute("UPDATE fate_listings SET boosted_until=? WHERE seller_id=?", (until, uid))
        conn.commit()
    return True, f"✨ E'loningiz {FATE_BOOST_HOURS} soatga eng tepaga chiqarildi va oltin nur bilan ajralib turadi!"


def fate_buy(buyer_id, seller_id):
    """(ok, xabar) — taqdirni sotib olish: to'lov + juftlik BITTA atomik amalda."""
    if buyer_id == seller_id:
        return False, "O'zingizning taqdiringizni sotib ololmaysiz."
    if not oc_feature_on("fate"):   # 👑 Owner Center
        return False, "Taqdir bozori hozircha o'chirilgan."
    user_dict(buyer_id)
    if is_banned(buyer_id):
        return False, "Siz bloklangansiz."
    stamp = time.strftime("%Y-%m-%d %H:%M:%S")
    with db_lock:
        cur.execute("SELECT price FROM fate_listings WHERE seller_id=? AND active=1", (seller_id,))
        row = cur.fetchone()
        if not row:
            return False, "E'lon topilmadi yoki allaqachon sotilgan."
        price = int(row[0])
        cur.execute("SELECT COALESCE(married_to,0), COALESCE(banned,0) FROM users WHERE user_id=?", (seller_id,))
        s = cur.fetchone()
        if not s or s[0] or s[1]:
            return False, "Bu foydalanuvchi endi band."
        cur.execute("SELECT COALESCE(married_to,0) FROM users WHERE user_id=?", (buyer_id,))
        b = cur.fetchone()
        if not b:
            return False, "Avval botda /start bosing."
        if b[0]:
            return False, "Siz allaqachon juftlikdasiz."
        cur.execute("UPDATE users SET diamond = diamond - ? WHERE user_id=? AND diamond >= ?", (price, buyer_id, price))
        if cur.rowcount == 0:
            return False, f"Yetarli olmos yo'q ({price} 💎 kerak)."
        cur.execute("UPDATE users SET diamond = diamond + ? WHERE user_id=?", (price, seller_id))
        cur.execute("UPDATE users SET married_to=?, married_at=? WHERE user_id=?", (seller_id, stamp, buyer_id))
        cur.execute("UPDATE users SET married_to=?, married_at=? WHERE user_id=?", (buyer_id, stamp, seller_id))
        cur.execute("UPDATE fate_listings SET active=0 WHERE seller_id IN (?, ?)", (seller_id, buyer_id))
        cur.execute("UPDATE pair_requests SET status='cancelled' WHERE status='pending' "
                    "AND (from_id IN (?,?) OR to_id IN (?,?))", (seller_id, buyer_id, seller_id, buyer_id))
        conn.commit()
    b_name, s_name = user_dict(buyer_id)["name"], user_dict(seller_id)["name"]
    safe_send(buyer_id, f"💞 <b>Taqdiringiz bog'landi!</b>\nEndi siz {mention(seller_id, s_name)} bilan juftsiz. (−{price} 💎)")
    safe_send(seller_id, f"💞 <b>Taqdiringiz bog'landi!</b>\n{mention(buyer_id, b_name)} taqdiringizni sotib oldi — endi juftsiz. (+{price} 💎)")
    return True, f"Tabriklaymiz! Endi siz {s_name} bilan juftsiz. (−{price} 💎)"


# ------------------------------------------------------------------ 🎲 TASODIFIY PARA SO'ROVI (10 daqiqa)
PAIR_TTL = 600


def _pair_pending_out(uid):
    with db_lock:
        cur.execute("SELECT id, created_at FROM pair_requests WHERE from_id=? AND status='pending' AND created_at>? "
                    "ORDER BY id DESC LIMIT 1", (uid, time.time() - PAIR_TTL))
        return cur.fetchone()


def pair_status(uid):
    p = _pair_pending_out(uid)
    with db_lock:
        cur.execute("SELECT COALESCE(married_to,0), 0, married_at FROM users WHERE user_id=?", (uid,))
        row = cur.fetchone()
    partner_id = row[0] if row else 0
    bond, partner_name, married_at = None, None, None
    if partner_id:
        partner_name = user_dict(partner_id)["name"]
        married_at = row[2] or None
    return {"free": pair_free_count(), "single": _is_single(uid),
            "pending": ({"id": p[0], "left": max(0, int(PAIR_TTL - (time.time() - p[1])))} if p else None),
            "partner_id": partner_id, "partner_name": partner_name, "married_at": married_at,
            "bond": None, "gifts": {}}


def _pair_expire(rid):
    with db_lock:
        cur.execute("SELECT from_id, status FROM pair_requests WHERE id=?", (rid,))
        row = cur.fetchone()
        if not row or row[1] != "pending":
            return
        cur.execute("UPDATE pair_requests SET status='expired' WHERE id=?", (rid,))
        conn.commit()
    safe_send(row[0], "⌛ Tasodifiy juft so'rovingizga 10 daqiqa ichida javob berilmadi va u bekor qilindi. Qayta urinib ko'rishingiz mumkin.")


def pair_random_request(uid):
    """(ok, rid yoki xato matni) — tasodifiy bo'ydoq foydalanuvchiga juft taklifi yuboradi."""
    user_dict(uid)
    if is_banned(uid):
        return False, "Siz bloklangansiz."
    if not _is_single(uid):
        return False, "Siz allaqachon juftlikdasiz."
    if _pair_pending_out(uid):
        return False, "Sizda faol so'rov bor — javobni kuting."
    if not _rate_ok(uid, "pair", 5, 3600):
        return False, "Juda ko'p urinish — birozdan keyin qayta urinib ko'ring."
    with db_lock:
        cur.execute(
            "SELECT user_id FROM users WHERE COALESCE(married_to,0)=0 AND COALESCE(banned,0)=0 AND user_id != ? "
            "AND user_id NOT IN (SELECT to_id FROM pair_requests WHERE status='pending' AND created_at>?) "
            "ORDER BY RANDOM() LIMIT 15", (uid, time.time() - PAIR_TTL))
        cands = [r[0] for r in cur.fetchall()]
    my_name = user_dict(uid)["name"]
    for cid in cands:
        with db_lock:
            cur.execute("INSERT INTO pair_requests (from_id, to_id, created_at, status) VALUES (?,?,?,'pending')",
                        (uid, cid, time.time()))
            rid = cur.lastrowid
            conn.commit()
        kb = types.InlineKeyboardMarkup()
        kb.add(types.InlineKeyboardButton("💞 Qabul qilish", callback_data=f"prq|acc|{rid}"),
               types.InlineKeyboardButton("❌ Rad etish", callback_data=f"prq|rej|{rid}"))
        if safe_send(cid, f"💞 <b>Tasodifiy juft taklifi!</b>\n{mention(uid, my_name)} sizga juft bo'lishni taklif qilmoqda.\n"
                          f"⏳ Javob berish uchun 10 daqiqa bor.", kb):
            t = threading.Timer(PAIR_TTL + 1, _pair_expire, args=(rid,))
            t.daemon = True
            t.start()
            return True, rid
        with db_lock:
            cur.execute("DELETE FROM pair_requests WHERE id=?", (rid,))
            conn.commit()
    return False, "Hozircha mos foydalanuvchi topilmadi. Keyinroq urinib ko'ring."


def pair_respond(uid, rid, accept):
    """(ok, xabar) — so'rov oluvchining javobi."""
    stamp = time.strftime("%Y-%m-%d %H:%M:%S")
    with db_lock:
        cur.execute("SELECT from_id, to_id, created_at, status FROM pair_requests WHERE id=?", (rid,))
        row = cur.fetchone()
        if not row or row[1] != uid:
            return False, "Bu so'rov sizga tegishli emas."
        from_id, _to, created, status = row
        if status != "pending":
            return False, "So'rov allaqachon yopilgan."
        if time.time() - created > PAIR_TTL:
            cur.execute("UPDATE pair_requests SET status='expired' WHERE id=?", (rid,))
            conn.commit()
            return False, "So'rov muddati tugagan."
        if not accept:
            cur.execute("UPDATE pair_requests SET status='rejected' WHERE id=?", (rid,))
            conn.commit()
            result = "rejected"
        else:
            cur.execute("SELECT COUNT(*) FROM users WHERE user_id IN (?,?) AND COALESCE(married_to,0)=0", (from_id, uid))
            if cur.fetchone()[0] != 2:
                cur.execute("UPDATE pair_requests SET status='cancelled' WHERE id=?", (rid,))
                conn.commit()
                return False, "Sizlardan biri allaqachon juftlikda."
            cur.execute("UPDATE users SET married_to=?, married_at=? WHERE user_id=?", (uid, stamp, from_id))
            cur.execute("UPDATE users SET married_to=?, married_at=? WHERE user_id=?", (from_id, stamp, uid))
            cur.execute("UPDATE pair_requests SET status='accepted' WHERE id=?", (rid,))
            cur.execute("UPDATE pair_requests SET status='cancelled' WHERE status='pending' AND id != ? "
                        "AND (from_id IN (?,?) OR to_id IN (?,?))", (rid, from_id, uid, from_id, uid))
            cur.execute("UPDATE fate_listings SET active=0 WHERE seller_id IN (?,?)", (from_id, uid))
            conn.commit()
            result = "accepted"
    my_name, other_name = user_dict(uid)["name"], user_dict(from_id)["name"]
    if result == "rejected":
        safe_send(from_id, f"💔 {mention(uid, my_name)} tasodifiy juft taklifingizni rad etdi. Qayta urinib ko'rishingiz mumkin.")
        return True, "Taklif rad etildi."
    safe_send(from_id, f"💞 <b>Tabriklaymiz!</b> {mention(uid, my_name)} taklifingizni qabul qildi — endi juftsiz!")
    return True, f"Tabriklaymiz! Endi siz {other_name} bilan juftsiz."


