@bot.message_handler(commands=["premium_qosh", "premium_ochir", "premium_narx", "premium_royxat"])
def cmd_premium_admin(message):
    """💎 FAQAT bot egasi. /premium_qosh <narx> [olmos|dollar] (guruh ichida) yoki
    /premium_qosh <chat_id> <narx> [olmos|dollar] (shaxsiy chatda) | /premium_narx <id> <narx> |
    /premium_ochir <id> | /premium_royxat"""
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    if not is_owner(message.from_user.id):
        return
    parts = (message.text or "").split()
    cmd = parts[0].split("@")[0].lower()
    args = parts[1:]
    reply = lambda t: bot.send_message(message.chat.id, t)
    if cmd == "/premium_royxat":
        with db_lock:
            cur.execute("SELECT id, chat_id, title, price, currency, active FROM premium_groups ORDER BY id")
            rows = cur.fetchall()
        if not rows:
            reply("💎 Premium guruhlar yo'q.")
            return
        reply("💎 <b>Premium guruhlar</b>\n" + "\n".join(
            f"#{r[0]} — {esc(r[2])} ({r[1]}) — {r[3]} {'💎' if r[4] == 'diamond' else '$'} {'' if r[5] else '⛔ o‘chirilgan'}" for r in rows))
        return
    if cmd == "/premium_ochir":
        if not args or not args[0].isdigit():
            reply("❌ Foydalanish: <code>/premium_ochir 1</code>")
            return
        with db_lock:
            cur.execute("UPDATE premium_groups SET active=0 WHERE id=?", (int(args[0]),))
            conn.commit()
        reply("✅ Premium guruh o'chirildi.")
        return
    if cmd == "/premium_narx":
        if len(args) < 2 or not args[0].isdigit() or not args[1].isdigit() or int(args[1]) < 1:
            reply("❌ Foydalanish: <code>/premium_narx 1 50</code>")
            return
        with db_lock:
            cur.execute("UPDATE premium_groups SET price=? WHERE id=?", (int(args[1]), int(args[0])))
            conn.commit()
        reply("✅ Narx yangilandi.")
        return
    # /premium_qosh
    if message.chat.type in ("group", "supergroup"):
        chat_id, title = message.chat.id, message.chat.title or "Premium guruh"
        rest = args
    else:
        if len(args) < 2 or not args[0].lstrip("-").isdigit():
            reply("❌ Shaxsiy chatda: <code>/premium_qosh -100123456789 50 olmos</code>\nYoki guruhning ichida: <code>/premium_qosh 50 olmos</code>")
            return
        chat_id = int(args[0])
        rest = args[1:]
        try:
            title = bot.get_chat(chat_id).title or "Premium guruh"
        except Exception:
            reply("❌ Guruh topilmadi yoki bot u yerda emas.")
            return
    if not rest or not rest[0].isdigit() or int(rest[0]) < 1:
        reply("❌ Narxni yozing: <code>/premium_qosh 50 olmos</code>")
        return
    currency = _parse_currency(rest[1] if len(rest) > 1 else "")
    with db_lock:
        cur.execute("INSERT INTO premium_groups (chat_id, title, price, currency, active) VALUES (?,?,?,?,1)",
                    (chat_id, title, int(rest[0]), currency))
        gid = cur.lastrowid
        conn.commit()
    reply(f"✅ Premium guruh qo'shildi: <b>{esc(title)}</b> — #{gid}, {rest[0]} {'💎' if currency == 'diamond' else '$'}.\n"
          f"⚠️ Bot shu guruhda admin bo'lishi va «Taklif havolalari» huquqiga ega bo'lishi kerak.")


