def forecast_state(uid, other=""):
    today = _date_str()
    seed = int(hashlib.sha256(f"{uid}:{today}".encode()).hexdigest()[:8], 16)
    love = 40 + seed % 61
    out = {"date": today, "love": love, "lucky_number": (seed >> 4) % 99 + 1,
           "advice": _FORECAST_ADVICE[(seed >> 8) % len(_FORECAST_ADVICE)],
           "mood": ["💖", "✨", "🌙", "🔥", "🌹", "🍀"][(seed >> 12) % 6]}
    other = re.sub(r"\s+", " ", str(other or "")).strip().lstrip("@")[:40]
    if other:
        pair = "|".join(sorted([str(uid), other.lower()]))
        p = 40 + int(hashlib.sha256(pair.encode()).hexdigest()[:8], 16) % 61
        text = ("Ajoyib moslik! 💞" if p >= 90 else "Kuchli tortishuv bor 💫" if p >= 75
                else "Yaxshi juftlik bo'lishi mumkin 🌷" if p >= 60 else "Birga sabr va e'tibor kerak 🌱")
        out["compat"] = {"name": other, "percent": p, "text": text}
    return out


