def _character_progress(uid, xp=0, destiny=0):
    try:
        with db_lock:
            cur.execute('SELECT identity,character_xp,character_level,destiny_points FROM hunter_character_identity WHERE user_id=?',(uid,)); r=cur.fetchone()
            if not r: return None
            nx=max(0,int(r[1] or 0)+int(xp or 0)); nd=max(0,int(r[3] or 0)+int(destiny or 0))
            nl=max(1,1+nx//100)
            cur.execute('UPDATE hunter_character_identity SET character_xp=?,character_level=?,destiny_points=?,updated_at=? WHERE user_id=?',(nx,nl,nd,time.time(),uid)); conn.commit()
            return {'xp':nx,'level':nl,'destiny_points':nd,'leveled_up':nl>int(r[2] or 1)}
    except Exception:
        return None

def _character_trait(uid):
    with db_lock:
        cur.execute('SELECT identity,temperament,skill_key,skill_name FROM hunter_character_identity WHERE user_id=?',(uid,)); r=cur.fetchone()
    if not r: return {'identity':'Hunter','temperament':'observant','skill_key':'instinct','skill_name':'Sezgi','skill_text':'Shaxsiy yo‘l'}
    identity, temp, key, name = r
    fallback=_CHARACTER_TRAITS.get(identity, ('observant','instinct','Sezgi','Shaxsiy yo‘l'))
    return {'identity':identity,'temperament':temp or fallback[0],'skill_key':key or fallback[1],'skill_name':name or fallback[2],'skill_text':fallback[3]}

_CHAR_ARCH={
 'female': [('Luna','Oy qo‘riqchisi','Tungi izchi'),('Mira','Sokin kuzatuvchi','Sir izlovchi')],
 'male': [('Kael','Soyalar ovchisi','Tungi ovchi'),('Arin','Temir iroda','Qalqonchi')]
}
def _character_after_select(uid, data):
    code=data.get('avatar_code') or 'starter_f1'
    with db_lock:
        cur.execute('SELECT name,gender,rarity FROM hm_avatar_defs WHERE code=?',(code,)); row=cur.fetchone()
    name,gender,rarity=(row if row else ('Hunter','male','Starter'))
    with db_lock:
        cur.execute('SELECT identity,destiny,archetype,origin,title,path,character_level,character_xp,starter_quest,starter_done,temperament,skill_key,skill_name,destiny_points FROM hunter_character_identity WHERE user_id=?',(uid,)); old=cur.fetchone()
    if old:
        return {
          'selected':True,'new':False,'identity':old[0],'destiny':old[1],'archetype':old[2],'origin':old[3],'title':old[4],'path':old[5],
          'level':old[6],'xp':old[7],'starter_quest':old[8],'starter_done':bool(old[9]),'rarity':rarity,'avatar_code':code,'temperament':old[10],'skill_key':old[11],'skill_name':old[12],'destiny_points':old[13]}
    idx=abs(int(uid))%len(_CHAR_ARCH[gender]); identity,destiny=_CHAR_ARCH[gender][idx][:2]
    temperament,skill_key,skill_name,_skill_text=_CHARACTER_TRAITS.get(identity,('observant','instinct','Sezgi','Shaxsiy yo‘l'))
    origin={'female':'Oy qal’asi','male':'Soyalar shahri'}.get(gender,'Soyalar shahri')
    title={'Legendary':'Taqdir tanlangani','Mythic':'Afsonaga da’vogar','Epic':'Yangi afsona','Starter':'Yangi ovchi'}.get(rarity,'Yangi ovchi')
    path='Kuzatuvchi' if 'kuz' in destiny.lower() or 'iz' in destiny.lower() else 'Ovchi'
    now=time.time()
    with db_lock:
        cur.execute('INSERT INTO hunter_character_identity(user_id,avatar_code,identity,destiny,archetype,origin,title,path,character_level,character_xp,starter_quest,starter_done,started_at,updated_at,temperament,skill_key,skill_name,destiny_points) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',
                    (uid,code,identity,destiny,identity,origin,title,path,1,0,'first_hunt',0,now,now,temperament,skill_key,skill_name,0)); conn.commit()
    # Existing World 2 profile is synchronized, so character selection immediately has a destination.
    try:
        _hw2_save(uid,character_name=name,origin=origin,title=title,path=path,archetype=identity,updated_at=now)
    except Exception: pass
    return {'selected':True,'new':True,'identity':identity,'destiny':destiny,'archetype':identity,'origin':origin,'title':title,'path':path,'level':1,'xp':0,'starter_quest':'first_hunt','starter_done':False,'rarity':rarity,'avatar_code':code,'temperament':temperament,'skill_key':skill_key,'skill_name':skill_name,'destiny_points':0}

def character_start(uid):
    with db_lock:
        cur.execute('SELECT avatar_code,identity,destiny,archetype,origin,title,path,character_level,character_xp,starter_quest,starter_done FROM hunter_character_identity WHERE user_id=?',(uid,)); r=cur.fetchone()
    if not r: return False,'Avval personaj tanlang.',{}
    if r[10]: return True,'Yo‘l allaqachon boshlangan.',{'started':True,'quest':'first_hunt'}
    now=time.time(); xp=25
    with db_lock:
        cur.execute('UPDATE hunter_character_identity SET starter_done=1,character_xp=?,updated_at=? WHERE user_id=?',(xp,now,uid)); conn.commit()
    _character_progress(uid,xp=xp)
    try: _hw2_log(uid,'character','character_start',f'{r[1]} yo‘lini boshladi.',xp,0)
    except Exception: pass
    return True,'Yo‘l boshlandi.',{'started':True,'quest':'first_hunt','xp':xp,'reward':'25 XP','currency_reward':False}


def _avatar_user(uid):
    with db_lock:
        cur.execute('SELECT avatar_code,body_json,owned_json,equipped_json FROM hm_user_avatar WHERE user_id=?',(uid,)); r=cur.fetchone()
    if r: return {'avatar_code':r[0],'body':json.loads(r[1] or '{}'),'owned':json.loads(r[2] or '[]'),'equipped':json.loads(r[3] or '{}')}
    return {'avatar_code':'starter_f1','body':{'height':50,'head':50,'shoulders':50,'waist':50,'hair':1,'eyes':1,'brows':1,'mouth':1,'nose':1,'skin':1},'owned':['starter_f1'],'equipped':{}}

def _avatar_save(uid, data, commit=True):
    """commit=False: chaqiruvchi yozuvni boshqa o'zgarishlar (masalan, pul yechish) bilan
    BIR tranzaksiyada tasdiqlaydi."""
    with db_lock:
        cur.execute("INSERT INTO hm_user_avatar(user_id,avatar_code,body_json,owned_json,equipped_json,updated_at) VALUES(?,?,?,?,?,?) ON CONFLICT(user_id) DO UPDATE SET avatar_code=excluded.avatar_code,body_json=excluded.body_json,owned_json=excluded.owned_json,equipped_json=excluded.equipped_json,updated_at=excluded.updated_at",
                    (uid,data['avatar_code'],json.dumps(data.get('body',{}),ensure_ascii=False),json.dumps(data.get('owned',[]),ensure_ascii=False),json.dumps(data.get('equipped',{}),ensure_ascii=False),time.time()))
        if commit:
            conn.commit()

def avatar_catalog(uid):
    me=_avatar_user(uid)
    with db_lock:
        cur.execute('SELECT code,name,gender,rarity,price,currency,active,sort_order,colors FROM hm_avatar_defs ORDER BY sort_order,avatar_id'); av=cur.fetchall()
        cur.execute('SELECT code,name,gender,slot,price,currency,active,rarity,colors FROM hm_avatar_clothes ORDER BY gender,item_id'); cl=cur.fetchall()
    def A(r): return {'code':r[0],'name':r[1],'gender':r[2],'rarity':r[3],'price':r[4],'currency':r[5],'active':bool(r[6]),'colors':json.loads(r[8] or '{}'),'owned':r[0] in me['owned']}
    def C(r): return {'code':r[0],'name':r[1],'gender':r[2],'slot':r[3],'price':r[4],'currency':r[5],'active':bool(r[6]),'rarity':r[7],'colors':json.loads(r[8] or '{}'),'owned':r[0] in me['owned'],'equipped':me['equipped'].get(r[3])==r[0]}
    current_code=me.get('avatar_code','starter_f1')
    current_row=next((r for r in av if r[0]==current_code), None)
    rarity=current_row[3] if current_row else 'Starter'
    style_benefit={
        'Starter':'🪪 Profil ko‘rinishi + 360° 3D',
        'Rare':'🎬 Qo‘shimcha animatsion aura + profil ko‘rinishi',
        'Epic':'✨ Kuchli aura + noyob 3D pose',
        'Mythic':'🌌 Mythic aura + maxsus pose',
        'Legendary':'👑 Legendary aura + g‘alaba pose'
    }.get(rarity,'🪪 3D profil')
    return {'avatars':[A(r) for r in av if r[6]],'clothes':[C(r) for r in cl if r[6]],'owned':me['owned'],'current':me,
            'style_benefit':style_benefit,'currency_reward':False}

def _avatar_apply_item(data, kind, code):
    """Tanlangan avatarni yoki kiyimni (slotiga) `data` ichiga qo'yadi."""
    if kind == 'avatar':
        data['avatar_code'] = code
        return
    with db_lock:
        cur.execute('SELECT slot FROM hm_avatar_clothes WHERE code=?', (code,))
        row = cur.fetchone()
    if row:
        data['equipped'][row[0]] = code


def avatar_buy(uid, kind, code):
    """(ok, xabar, holat). "Tekshir -> pul yech -> egalikni yoz" zanjiri BITTA qulf va
    BITTA tranzaksiya ichida: parallel bosishlarda pul ikki marta yechilmaydi, yozuv
    saqlanmasa pul qaytadi (rollback)."""
    table = 'hm_avatar_defs' if kind == 'avatar' else 'hm_avatar_clothes'
    with db_lock:
        data = _avatar_user(uid)
        if code in data['owned']:
            _avatar_apply_item(data, kind, code)
            _avatar_save(uid, data)
            owned_now = True
        else:
            owned_now = False
            cur.execute(f'SELECT price,currency,active,gender FROM {table} WHERE code=?', (code,))
            r = cur.fetchone()
            if not r or not r[2]:
                return False, 'Mahsulot sotuvda emas.', data
            price, curr = r[0], r[1]
            col = {'diamond': 'diamond', 'dollar': 'dollar', 'coin': 'coin'}.get(curr)
            if not col:
                return False, 'Noma’lum valyuta.', data
            try:
                cur.execute(f'UPDATE users SET {col}={col}-? WHERE user_id=? AND {col}>=?', (price, uid, price))
                if cur.rowcount == 0:
                    return False, f'Yetarli {curr} yo‘q.', data
                data['owned'].append(code)
                _avatar_apply_item(data, kind, code)
                _avatar_save(uid, data, commit=False)
                conn.commit()
            except Exception:
                conn.rollback()
                _logger.exception("avatar_buy: xarid bekor qilindi (uid=%s, code=%s)", uid, code)
                raise
    if kind == 'avatar':
        data['character_journey'] = _character_after_select(uid, data)
    if owned_now:
        return True, 'Tanlandi.' if kind == 'avatar' else 'Kiyildi.', data
    return True, 'Xarid qilindi.', data

def avatar_update(uid, body=None, avatar_code=None, equip=None):
    data=_avatar_user(uid)
    if avatar_code:
        if avatar_code not in data['owned']: return False,'Avval personajni oling.',data
        data['avatar_code']=avatar_code
    if isinstance(body,dict):
        allow={'height','head','shoulders','waist','hair','eyes','brows','mouth','nose','skin','hairColor','eyeColor','skinColor'}
        data['body'].update({k:v for k,v in body.items() if k in allow})
    if isinstance(equip,dict):
        for slot,code in equip.items():
            if code in data['owned']: data['equipped'][slot]=code
    _avatar_save(uid,data)
    if avatar_code: data['character_journey']=_character_after_select(uid,data)
    return True,'Saqlandi.',data

