@bot.message_handler(commands=['personaj_narx'])
def cmd_avatar_price(message):
    if not is_owner(message.from_user.id): return
    p=(message.text or '').split();
    if len(p)!=3: bot.send_message(message.chat.id,'Foydalanish: /personaj_narx <code>avatar_code</code> <code>narx</code>'); return
    try: price=max(0,int(p[2]))
    except: bot.send_message(message.chat.id,'❌ Narx son bo‘lishi kerak.'); return
    with db_lock: cur.execute('UPDATE hm_avatar_defs SET price=? WHERE code=?',(price,p[1])); conn.commit()
    bot.send_message(message.chat.id,f'✅ {p[1]} narxi: <b>{price}</b> 💎')

