@bot.message_handler(commands=['kiyim_qosh'])
def cmd_cloth_add(message):
    if not is_owner(message.from_user.id): return
    m=re.match(r'^/kiyim_qosh\s+(ayol|erkak)\s+"([^"]+)"\s+(\w+)\s+(\d+)(?:\s+(diamond|dollar|coin))?$',message.text or '',re.I)
    if not m: bot.send_message(message.chat.id,'Foydalanish: /kiyim_qosh ayol "Nom" top 500 diamond'); return
