    with db_lock: cur.execute('INSERT INTO hm_avatar_clothes(code,name,gender,slot,price,currency,active,rarity,colors,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)',(code,m.group(2),gender,m.group(3),int(m.group(4)),m.group(5) or 'diamond',1,'Rare','{}',now)); conn.commit()
    bot.send_message(message.chat.id,f'✅ Kiyim qo‘shildi: <code>{code}</code>')

