@bot.callback_query_handler(func=lambda c: c.data.startswith("admin|v8|"))
def cb_admin_v8_section(call):
    if not _owner_only(call):
        return
    parts = call.data.split("|")
    key = parts[2]
    note = None
    if key == "hc_tick":
        _hc_market_tick()
        key, note = "hc", "Kurs yangilandi."
    elif key == "hc_reset":
        global HC_DIAMOND_RATE, HC_PREV_DIAMOND_RATE
        HC_DIAMOND_RATE = HC_PREV_DIAMOND_RATE = float(HC_BASE_DIAMOND_RATE)
        set_setting("hc_diamond_rate", HC_DIAMOND_RATE)
        key, note = "hc", "Kurs bazaviyga qaytarildi."
    elif key == "pgtoggle" and len(parts) > 3 and parts[3].isdigit():
        with db_lock:
            cur.execute("UPDATE premium_groups SET active = 1 - active WHERE id=?", (int(parts[3]),))
            conn.commit()
        key, note = "premium", "Yangilandi."
    elif key == "news_clear":
        set_setting("news_v8", "[]")
        key, note = "news", "Tozalandi."
    elif key == "fatedel" and len(parts) > 3 and parts[3].lstrip("-").isdigit():
        fate_unlist(int(parts[3]))
        key, note = "fate", "E'lon olib tashlandi."
    bot.answer_callback_query(call.id, note)
    text, kb = _v8_panel(key)
    smart_render(call, text, kb)


@bot.message_handler(commands=["xodimlar", "jamoa_qosh", "jamoa_ochir"])
def cmd_jamoa(message):
    """👥 FAQAT bot egasi: /xodimlar | /jamoa_qosh Ism | Rol | loyiha soni | username | /jamoa_ochir Ism
    ⚠️ E'TIBOR: bu yerda ataylab "jamoa" emas "xodimlar" ishlatilgan — chunki /jamoa buyrug'i
    avval o'yin ichidagi yashirin jamoa chati uchun ishlatilgan edi (endi u olib tashlangan)
    band qilingan, va pyTelegramBotAPI bir xil buyruqqa ikkita handler ro'yxatga olinganda
    FAQAT birinchisini chaqiradi. Buni qayta "jamoa" ga o'zgartirmang — aks holda bu handler
    yana ishlamay qoladi."""
    maybe_capture_owner(message.from_user)
    safe_delete(message)
    if not is_owner(message.from_user.id):
        return
    cmd = (message.text or "").split()[0].split("@")[0].lower()
    rest = (message.text or "").split(maxsplit=1)
    try:
        team = json.loads(get_setting("team_v8") or "[]")
        if not isinstance(team, list):
            team = []
    except Exception:
        team = []
    if cmd == "/jamoa_qosh":
        fields = [x.strip() for x in (rest[1] if len(rest) > 1 else "").split("|")]
        if len(fields) < 2 or not fields[0] or not fields[1]:
            bot.send_message(message.chat.id, "❌ Foydalanish: <code>/jamoa_qosh Ism | Rol | loyiha soni | username</code>")
            return
        proj = int(fields[2]) if len(fields) > 2 and fields[2].isdigit() else 1
        uname = fields[3].lstrip("@") if len(fields) > 3 and fields[3] else None
        team = [m for m in team if m.get("name", "").lower() != fields[0].lower()] + [{"name": fields[0][:40], "role": fields[1][:30], "projects": proj, "username": uname}]
        set_setting("team_v8", json.dumps(team, ensure_ascii=False))
    elif cmd == "/jamoa_ochir":
        name = (rest[1] if len(rest) > 1 else "").strip().lower()
        if not name:
            bot.send_message(message.chat.id, "❌ Foydalanish: <code>/jamoa_ochir Ism</code>")
            return
        team = [m for m in team if m.get("name", "").lower() != name]
        set_setting("team_v8", json.dumps(team, ensure_ascii=False))
    text, _ = _v8_panel("team")
    bot.send_message(message.chat.id, text)



