@bot.callback_query_handler(func=lambda c: c.data.startswith('adm4|') and not c.data.startswith('adm4|act|') and c.data != 'adm4|home')
def cb_admin4_section(call):
    if not _owner_only(call): return
    key=call.data.split('|')[1]
    bot.answer_callback_query(call.id)
    text,kb=_admin4_section(key)
