@bot.callback_query_handler(func=lambda c: c.data.startswith('adm4|act|'))
def cb_admin4_action(call):
    if not _owner_only(call): return
    act=call.data.split('|')[2]
    bot.answer_callback_query(call.id)
    uid=call.from_user.id
    prompts={
      'user':('user','🔎 Foydalanuvchi ID sini yuboring yoki xabariga reply qiling.'),
      'balance':('balance','💰 Format: <code>USER_ID dollar|diamond|coin AMOUNT</code>\nMasalan: <code>12345 diamond 500</code> yoki <code>12345 dollar -100</code>'),
      'ban':('ban','🚫 Format: <code>USER_ID on</code> yoki <code>USER_ID off</code>'),
      'elite':('elite','👑 Format: <code>USER_ID KUN [DARAJA 1/2/3]</code>\nMasalan: <code>12345 30 2</code> (daraja yozilmasa — 3)'),
    }
    state,prompt=prompts.get(act,('',''))
    if not state: return
    _ADMIN4_STATE[uid]=state
    bot.send_message(call.message.chat.id,prompt)

@bot.message_handler(func=lambda m: bool(getattr(m,'from_user',None)) and is_owner(m.from_user.id) and m.from_user.id in _ADMIN4_STATE)
def _admin4_input(message):
    uid=message.from_user.id; state=_ADMIN4_STATE.get(uid); raw=(message.text or '').strip()
    try:
        if state=='user':
            tid=int(raw.split()[0]); _ADMIN4_STATE.pop(uid,None)
            u=user_dict(tid)
            ch=get_charges(tid)
            elite_label = "ha" if ch.get("vip_until",0) > time.time() else "yo-q"
            bot.send_message(message.chat.id, f"🔎 <b>{esc(u['name'])}</b>\nID: <code>{tid}</code>\n💵 {u.get('dollar',0)} · 💎 {u.get('diamond',0)} · 🪙 {u.get('coin',0)}\n🎮 {u.get('games',0)} o-yin · 🏆 {u.get('wins',0)} g-alaba\n👑 PRIME: {elite_label}")
        elif state=='balance':
            p=raw.split(); tid=int(p[0]); field=p[1].lower(); amount=int(p[2]); col={'dollar':'dollar','diamond':'diamond','coin':'coin'}[field]
            with db_lock:
                cur.execute(f'UPDATE users SET {col}={col}+? WHERE user_id=?',(amount,tid)); ok=cur.rowcount>0; conn.commit()
            _ADMIN4_STATE.pop(uid,None)
            bot.send_message(message.chat.id,('✅' if ok else '❌')+f' {tid}: {field} {amount:+d}')
        elif state=='ban':
            p=raw.split(); tid=int(p[0]); val=p[1].lower() in ('on','1','true','ban')
            with db_lock:
                cur.execute("UPDATE users SET banned=? WHERE user_id=?",(1 if val else 0,tid)); ok=cur.rowcount>0; conn.commit()
            _ADMIN4_STATE.pop(uid,None); bot.send_message(message.chat.id,('🚫 Ban berildi' if val else '✅ Ban olindi') if ok else '❌ Foydalanuvchi topilmadi.')
        elif state=='elite':
            p=raw.split(); tid=int(p[0]); days=max(1,int(p[1])); lvl=int(p[2]) if len(p)>2 and p[2] in ('1','2','3') else 3
            grant_elite_days(tid,days,lvl)
            _ADMIN4_STATE.pop(uid,None); bot.send_message(message.chat.id,f'👑 {tid} ga {days} kun PRIME {lvl} berildi.')
    except Exception:
        bot.send_message(message.chat.id,'❌ Format noto‘g‘ri. Qayta yuboring.')


