def _send_onboarding_intro(chat_id, first_name):
    """🎬 Yangi foydalanuvchi /start bosganda, bosh menyudan OLDIN ko'rsatiladigan
    qisqa, bir martalik "kirish sahnasi". Maqsad — birinchi taassurotni oddiy
    menyu o'rniga kichik hikoya bilan boshlash (ortiqcha uzun emas, 2 ta xabar)."""
    try:
        safe_name = esc(first_name or "Yo'lovchi")
        bot.send_message(
            chat_id,
            f"🌃 <i>Hunter shahri, tungi ko'cha...</i>\n\n"
            f"Xush kelibsiz, <b>{safe_name}</b>. Bu yerda ishonch — eng qimmat "
            f"narsa: kim do'st, kim dushman — buni faqat o'yin ko'rsatadi.",
        )
        time.sleep(0.6)
        bot.send_message(
            chat_id,
            "🎭 Har bir o'yinda sizga yashirin rol beriladi. Ayyorlik bilan "
            "o'ylang, ovqat vaqtida ovoz bering — va omadingizni sinang.",
        )
        time.sleep(0.4)
    except Exception as e:
        _logger.warning("_send_onboarding_intro xatolik: %s", e)


def _compare_block(uid):
    """/solishtir uchun bitta foydalanuvchining qisqa statistik blokini tayyorlaydi."""
    u = user_dict(uid)
    _, streak = _points_summary(uid)
    winrate = round((u.get("wins", 0) / u["games"]) * 100, 1) if u.get("games") else 0.0
    return {
        "name": u.get("name") or "Foydalanuvchi",
        "games": u.get("games", 0),
        "wins": u.get("wins", 0),
        "winrate": winrate,
        "dollar": u.get("dollar", 0),
        "diamond": u.get("diamond", 0),
        "duel_wins": u.get("duel_wins", 0),
        "duel_losses": u.get("duel_losses", 0),
        "streak": streak,
    }


@bot.message_handler(commands=["solishtir"])
def cmd_solishtir(message):
    """⚔️ /solishtir — reply qilingan o'yinchi bilan statistikangizni yonma-yon
    taqqoslaydi. Faqat shaxsiy hisobot, hech qanday balansga ta'sir qilmaydi."""
    safe_delete(message)
    if not message.reply_to_message:
        bot.send_message(
            message.chat.id,
            "⚔️ Kimningdir statistikasi bilan solishtirish uchun, o'sha "
            "foydalanuvchining xabariga <b>reply</b> qilib <code>/solishtir</code> deb yozing.",
        )
        return
    other = message.reply_to_message.from_user
    if other.id == message.from_user.id:
        bot.send_message(message.chat.id, "⚔️ O'zingiz bilan solishtirib bo'lmaydi 🙂")
        return

    a = _compare_block(message.from_user.id)
    b = _compare_block(other.id)

    def _row(label, av, bv, unit=""):
        a_mark = " 🟢" if av > bv else ""
        b_mark = " 🟢" if bv > av else ""
        return f"{label}\n   {av}{unit}{a_mark}   vs   {bv}{unit}{b_mark}"

    text = (
        f"⚔️ <b>{esc(a['name'])}</b> vs <b>{esc(b['name'])}</b>\n"
        f"━━━━━━━━━━━━━━━\n"
        f"{_row('🎮 O‘yinlar', a['games'], b['games'])}\n\n"
        f"{_row('🏆 G‘alabalar', a['wins'], b['wins'])}\n\n"
        f"{_row('📊 Win-rate', a['winrate'], b['winrate'], '%')}\n\n"
        f"{_row('🔥 Seriya', a['streak'], b['streak'])}\n\n"
        f"{_row('⚔️ Duel (g‘alaba)', a['duel_wins'], b['duel_wins'])}\n\n"
        f"{_row('💎 Olmos', a['diamond'], b['diamond'])}"
    )
    bot.send_message(message.chat.id, text, reply_markup=with_back_button())


def voting_progress_bar(seconds_left, total_seconds, width=5):
    """🗳 Ovoz berish/tun bosqichi uchun vizual progress-bar matni.
    Masalan: '⬛⬛⬜⬜⬜ 40 soniya qoldi' — mavjud sanoq xabarlariga
    qo'shimcha ravishda ishlatish uchun (chaqiruv ixtiyoriy, majburiy emas)."""
    total_seconds = max(1, total_seconds)
    filled = max(0, min(width, round((seconds_left / total_seconds) * width)))
    bar = "⬛" * filled + "⬜" * (width - filled)
    return f"{bar} {max(0, seconds_left)} soniya qoldi"


def _weekly_report_text(uid):
    u = user_dict(uid)
    _, streak = _points_summary(uid)
    return (
        f"📅 <b>Haftalik hisobot</b>\n\n"
        f"🎮 Jami o'yinlar: <b>{u.get('games', 0)}</b>\n"
        f"🏆 G'alabalar: <b>{u.get('wins', 0)}</b>\n"
        f"🔥 Joriy seriya: <b>{streak}</b>\n"
        f"💰 Balans: <b>{u.get('dollar', 0)}$ / {u.get('diamond', 0)}💎</b>\n\n"
        f"👇 Yangi hafta — yangi imkoniyat!"
    )


def _weekly_report_loop():
    """📅 Har dushanba soat 09:00'da har bir foydalanuvchiga shaxsiy, qisqa
    haftalik statistika xabari yuboradi (reklama emas — faqat o'z natijasi).
    Mavjud kunlik 07:00 broadcast'ga o'xshab ishlaydi, lekin haftada bir marta
    va shaxsiylashtirilgan matn bilan."""
    last_sent_week = None
    while True:
        try:
            now_tashkent = time.gmtime(time.time() + 5 * 3600)
            year_week = time.strftime("%Y-%W", now_tashkent)
            if now_tashkent.tm_wday == 0 and now_tashkent.tm_hour == 9 and last_sent_week != year_week:
                last_sent_week = year_week
                with db_lock:
                    cur.execute("SELECT user_id FROM users WHERE games > 0")
                    user_ids = [r[0] for r in cur.fetchall()]
                sent, failed = 0, 0
                for target_uid in user_ids:
                    try:
                        bot.send_message(target_uid, _weekly_report_text(target_uid))
                        sent += 1
                    except Exception:
                        failed += 1
                    time.sleep(0.05)
                _logger.info("📅 Haftalik hisobot yuborildi: %s ta muvaffaqiyatli, %s ta yetib bormadi.", sent, failed)
        except Exception as e:
            _logger.warning("_weekly_report_loop xatolik: %s", e)
        time.sleep(60)


def start_weekly_report_loop():
    t = threading.Thread(target=_weekly_report_loop, daemon=True)
    t.start()


