def _v10_seed_territories():
    with db_lock:
        cur.execute("SELECT COUNT(*) FROM territories")
        if cur.fetchone()[0] == 0:
            for i, name in enumerate(TERRITORY_NAMES, start=1):
                cur.execute("INSERT INTO territories (id, name, owner_id, captured_at) VALUES (?,?,?,?)",
                            (i, name, None, 0))
            conn.commit()


_v10_seed_territories()


def v10_territories():
    with db_lock:
        cur.execute("SELECT id, name, owner_id FROM territories ORDER BY id")
        rows = cur.fetchall()
    return [{"id": r[0], "name": r[1], "owner_id": r[2]} for r in rows]


def v10_capture_territory(winner_owner_id, loser_owner_id):
    """⚔️ Klan jangida g'olib chiqqan klan hudud oladi:
    1) Avval mag'lub klanning egalik qilgan hududlaridan BIRINI tortib oladi (bo'lsa).
    2) Bo'lmasa — hali hech kim egallamagan ERKIN hududlardan birini egallaydi.
    3) Ikkalasi ham bo'lmasa (barcha hudud allaqachon shu g'olibda yoki band) — hech narsa qaytmaydi.
    Qaytaradi: egallangan hudud nomi yoki None."""
    with db_lock:
        cur.execute("SELECT id, name FROM territories WHERE owner_id=?", (loser_owner_id,))
        losers_land = cur.fetchall()
        if losers_land:
            tid, tname = random.choice(losers_land)
        else:
            cur.execute("SELECT id, name FROM territories WHERE owner_id IS NULL")
            free_land = cur.fetchall()
            if not free_land:
                return None
            tid, tname = random.choice(free_land)
        cur.execute("UPDATE territories SET owner_id=?, captured_at=? WHERE id=?",
                    (winner_owner_id, time.time(), tid))
        conn.commit()
    return tname


@bot.message_handler(commands=["dunyo"])
def cmd_dunyo(message):
    """🗺 Hunter World — umumiy hudud xaritasi: qaysi klan qaysi hududga ega."""
    maybe_capture_owner(message.from_user)
    lands = v10_territories()
    lines = ["🗺 <b>Hunter World — umumiy hudud xaritasi</b>\n"]
    owned = 0
    for t in lands:
        if t["owner_id"]:
            clan = get_clan(t["owner_id"])
            owner_label = f"🚩 {clan['name']}" if clan else "🚩 (klan topilmadi)"
            owned += 1
        else:
            owner_label = "⚪ Erkin"
        lines.append(f"{t['name']} — {owner_label}")
    lines.append(f"\n📊 Egallangan: {owned}/{len(lands)} hudud")
    lines.append("⚔️ Hudud olish uchun: <code>/klanjang</code> orqali klan jangida g'alaba qozoning!")
    bot.send_message(message.chat.id, "\n".join(lines))


