# -------------------------------------------------------------------- 🎲 TASODIFIY VOQEALAR
# O'yin bo'lmagan paytda ham guruhni jonli tutish uchun — bot vaqti-vaqti bilan
# tasodifiy guruhga tezkor mini-voqea yuboradi (v11 bo'limida 4 xil formatga kengaytiriladi).
RANDOM_EVENT_WINDOW_SECONDS = 25
RANDOM_EVENT_REWARD = 10
_V10_EVENT_STATE = {}  # chat_id -> {"mode": ..., "claimed": bool, "expires_at": float, ...}
_V10_EVENT_LOCK = threading.Lock()


@bot.callback_query_handler(func=lambda c: c.data == "v10ev|claim")
def cb_v10_event_claim(call):
    """⚡️ "Birinchi bosgan yutadi" VA 🎯 "Ikkinchi bosgan yutadi" (v11, reverse) —
    ikkala format ham shu yerda hal qilinadi (mode maydoniga qarab)."""
    chat_id = call.message.chat.id
    with _V10_EVENT_LOCK:
        st = _V10_EVENT_STATE.get(chat_id)
        if not st or st.get("message_id") != call.message.message_id or st["claimed"] or time.time() > st["expires_at"]:
            bot.answer_callback_query(call.id, "⌛ Kech qoldingiz yoki voqea tugagan!", show_alert=True)
            return
        if st.get("mode") == "reverse":
            st["click_count"] = st.get("click_count", 0) + 1
            if st["click_count"] == 1:
                bot.answer_callback_query(call.id, "😏 Kutib turing...")
                return
        st["claimed"] = True
    uid = call.from_user.id
    name = call.from_user.first_name or "O'yinchi"
    add_balance(uid, dollar=RANDOM_EVENT_REWARD)
    try:
        if st.get("mode") == "reverse":
            bot.edit_message_text(f"🎯 <b>{esc(name)}</b> IKKINCHI bosib, hammani ortda qoldirdi! +{RANDOM_EVENT_REWARD}$",
                                   chat_id, call.message.message_id)
        else:
            bot.edit_message_text(f"⚡️ <b>{esc(name)}</b> hammadan tezroq bosdi va +{RANDOM_EVENT_REWARD}$ yutib oldi!",
                                   chat_id, call.message.message_id)
    except Exception:
        pass
    bot.answer_callback_query(call.id, f"🎉 +{RANDOM_EVENT_REWARD}$ yutdingiz!", show_alert=True)


def v10_send_random_event():
    """⚡️ Klassik "birinchi bosgan yutadi" format (v11_send_random_event uni bitta format
    sifatida ishlatadi)."""
    groups = [g for g in list_known_groups() if gsv(g[0], "world_events") != "0"]
    if not groups:
        return
    chat_id, _title = random.choice(groups)
    kb = types.InlineKeyboardMarkup()
    kb.add(types.InlineKeyboardButton(f"⚡️ Bos! (birinchi oladi, +{RANDOM_EVENT_REWARD}$)", callback_data="v10ev|claim"))
    try:
        msg = bot.send_message(chat_id, "🎁 <b>Tasodifiy voqea!</b>\nBirinchi bosgan kishi mukofot oladi!", reply_markup=kb)
    except Exception:
        return
    with _V10_EVENT_LOCK:
        _V10_EVENT_STATE[chat_id] = {"mode": "first", "message_id": msg.message_id, "claimed": False,
                                      "expires_at": time.time() + RANDOM_EVENT_WINDOW_SECONDS}


