# -------------------------------------------------------------------- 🃏 XARAKTER KARTALARI
# O'yin natijasiga qarab tasodifiy tushadigan noyob kolleksion kartalar.
CHARACTER_CARDS = {
    "sovuq_komissar": {"name": "🕵️ Sovuq qonli Komissar", "chance": 0.12, "cond": lambda role, won: role and "Komissar" in role and won},
    "omadli_qochqin": {"name": "🏃 Omadli Qochqin", "chance": 0.12, "cond": lambda role, won: role and not won},
    "sadoqatli_doktor": {"name": "💉 Sadoqatli Doktor", "chance": 0.15, "cond": lambda role, won: role and "Doktor" in role and won},
    "qora_niqob": {"name": "🎭 Qora Niqob", "chance": 0.10, "cond": lambda role, won: role and ("Mafiya" in role or "Don" in role) and won},
    "yolg'iz_boru": {"name": "🐺 Yolg'iz Bo'ri", "chance": 0.08, "cond": lambda role, won: role and "Yolg'iz" in role},
    "faol_qahramon": {"name": "🏅 Faol Qahramon", "chance": 1.0, "cond": lambda role, won: False},  # faqat MVP uchun quyida alohida beriladi
}


def v10_maybe_drop_card(uid, role, won, is_mvp=False):
    """O'yin natijasi shartlariga mos kelsa — tasodifiy foiz bilan noyob karta beradi.
    Qaytaradi: karta nomi (matn) yoki None."""
    candidates = []
    if is_mvp:
        candidates.append("faol_qahramon")
    for card_id, c in CHARACTER_CARDS.items():
        if card_id == "faol_qahramon":
            continue
        try:
            if c["cond"](role, won) and random.random() < c["chance"]:
                candidates.append(card_id)
        except Exception:
            pass
    if not candidates:
        return None
    card_id = random.choice(candidates)
    card_name = CHARACTER_CARDS[card_id]["name"]
    try:
        with db_lock:
            cur.execute("INSERT INTO user_cards (user_id, card_id, count, obtained_at) VALUES (?,?,1,?) "
                        "ON CONFLICT(user_id, card_id) DO UPDATE SET count=count+1, obtained_at=excluded.obtained_at",
                        (uid, card_id, time.time()))
            conn.commit()
    except Exception as e:
        _logger.warning("Karta saqlashda xatolik: %s", e)
        return None
    return card_name


@bot.message_handler(commands=["kartalarim"])
def cmd_kartalarim(message):
    """🃏 Yig'ilgan noyob xarakter kartalari to'plami."""
    maybe_capture_owner(message.from_user)
    uid = message.from_user.id
    with db_lock:
        cur.execute("SELECT card_id, count FROM user_cards WHERE user_id=?", (uid,))
        rows = cur.fetchall()
    if not rows:
        bot.send_message(message.chat.id, "🃏 Sizda hali kartalar yo'q — o'ynang va noyob shartlarni bajarib, "
                                           "tasodifiy kartalar yutib oling!")
        return
    owned = {r[0]: r[1] for r in rows}
    lines = [f"🃏 <b>Kartalar to'plamingiz</b> ({len(owned)}/{len(CHARACTER_CARDS)})\n"]
    for card_id, c in CHARACTER_CARDS.items():
        if card_id in owned:
            lines.append(f"✅ {c['name']} — x{owned[card_id]}")
        else:
            lines.append(f"⬛ ??? — hali topilmagan")
    bot.send_message(message.chat.id, "\n".join(lines))


# -------------------------------------------------------------------- 🧩 SIRLI TOPSHIRIQ ZANJIRI (ARG)
# Bot egasi vaqti-vaqti bilan BARCHA guruhlarga umumiy sirli jumboq(lar) tashlaydi.
# /jumboq va /jumboq_qosh buyruqlarining ZANJIRLI (3 bosqichli) versiyalari PASTDA,
# "v11" bo'limida ro'yxatdan o'tkaziladi — bu yerda faqat yordamchi funksiya qoladi.
def _v10_normalize_answer(s):
    return (s or "").strip().lower().replace("'", "'").replace("`", "'")



def start_v10_loop():
    t = threading.Thread(target=_v10_event_loop, daemon=True)
    t.start()


# ================================================================================
#  🆕 v11 — HUNTER WORLD CHUQURLASHTIRISH (v10 ustiga qo'shiladi): mustahkamlangan/
#  poytaxt hududlar, imperiya bonusi, afsonalar layk+oy afsonasi, taqdir filiallari,
#  4 xil tasodifiy voqea, karta kombinatsiya bonusi, karta almashish, ARG zanjiri.
# ================================================================================

with db_lock:
    # Mavjud jadvallarga yangi ustunlar (SQLite'da "ADD COLUMN IF NOT EXISTS" yo'q,
    # shu sabab try/except bilan xavfsiz qo'shiladi — fayl necha marta ishga
    # tushirilsa ham xato bermaydi).
    for alter_sql in [
        "ALTER TABLE territories ADD COLUMN fortified_since REAL",
        "ALTER TABLE territories ADD COLUMN captures INTEGER NOT NULL DEFAULT 0",
        "ALTER TABLE legends ADD COLUMN likes INTEGER NOT NULL DEFAULT 0",
        "ALTER TABLE legends ADD COLUMN is_month_legend INTEGER NOT NULL DEFAULT 0",
        "ALTER TABLE arg_puzzles ADD COLUMN chain_stage INTEGER NOT NULL DEFAULT 1",
        "ALTER TABLE arg_puzzles ADD COLUMN chain_id INTEGER",
        "ALTER TABLE arg_puzzles ADD COLUMN territory_reward INTEGER NOT NULL DEFAULT 0",
    ]:
        try:
            cur.execute(alter_sql)
        except Exception as _mig_exc:
            _migration_ignore(_mig_exc, alter_sql)
    cur.execute("""CREATE TABLE IF NOT EXISTS legend_likes (
        legend_id INTEGER NOT NULL, user_id INTEGER NOT NULL,
        PRIMARY KEY (legend_id, user_id)
    )""")
    cur.execute("""CREATE TABLE IF NOT EXISTS card_trades (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        from_uid INTEGER NOT NULL, to_uid INTEGER NOT NULL,
        from_card TEXT NOT NULL, to_card TEXT NOT NULL,
        from_ok INTEGER NOT NULL DEFAULT 0, to_ok INTEGER NOT NULL DEFAULT 0,
        status TEXT NOT NULL DEFAULT 'pending', created_at REAL NOT NULL
    )""")
    conn.commit()


# ================================================================================
#  🗺 1) HUNTER WORLD — hudud turiga qarab bonus, mustahkamlanish, imperiya
# ================================================================================
# Har hudud ID'siga (v10 TERRITORY_NAMES tartibida 1..10) bog'langan bonus turi.
TERRITORY_BONUS = {
    1: ("clan_power", 1),      # 🏰 Qora qal'a — klan jangida +1 zarba kuchi
    2: ("clan_xp", 10),        # 🌲 Sharq o'rmoni — klan a'zolariga +10% tajriba
    3: ("clan_income", 5),     # 🏔 Kumush tog'lar — +5% xazina daromadi
    4: ("clan_income", 4),     # 🏜 Qumli chegara
    5: ("clan_xp", 8),         # 🌊 Ko'k qirg'oq
    6: ("clan_power", 1),      # 🏚 Xarob shahar
    7: ("clan_income", 6),     # ⛏ Oltin konlar — eng yuqori daromad bonusi
    8: ("clan_xp", 6),         # 🌾 Vodiy dalalari
    9: ("clan_power", 1),      # 🌋 Yonar tog' etagi
    10: ("clan_income", 4),    # 🕯 Soya bozori
}
FORTIFY_DAYS = 7          # shuncha kun uzluksiz egalik → "mustahkamlangan"
CAPITAL_DAYS = 30         # shuncha kun → "poytaxt" (avtomatik tortib olinmaydi)
EMPIRE_THRESHOLD = 6      # shuncha hudud (10 tadan) → "imperiya" e'lon qilinadi
EMPIRE_INCOME_BONUS_HOURS = 24


def v11_territory_bonus(owner_id, bonus_type):
    """Klan egasining barcha hududlaridan shu turdagi bonuslarni yig'ib, % qaytaradi.
    Masalan v11_territory_bonus(owner_id, "clan_income") → jami % (masalan 9)."""
    total = 0
    with db_lock:
        cur.execute("SELECT id FROM territories WHERE owner_id=?", (owner_id,))
        ids = [r[0] for r in cur.fetchall()]
    for tid in ids:
        btype, val = TERRITORY_BONUS.get(tid, (None, 0))
        if btype == bonus_type:
            total += val
    return total


def v11_capture_territory_deep(winner_owner_id, loser_owner_id):
    """v10_capture_territory() ning o'rniga chaqiriladigan 'chuqur' versiya:
    mustahkamlangan/poytaxt hududlarni hisobga oladi, imperiya e'lonini tekshiradi.
    Qaytaradi: (hudud_nomi yoki None, imperiya_xabari yoki None)."""
    with db_lock:
        cur.execute("SELECT id, name, fortified_since, captured_at FROM territories WHERE owner_id=?",
                    (loser_owner_id,))
        losers_land = cur.fetchall()

    capturable = []
    for tid, tname, fortified_since, captured_at in losers_land:
        days_held = (time.time() - (captured_at or 0)) / 86400
        if days_held >= CAPITAL_DAYS:
            continue  # 👑 Poytaxt — oddiy jang bilan tortib olib bo'lmaydi
        capturable.append((tid, tname, days_held >= FORTIFY_DAYS))

    tname_final = None
    if capturable:
        # 🛡 mustahkamlangan hududlar bo'lsa — 50% ehtimol bilan jang "yutilmaydi"
        # (ya'ni real hayotda "2 marta yutish kerak" qoidasi shu yerda 1 chaqiriqqa
        # tushiriladi: agar hudud mustahkam bo'lsa, uni olish 50% shansga bog'liq)
        tid, tname, fortified = random.choice(capturable)
        if fortified and random.random() < 0.5:
            tname_final = None  # bu safar qaytarib bo'lmadi, keyingi jangda urinib ko'ring
        else:
            with db_lock:
                cur.execute("UPDATE territories SET owner_id=?, captured_at=?, fortified_since=NULL, "
                            "captures=captures+1 WHERE id=?", (winner_owner_id, time.time(), tid))
                conn.commit()
            tname_final = tname
    else:
        with db_lock:
            cur.execute("SELECT id, name FROM territories WHERE owner_id IS NULL")
            free_land = cur.fetchall()
        if free_land:
            tid, tname = random.choice(free_land)
            with db_lock:
                cur.execute("UPDATE territories SET owner_id=?, captured_at=?, captures=captures+1 WHERE id=?",
                            (winner_owner_id, time.time(), tid))
                conn.commit()
            tname_final = tname

    empire_msg = None
    with db_lock:
        cur.execute("SELECT COUNT(*) FROM territories WHERE owner_id=?", (winner_owner_id,))
        owned_count = cur.fetchone()[0]
    if owned_count >= EMPIRE_THRESHOLD:
        clan = get_clan(winner_owner_id)
        if clan:
            set_setting(f"empire_bonus_until_{winner_owner_id}", str(time.time() + EMPIRE_INCOME_BONUS_HOURS * 3600))
            empire_msg = (f"🌍 <b>HUNTER WORLD IMPERIYASI!</b>\n\n<b>{esc(clan['name'])}</b> klani {owned_count} ta hududni "
                          f"({EMPIRE_THRESHOLD}+) egalladi va butun dunyoga hukmronlik e'lon qildi!\n"
                          f"⚡️ Keyingi {EMPIRE_INCOME_BONUS_HOURS} soat davomida klan daromadiga +15% bonus!")
            for chat_id, _t in list_known_groups():
                try:
                    bot.send_message(chat_id, empire_msg)
                except Exception:
                    pass
    return tname_final, empire_msg


def v11_mark_fortifications():
    """Fon siklida chaqiriladi: FORTIFY_DAYS dan ko'p vaqt bir egada turgan
    hududlarga fortified_since belgisini qo'yadi (faqat belgi uchun, /dunyo'da ko'rinadi)."""
    with db_lock:
        cur.execute("SELECT id, owner_id, captured_at, fortified_since FROM territories WHERE owner_id IS NOT NULL")
        rows = cur.fetchall()
        now = time.time()
        for tid, owner_id, captured_at, fortified_since in rows:
            days = (now - (captured_at or now)) / 86400
            if days >= FORTIFY_DAYS and not fortified_since:
                cur.execute("UPDATE territories SET fortified_since=? WHERE id=?", (now, tid))
        conn.commit()


def v11_territory_status_label(tid, owner_id, captured_at):
    if not owner_id:
        return ""
    days = (time.time() - (captured_at or time.time())) / 86400
    if days >= CAPITAL_DAYS:
        return " 👑"
    if days >= FORTIFY_DAYS:
        return " 🛡"
    return ""


