#  🎭 3) TAQDIR YO'LI — filiallar (Himoyachi/Soyaboshi) + guruh reytingi
# ================================================================================
PROTECTOR_ROLES_HINT = ("Komissar", "Doktor")
SHADOW_ROLES_HINT = ("Mafiya", "Don")

DESTINY_BRANCHES = {
    "protector": [
        (0, "🌱 Yangi Himoyachi"), (5, "🛡 Sinovdan O'tgan Qalqon"),
        (15, "⚕️ Ishonchli Muhofaza"), (30, "🏅 Shahar Farishtasi"),
        (60, "👼 Himoyachilar Afsonasi"),
    ],
    "shadow": [
        (0, "🌑 Yangi Soya"), (5, "🗡 Sinalgan Fitnachi"),
        (15, "🎭 Mohir Aldamchi"), (30, "🐺 Soya Lideri"),
        (60, "👑 Soyaboshi Afsonasi"),
    ],
}


def v11_destiny_branch(uid):
    """Rol statistikasi asosida qaysi filialga (himoyachi/soyaboshi/neytral)
    tegishli ekanini va shu filialdagi unvonni hisoblaydi."""
    stats = role_stats_of(uid)
    prot_games = sum(s["games"] for s in stats if any(r in s["role"] for r in PROTECTOR_ROLES_HINT))
    shad_games = sum(s["games"] for s in stats if any(r in s["role"] for r in SHADOW_ROLES_HINT))
    u = user_dict(uid)
    games = u.get("games", 0)

    if prot_games == 0 and shad_games == 0:
        return None, None  # hali filial aniqlanmagan — oddiy compute_destiny() ishlatiladi
    branch = "protector" if prot_games >= shad_games else "shadow"
    ladder = DESTINY_BRANCHES[branch]
    title = ladder[0][1]
    for threshold, t in ladder:
        if games >= threshold:
            title = t
    return branch, title


@bot.message_handler(commands=["taqdirim"])
def cmd_taqdirim_v11(message):
    """🎭 v10'dagi /taqdirim ni ALMASHTIRADI: endi filial (Himoyachi/Soyaboshi)
    aniqlansa o'sha unvon, aks holda oddiy umumiy unvon ko'rsatiladi."""
    maybe_capture_owner(message.from_user)
    uid = message.from_user.id
    branch, branch_title = v11_destiny_branch(uid)
    _, base_text = compute_destiny(uid)
    if branch:
        branch_label = "🛡 Himoyachilar yo'li" if branch == "protector" else "🗡 Soyaboshilar yo'li"
        badge = "\n\n👼 <b>Eng yuqori maxsus nishon ochildi!</b>" if branch_title.startswith(("👼", "👑")) else ""
        text = (f"🎭 <b>Taqdir yo'lingiz:</b> {branch_title}\n<i>({branch_label})</i>{badge}\n\n" + base_text.split("\n\n", 1)[-1])
    else:
        text = base_text
    bot.send_message(message.chat.id, text)


@bot.message_handler(commands=["taqdirlar"])
def cmd_taqdirlar(message):
    """🎭 Guruhdagi eng faol o'yinchilarning taqdir unvonlarini ko'rsatadi
    (umumiy /top serverdan farqli — bu shu guruhda oxirgi marta o'ynagan
    o'yinchilar bo'yicha, kim ekanini profildan bilamiz)."""
    maybe_capture_owner(message.from_user)
