# ================================================================================
TRIVIA_QA = [
    ("Hunter Mafia'da nechta asosiy jamoa bor? (raqam bilan javob bering)", "3"),
    ("Klan jangida g'olib nechta lvl-up token oladi?", "3"),
    ("Tunda birinchi bo'lib kim uyg'onadi — Mafiya yoki Doktor? (bitta so'z)", "mafiya"),
]


def v11_send_random_event():
    """v10_send_random_event() o'rniga chaqiriladi — 4 formatdan birini tasodifiy tanlaydi."""
    groups = [g for g in list_known_groups() if gsv(g[0], "world_events") != "0"]
    if not groups:
        return
    chat_id, _title = random.choice(groups)
    fmt = random.choice(["first", "number", "reverse", "trivia"])

    if fmt == "first":
        v10_send_random_event()  # mavjud, o'zgarishsiz format
        return

    if fmt == "number":
        target = random.randint(1, 50)
        with _V10_EVENT_LOCK:
            _V10_EVENT_STATE[chat_id] = {"mode": "number", "target": target, "guesses": {},
                                          "expires_at": time.time() + 40, "claimed": False}
        try:
            bot.send_message(chat_id, "🔢 <b>Tasodifiy voqea!</b>\nMen 1 dan 50 gacha son o'yladim. "
                                       "Kim eng yaqin taxmin qilsa — g'olib!\n✏️ <code>/topraqam son</code>")
        except Exception:
            pass
        return

    if fmt == "reverse":
        kb = types.InlineKeyboardMarkup()
        kb.add(types.InlineKeyboardButton(f"🎯 Bos! (IKKINCHI bosgan yutadi)", callback_data="v10ev|claim"))
        try:
            msg = bot.send_message(chat_id, "🎯 <b>Aksincha voqea!</b>\nBu safar BIRINCHI bosgan emas, "
                                             "IKKINCHI bosgan yutadi! Shoshilmang 😏", reply_markup=kb)
        except Exception:
            return
        with _V10_EVENT_LOCK:
            _V10_EVENT_STATE[chat_id] = {"mode": "reverse", "message_id": msg.message_id, "click_count": 0,
                                          "claimed": False, "expires_at": time.time() + 40}
        return

    if fmt == "trivia":
        q, a = random.choice(TRIVIA_QA)
        with _V10_EVENT_LOCK:
            _V10_EVENT_STATE[chat_id] = {"mode": "trivia", "answer": a.lower(), "claimed": False,
                                          "expires_at": time.time() + 60}
        try:
            bot.send_message(chat_id, f"🧠 <b>Tezkor savol!</b>\n{q}\n\n✏️ Javobni oddiy xabar qilib yozing.")
        except Exception:
            pass


@bot.message_handler(commands=["topraqam"])
def cmd_topraqam(message):
    chat_id = message.chat.id
    with _V10_EVENT_LOCK:
        st = _V10_EVENT_STATE.get(chat_id)
        if not st or st.get("mode") != "number" or st["claimed"] or time.time() > st["expires_at"]:
            return
        parts = (message.text or "").split()
        if len(parts) < 2:
            return
        try:
            guess = int(parts[1])
        except ValueError:
            return
        st["guesses"][message.from_user.id] = (guess, message.from_user.first_name or "O'yinchi")


def _v11_resolve_number_event(chat_id, st):
    if not st["guesses"]:
        return
    target = st["target"]
    winner_uid, (winner_guess, winner_name) = min(st["guesses"].items(), key=lambda kv: abs(kv[1][0] - target))
    add_balance(winner_uid, dollar=RANDOM_EVENT_REWARD)
    try:
        bot.send_message(chat_id, f"🔢 Men <b>{target}</b> ni o'ylagan edim!\n🏆 <b>{esc(winner_name)}</b> "
                                   f"eng yaqin taxmin ({winner_guess}) bilan +{RANDOM_EVENT_REWARD}$ yutdi!")
    except Exception:
        pass


@bot.message_handler(func=lambda m: m.chat.id in _V10_EVENT_STATE and
                      _V10_EVENT_STATE[m.chat.id].get("mode") == "trivia" and
                      not _V10_EVENT_STATE[m.chat.id]["claimed"] and
                      time.time() <= _V10_EVENT_STATE[m.chat.id]["expires_at"] and
                      (m.text or "").strip().lower() == _V10_EVENT_STATE[m.chat.id]["answer"])
def cmd_trivia_answer(message):
    chat_id = message.chat.id
    with _V10_EVENT_LOCK:
        st = _V10_EVENT_STATE.get(chat_id)
        if not st or st["claimed"]:
            return
        st["claimed"] = True
    uid = message.from_user.id
    name = message.from_user.first_name or "O'yinchi"
    add_balance(uid, dollar=RANDOM_EVENT_REWARD)
    bot.send_message(chat_id, f"🧠 <b>{esc(name)}</b> to'g'ri javob berdi va +{RANDOM_EVENT_REWARD}$ yutdi!")


def _v11_event_timeout_sweeper():
    """Fon siklida: muddati o'tgan 'number' voqealarni yakunlaydi."""
    with _V10_EVENT_LOCK:
        items = list(_V10_EVENT_STATE.items())
    now = time.time()
    for chat_id, st in items:
        if st.get("mode") == "number" and not st["claimed"] and now > st["expires_at"]:
            with _V10_EVENT_LOCK:
                st["claimed"] = True
            _v11_resolve_number_event(chat_id, st)


