def _oc_elite(days, fld, unit, mx):
    def plan():
        return next(p for p in ELITE_PLANS if p["days"] == days)

    default = next(p for p in _ELITE_PLANS_DEFAULT if p["days"] == days)[fld]

    def get():
        return plan()[fld]

    def put(v):
        plan()[fld] = int(v)

    _oc_add(f"elite:{days}:{fld}", f"👑 PRIME {days} kun — {'olmos' if fld == 'diamond' else 'Stars'} narxi", "shop",
            "👑 PRIME tariflari", unit, int, 1, mx, default, get, put,
            lambda v: ("elite_plans_json", json.dumps(ELITE_PLANS, ensure_ascii=False)),
            risk=True, dynamic=True, search="elite vip narx")


def _oc_hero(tier, tlabel, item):
    skey = f"hero_price_{tier}_{item}"
    default = HERO_PRICE_DEFAULTS[tier][item]
    is_dollar = item.endswith("dollar")
    names = {"lv2": "2-daraja (keyingilari oshib boradi)", "charge": "Qurolni zaryadlash", "rename": "Ismni o'zgartirish"}
    nm = names[item.split("_")[0]]

    def get():
        return hero_price("soya", item)

    _oc_add(f"hero:{tier}:{item}", f"👑 {nm} — {'💵 dollar' if is_dollar else '💎 olmos'}", "hero", tlabel,
            "💵" if is_dollar else "💎", int, 1, 10000000 if is_dollar else 100000, default, get, lambda v: None,
            lambda v: (skey, str(int(v))), risk=True, dynamic=True, search="hero geroy qahramon narx " + tier)


def _oc_shop_flag(cat_key, ikey, name):
    skey = f"oc_shopoff_{cat_key}_{ikey}"

    def get():
        return 1 if oc_shop_on(cat_key, ikey) else 0

    def put(v):
        (OC_SHOP_OFF.discard if int(v) else OC_SHOP_OFF.add)(cat_key + ":" + ikey)

    _oc_bool(f"shopon:{cat_key}:{ikey}", name, "shop", "🟢 Sotuv holati (sotuvda/yopiq)", get, put, skey,
             search="shop do'kon sotuv availability " + ikey)


def _oc_recompute_derived():
    """DAY_VOTE_SECONDS = umumiy − muhokama (modul yuklanganda bir marta hisoblangan edi)."""
    globals()["DAY_VOTE_SECONDS"] = int(DAY_TOTAL_SECONDS) - int(DAY_DISCUSSION_SECONDS)


# ----------------------------------------------------------------- ✅ VALIDATSIYA, YOZISH, TARIX
def oc_fmt(p, v):
    if p["typ"] is bool:
        return "🟢 Yoqilgan" if int(v) else "🔴 O'chirilgan"
    if isinstance(v, float):
        s = ("%g" % v)
    else:
        s = f"{int(v):,}".replace(",", " ")
    return f"{s} {p['unit']}".strip()


def oc_parse(p, raw):
    """(qiymat, xato) — kiritilgan matnni qat'iy tekshiradi."""
    raw = (raw or "").strip().replace(" ", "")
    if not raw:
        return None, "Qiymat kiritilmadi."
    if len(raw) > 18:
        return None, "Qiymat juda uzun."
    if p["typ"] is int:
        if not re.fullmatch(r"-?\d+", raw):
            return None, "Faqat butun son kiriting (masalan: 750). Harf, kasr va belgilar mumkin emas."
        val = int(raw)
    elif p["typ"] is float:
        if not re.fullmatch(r"-?\d+(?:[.,]\d+)?", raw):
            return None, "Son kiriting (masalan: 1.15)."
        val = float(raw.replace(",", "."))
        if not math.isfinite(val):
            return None, "Noto'g'ri son."
    else:
        return None, "Bu qiymat tugma orqali o'zgartiriladi."
    if val < p["min"] or val > p["max"]:
        return None, f"Ruxsat etilgan oraliq: {('%g' % p['min'])} … {('%g' % p['max'])} {p['unit']}".strip()
    if p["check"]:
        err = p["check"](val)
        if err:
            return None, err
    return val, None


def oc_is_risky(p, old, new):
    if not p["risk"] or p["typ"] is bool:
        return False
    try:
        return old == 0 or new >= old * 2 or new <= old / 2
    except Exception:
        return True


def oc_commit(uid, p, new, action="change"):
    """Atomik yangilash: runtime + saqlash + tarix. Muvaffaqiyatsiz bo'lsa eski qiymat qaytariladi."""
    with _OC_LOCK:
        old = p["get"]()
        if old == new:
            return False, "Qiymat allaqachon shunday."
        try:
            p["put"](new)
            if p["post"]:
                p["post"](new)
            skey, sval = p["store"](new)
            with db_lock:
                cur.execute("INSERT OR REPLACE INTO bot_settings (key, value) VALUES (?,?)", (skey, sval))
                cur.execute("INSERT INTO oc_history (ts, owner_id, pkey, label, old, new, action, scope) VALUES (?,?,?,?,?,?,?,?)",
                            (time.time(), uid, p["key"], p["label"], str(old), str(new), action, "global"))
                conn.commit()
        except Exception:
            _logger.exception("OWNER CENTER: yangilash muvaffaqiyatsiz — eski qiymat tiklanmoqda (%s)", p["key"])
            try:
                with db_lock:
                    conn.rollback()
            except Exception:
                pass
            try:
                p["put"](old)
                if p["post"]:
                    p["post"](old)
            except Exception:
                pass
            return False, "Saqlashda xatolik — eski qiymat saqlanib qoldi."
    return True, "ok"


def oc_log_external(uid, key, label, old, new, action, scope="global"):
    with db_lock:
        try:
            cur.execute("INSERT INTO oc_history (ts, owner_id, pkey, label, old, new, action, scope) VALUES (?,?,?,?,?,?,?,?)",
                        (time.time(), uid, key, label, str(old), str(new), action, scope))
            conn.commit()
        except Exception:
            # O'zgarishlar tarixi yozilmasa ham sozlama o'zgarishi bekor qilinmaydi, lekin iz yo'qolgani log'da bo'ladi.
            conn.rollback()
            _logger.warning("oc_log_external: o'zgarish tarixi yozilmadi (key=%s)", key, exc_info=True)


def oc_load_all():
    """Bot ishga tushganda: saqlangan qiymatlarni runtime'ga qo'llaydi (standart faqat saqlanmagan bo'lsa)."""
    for p in OC_PARAMS:
        if p["dynamic"] and p["key"].startswith("elite:"):
            continue  # PRIME — mavjud _load_elite_plans_from_settings() yuklaydi
        if p["dynamic"]:
            continue  # hero narxi har chaqiruvda bazadan o'qiladi
        try:
            skey, _ = p["store"](p["default"])
            raw = get_setting(skey)
            if raw in (None, ""):
                continue
            if p["typ"] is bool:
                p["put"](1 if str(raw) == "1" else 0)
                continue
            val = p["typ"](float(raw)) if p["typ"] is int else float(raw)
            if not (p["min"] <= val <= p["max"]):
                _logger.warning("OWNER CENTER: saqlangan qiymat oraliqdan tashqari, e'tiborga olinmadi: %s=%s", p["key"], raw)
                continue
            p["put"](val)
        except Exception:
            _logger.exception("OWNER CENTER: %s yuklanmadi", p["key"])
    _oc_recompute_derived()
    try:
        _hc_clamp_rate()
    except Exception:
        pass


# ----------------------------------------------------------------- 🖥 EKRANLAR
_OC_INPUT = {}     # owner_id -> {"mode", "key"/"cat", "chat", "mid", "ts"}
_OC_TOKENS = {}    # token -> {"uid","kind","items":[(key,old,new)],"risky","warned","ts"}


def _oc_cleanup():
    now = time.time()
    with _OC_LOCK:
        for k in [k for k, v in _OC_TOKENS.items() if now - v["ts"] > OC_STATE_TTL]:
            _OC_TOKENS.pop(k, None)
        for k in [k for k, v in _OC_INPUT.items() if now - v["ts"] > OC_STATE_TTL]:
            _OC_INPUT.pop(k, None)


def _oc_btn(text, data):
    assert len(data.encode("utf-8")) <= 64, data
    return types.InlineKeyboardButton(text, callback_data=data)


def _oc_subs(cat):
    seen = []
    for p in OC_PARAMS:
        if p["cat"] == cat and p["sub"] not in seen:
            seen.append(p["sub"])
    return seen


