def _oc_crumb(cat=None, sub=None):
    s = "👑 OWNER CENTER"
    if cat:
        s += " › " + OC_CAT_NAME.get(cat, cat)
    if sub:
        s += " › " + sub
    return "📌 " + s


def _oc_cat_screen(cat):
    subs = _oc_subs(cat)
    if len(subs) == 1:
        return _oc_list_screen(cat, 0, 0)
    kb = types.InlineKeyboardMarkup(row_width=1)
    for i, sname in enumerate(subs):
        n = sum(1 for p in OC_PARAMS if p["cat"] == cat and p["sub"] == sname)
        kb.add(_oc_btn(f"{sname} ({n})", f"oc|l|{cat}|{i}|0"))
    if cat == "game":
        kb.add(_oc_btn("👥 Guruh sozlamalari (guruh tanlanadi)", "oc|grp|0"))
    kb.add(_oc_btn("↩️ Bo'limni defaultga qaytarish", f"oc|rc|{cat}"))
    kb.add(_oc_btn("⬅️ Orqaga", "oc|home"))
    return f"{_oc_crumb(cat)}\n\nBo'limni tanlang:", kb


def _oc_list_screen(cat, si, page):
    subs = _oc_subs(cat)
    if si >= len(subs):
        si = 0
    sname = subs[si]
    items = [p for p in OC_PARAMS if p["cat"] == cat and p["sub"] == sname]
    pages = max(1, (len(items) + OC_PAGE_SIZE - 1) // OC_PAGE_SIZE)
    page = max(0, min(page, pages - 1))
    chunk = items[page * OC_PAGE_SIZE:(page + 1) * OC_PAGE_SIZE]
    kb = types.InlineKeyboardMarkup(row_width=1)
    lines = [_oc_crumb(cat, sname), f"🌍 GLOBAL · sahifa {page + 1}/{pages}\n"]
    for p in chunk:
        val = p["get"]()
        mark = "" if val == p["default"] else " ✏️"
        lines.append(f"• {p['label']}: <b>{oc_fmt(p, val)}</b>{mark}")
        short = p["label"] if len(p["label"]) <= 34 else p["label"][:33] + "…"
        kb.add(_oc_btn(f"🌍 {short}: {oc_fmt(p, val)}", f"oc|e|{p['key']}"))
    nav = []
    if page > 0:
        nav.append(_oc_btn("◀️", f"oc|l|{cat}|{si}|{page - 1}"))
    if page < pages - 1:
        nav.append(_oc_btn("▶️", f"oc|l|{cat}|{si}|{page + 1}"))
    if nav:
        kb.row(*nav)
    if len(subs) == 1:
        kb.add(_oc_btn("↩️ Bo'limni defaultga qaytarish", f"oc|rc|{cat}"))
    kb.add(_oc_btn("⬅️ Orqaga", f"oc|c|{cat}" if len(subs) > 1 else "oc|home"))
    lines.append("\n✏️ belgisi — standartdan farq qiladi.")
    return "\n".join(lines), kb


