def _oc_new_token(uid, kind, items, risky=False):
    _oc_cleanup()
    tok = secrets.token_hex(4)
    with _OC_LOCK:
        _OC_TOKENS[tok] = {"uid": uid, "kind": kind, "items": items, "risky": risky, "warned": False, "ts": time.time()}
    return tok


def _oc_confirm_screen(tok):
    t = _OC_TOKENS[tok]
    items = t["items"]
    kb = types.InlineKeyboardMarkup(row_width=2)
    if len(items) == 1:
        key, old, new = items[0]
        p = OC_BY_KEY[key]
        head = {"set": "⚠️ <b>TASDIQLASH</b>", "reset": "↩️ <b>DEFAULTGA QAYTARISH</b>", "toggle": "⚠️ <b>TASDIQLASH</b>"}.get(t["kind"], "⚠️ <b>TASDIQLASH</b>")
        text = (f"{head}\n\n{_oc_crumb(p['cat'], p['sub'])}\n📌 {p['label']}\n🌍 GLOBAL\n\n"
                f"Eski qiymat:\n<b>{oc_fmt(p, old)}</b>\n\nYangi qiymat:\n<b>{oc_fmt(p, new)}</b>")
    else:
        text = f"↩️ <b>BO'LIMNI DEFAULTGA QAYTARISH</b>\n\n<b>{len(items)}</b> ta qiymat standartga qaytariladi:\n\n"
        for key, old, new in items[:12]:
            p = OC_BY_KEY[key]
            text += f"• {p['label']}: {oc_fmt(p, old)} → {oc_fmt(p, new)}\n"
        if len(items) > 12:
            text += f"… va yana {len(items) - 12} ta\n"
    if t["risky"] and not t["warned"]:
        text = ("⚠️ <b>DIQQAT</b>\n\nBu qiymat ko'p o'zgarsa economy balansiga kuchli ta'sir qiladi "
                "(keskin emissiya yoki narx sakrashi mumkin).\n\n" + text.split("\n\n", 1)[1])
        kb.add(_oc_btn("Davom etish", f"oc|go|{tok}"), _oc_btn("Bekor qilish", "oc|no"))
    else:
        kb.add(_oc_btn("✅ Tasdiqlash" if t["kind"] != "reset" else "✅ Ha", f"oc|ok|{tok}"),
               _oc_btn("❌ Bekor qilish" if t["kind"] != "reset" else "❌ Yo'q", "oc|no"))
    return text, kb


def _oc_show(target, text, kb):
    """target — CallbackQuery (joyida tahrir) yoki (chat_id, message_id) yoki chat_id."""
    if hasattr(target, "message"):
        smart_render(target, text, kb)
        return
    if isinstance(target, tuple):
        try:
            bot.edit_message_text(text, target[0], target[1], reply_markup=kb)
            return
        except Exception as e:
            if "not modified" in str(e).lower():
                return
        bot.send_message(target[0], text, reply_markup=kb)
        return
    bot.send_message(target, text, reply_markup=kb)


