# ----------------------------------------------------------------- 🔎 QIDIRUV, 📦 BACKUP
def _oc_search_results(query):
    q = (query or "").strip().casefold()
    if len(q) < 2:
        return []
    out = []
    for p in OC_PARAMS:
        hay = (p["label"] + " " + p["search"] + " " + p["key"] + " " + OC_CAT_NAME[p["cat"]] + " " + p["sub"]).casefold()
        if all(w in hay for w in q.split()):
            out.append(p)
    return out[:10]


def _oc_backup_payload():
    data = {}
    for p in OC_PARAMS:
        data[p["key"]] = p["get"]()
    return {"oc_config_backup": 1, "ts": time.time(), "values": data}


