def oc_try_restore_document(message):
    """Document handler'dan chaqiriladi: owner tiklash kutayotgan bo'lsa True qaytaradi."""
    uid = message.from_user.id
    st = _OC_INPUT.get(uid)
    if not st or st.get("mode") != "restore" or message.chat.type != "private":
        return False
    if not is_owner(uid):
        _OC_INPUT.pop(uid, None)
        return False
    _OC_INPUT.pop(uid, None)
    doc = message.document
    try:
        if not doc or not (doc.file_name or "").lower().endswith(".json") or (doc.file_size or 0) > 1024 * 1024:
            raise ValueError("Faqat .json (1 MB gacha) fayl qabul qilinadi.")
        raw = bot.download_file(bot.get_file(doc.file_id).file_path)
        data = json.loads(raw.decode("utf-8"))
        vals = data["values"] if data.get("oc_config_backup") == 1 else None
        if not isinstance(vals, dict):
            raise ValueError("Bu OWNER CENTER backup fayli emas.")
        items, skipped = [], 0
        for key, v in vals.items():
            p = OC_BY_KEY.get(key)
            if not p or isinstance(v, bool):
                skipped += 1
                continue
            if p["typ"] is bool:
                if v not in (0, 1):
                    skipped += 1
                    continue
                new = int(v)
            else:
                if not isinstance(v, (int, float)) or not math.isfinite(v):
                    skipped += 1
                    continue
                new = p["typ"](v)
                if not (p["min"] <= new <= p["max"]) or (p["typ"] is int and new != v):
                    skipped += 1
                    continue
            if new != p["get"]():
                items.append((key, p["get"](), new))
        if not items:
            bot.send_message(message.chat.id, f"ℹ️ Fayldagi qiymatlar hozirgi sozlamalar bilan bir xil (o'tkazib yuborilgan: {skipped}).")
            return True
        tok = _oc_new_token(uid, "restore", items, risky=False)
        lines = [f"📥 <b>TIKLASH</b> — {len(items)} ta qiymat o'zgaradi (o'tkazib yuborilgan: {skipped}):\n"]
        for key, old, new in items[:15]:
            p = OC_BY_KEY[key]
            lines.append(f"• {p['label']}: {oc_fmt(p, old)} → {oc_fmt(p, new)}")
        if len(items) > 15:
            lines.append(f"… va yana {len(items) - 15} ta")
        kb = types.InlineKeyboardMarkup(row_width=2)
        kb.add(_oc_btn("✅ Tasdiqlash", f"oc|ok|{tok}"), _oc_btn("❌ Bekor qilish", "oc|no"))
        bot.send_message(message.chat.id, "\n".join(lines), reply_markup=kb)
    except Exception as e:
        bot.send_message(message.chat.id, f"❌ Tiklab bo'lmadi: {esc(str(e))[:200]}")
    return True


# ----------------------------------------------------------------- 🔘 CALLBACK DISPATCH
def _oc_guard(call):
    """Har bir callback'da qayta tekshiriladi: haqiqiy owner + shaxsiy chat."""
    maybe_capture_owner(call.from_user)
    if not is_owner(call.from_user.id) or call.message is None or call.message.chat.type != "private":
        try:
            bot.answer_callback_query(call.id, "⛔ Ruxsat yo'q.", show_alert=True)
        except Exception:
            pass
        return False
    return True


def oc_open(chat_id, uid):
    """👑 OWNER CENTER ni yangi xabar sifatida ochadi (faqat owner)."""
    if not is_owner(uid):
        return False
    text, kb = _oc_home_screen()
    bot.send_message(chat_id, text, reply_markup=kb)
    return True


def _oc_apply_token(call, tok):
    uid = call.from_user.id
    with _OC_LOCK:
        t = _OC_TOKENS.get(tok)
        if (not t or t["uid"] != uid or time.time() - t["ts"] > OC_STATE_TTL):
            _OC_TOKENS.pop(tok, None)
            t = None
        elif t["risky"] and not t["warned"]:
            bot.answer_callback_query(call.id, "⚠️ Avval ogohlantirishni tasdiqlang.", show_alert=True)
            return
        else:
            _OC_TOKENS.pop(tok, None)   # bir martalik — ikkinchi bosish ishlamaydi
    if not t:
        bot.answer_callback_query(call.id, "ℹ️ Bu tasdiqlash eskirgan yoki allaqachon bajarilgan.", show_alert=True)
        text, kb = _oc_home_screen()
        smart_render(call, text, kb)
        return
    done, failed, stale = [], [], []
    for key, old, new in t["items"]:
        p = OC_BY_KEY.get(key)
        if not p:
            failed.append(key)
            continue
        if p["get"]() != old:
            stale.append(p)
            continue
        ok, msg = oc_commit(uid, p, new, action=("reset" if t["kind"] == "reset" else "restore" if t["kind"] == "restore" else "change"))
        (done if ok else failed).append((p, old, new, msg))
    bot.answer_callback_query(call.id)
    if len(t["items"]) == 1 and done:
        p, old, new, _m = done[0]
        text = (f"✅ <b>{'Qiymat o‘zgartirildi' if p['typ'] is bool else 'Narx/qiymat o‘zgartirildi'}.</b>\n\n📌 {p['label']}\n\n"
                f"Eski:\n<b>{oc_fmt(p, old)}</b>\n\nYangi:\n<b>{oc_fmt(p, new)}</b>\n\nO'zgarish darhol amalda.")
    elif len(t["items"]) == 1:
        if stale:
            text = "⚠️ Qiymat boshqa joyda o'zgargan — o'zgartirish bekor qilindi. Qaytadan urining."
        else:
            text = f"❌ O'zgartirib bo'lmadi: {failed[0][3] if failed and isinstance(failed[0], tuple) else 'xatolik'}"
    else:
        text = f"✅ Bajarildi: <b>{len(done)}</b> ta · o'tkazib yuborildi: {len(stale)} · xato: {len(failed)}"
    kb = types.InlineKeyboardMarkup(row_width=1)
    kb.add(_oc_btn("⬅️ OWNER CENTER", "oc|home"))
    smart_render(call, text, kb)


def _oc_route(call):
    parts = call.data.split("|")
    uid = call.from_user.id
    act = parts[1] if len(parts) > 1 else "home"
    _need = {"c": 3, "l": 5, "e": 3, "t": 3, "r": 3, "rc": 3, "go": 3, "ok": 3, "h": 3, "grp": 3, "g": 3, "gk": 4, "gv": 5}
    if len(parts) < _need.get(act, 2):
        return bot.answer_callback_query(call.id, "❌ Noto'g'ri so'rov.", show_alert=True)
    if act == "home":
        _OC_INPUT.pop(uid, None)
        text, kb = _oc_home_screen()
        bot.answer_callback_query(call.id)
        return smart_render(call, text, kb)
    if act == "c":
        _OC_INPUT.pop(uid, None)
        cat = parts[2]
        if cat not in OC_CAT_NAME:
            return bot.answer_callback_query(call.id, "❌ Topilmadi.", show_alert=True)
        text, kb = _oc_cat_screen(cat)
        if cat == "sec":
            text += _oc_sec_text()
        bot.answer_callback_query(call.id)
        return smart_render(call, text, kb)
    if act == "l":
        _OC_INPUT.pop(uid, None)
        text, kb = _oc_list_screen(parts[2], int(parts[3]), int(parts[4]))
        bot.answer_callback_query(call.id)
        return smart_render(call, text, kb)
    if act == "e":
        p = OC_BY_KEY.get(parts[2])
        if not p:
            return bot.answer_callback_query(call.id, "❌ Topilmadi.", show_alert=True)
        bot.answer_callback_query(call.id)
        if p["typ"] is not bool:
            _OC_INPUT[uid] = {"mode": "value", "key": p["key"], "chat": call.message.chat.id,
                              "mid": call.message.message_id, "ts": time.time()}
        else:
            _OC_INPUT.pop(uid, None)
        text, kb = _oc_edit_screen(p)
        return smart_render(call, text, kb)
    if act == "t":
        p = OC_BY_KEY.get(parts[2])
        if not p or p["typ"] is not bool:
            return bot.answer_callback_query(call.id, "❌ Topilmadi.", show_alert=True)
        old = int(p["get"]())
        tok = _oc_new_token(uid, "toggle", [(p["key"], old, 1 - old)])
        text, kb = _oc_confirm_screen(tok)
        bot.answer_callback_query(call.id)
        return smart_render(call, text, kb)
    if act == "r":
        p = OC_BY_KEY.get(parts[2])
        if not p:
            return bot.answer_callback_query(call.id, "❌ Topilmadi.", show_alert=True)
        _OC_INPUT.pop(uid, None)
        if p["get"]() == p["default"]:
            return bot.answer_callback_query(call.id, "ℹ️ Allaqachon standart qiymatda.", show_alert=True)
        tok = _oc_new_token(uid, "reset", [(p["key"], p["get"](), p["default"])])
        text, kb = _oc_confirm_screen(tok)
        text = text.replace("DEFAULTGA QAYTARISH</b>", "DEFAULTGA QAYTARISH</b>\n\n⚠️ Barcha default qiymatga qaytarilsinmi?", 1)
        bot.answer_callback_query(call.id)
        return smart_render(call, text, kb)
    if act == "rc":
        cat = parts[2]
        if cat not in OC_CAT_NAME:
            return bot.answer_callback_query(call.id, "❌ Topilmadi.", show_alert=True)
        _OC_INPUT[uid] = {"mode": "resetcat", "cat": cat, "chat": call.message.chat.id, "mid": call.message.message_id, "ts": time.time()}
        kb = types.InlineKeyboardMarkup()
        kb.add(_oc_btn("⬅️ Bekor qilish", f"oc|c|{cat}"))
        bot.answer_callback_query(call.id)
        return smart_render(call, f"{_oc_crumb(cat)}\n\n⚠️ <b>JUDA XAVFLI AMAL</b>\n\n<b>{OC_CAT_NAME[cat]}</b> bo'limidagi BARCHA qiymatlar "
                                  "standartga qaytariladi.\n\nDavom etish uchun <code>RESET</code> deb yozing:", kb)
    if act == "go":
        with _OC_LOCK:
            t = _OC_TOKENS.get(parts[2])
            if not t or t["uid"] != uid:
                return bot.answer_callback_query(call.id, "ℹ️ Eskirgan.", show_alert=True)
            t["warned"] = True
        text, kb = _oc_confirm_screen(parts[2])
        bot.answer_callback_query(call.id)
        return smart_render(call, text, kb)
    if act == "ok":
        return _oc_apply_token(call, parts[2])
    if act == "no":
        _OC_INPUT.pop(uid, None)
        with _OC_LOCK:
            for k in [k for k, v in _OC_TOKENS.items() if v["uid"] == uid]:
                _OC_TOKENS.pop(k, None)
        bot.answer_callback_query(call.id, "❌ Bekor qilindi.")
        text, kb = _oc_home_screen()
        return smart_render(call, text, kb)
    if act == "h":
        text, kb = _oc_hist_screen(int(parts[2]))
        bot.answer_callback_query(call.id)
        return smart_render(call, text, kb)
    if act == "stat":
        text, kb = _oc_stat_screen()
        bot.answer_callback_query(call.id)
        return smart_render(call, text, kb)
    if act == "perm":
        text, kb = _oc_perm_screen()
        bot.answer_callback_query(call.id)
        return smart_render(call, text, kb)
    if act == "msg":
        text, kb = _oc_msg_screen()
        bot.answer_callback_query(call.id)
        return smart_render(call, text, kb)
    if act == "q":
        _OC_INPUT[uid] = {"mode": "search", "chat": call.message.chat.id, "mid": call.message.message_id, "ts": time.time()}
        kb = types.InlineKeyboardMarkup()
        kb.add(_oc_btn("⬅️ Bekor qilish", "oc|home"))
        bot.answer_callback_query(call.id)
        return smart_render(call, f"{_oc_crumb()} › 🔎 Qidirish\n\nSozlama nomini yozing (masalan: <code>hero</code>, <code>narx</code>, <code>coin</code>, <code>timer</code>):", kb)
    if act == "bkmenu":
        text, kb = _oc_bk_menu()
        bot.answer_callback_query(call.id)
        return smart_render(call, text, kb)
    if act == "bk":
        payload = json.dumps(_oc_backup_payload(), ensure_ascii=False, indent=1).encode("utf-8")
        bio = io.BytesIO(payload)
        bio.name = "owner_center_config_" + time.strftime("%Y%m%d_%H%M%S") + ".json"
        bot.answer_callback_query(call.id, "📦 Backup yuborilmoqda…")
        bot.send_document(call.message.chat.id, bio, caption="📦 OWNER CENTER sozlamalari (faqat config — foydalanuvchi ma'lumotlari yo'q).")
        return
    if act == "rs":
        _OC_INPUT[uid] = {"mode": "restore", "chat": call.message.chat.id, "mid": call.message.message_id, "ts": time.time()}
        kb = types.InlineKeyboardMarkup()
        kb.add(_oc_btn("⬅️ Bekor qilish", "oc|home"))
        bot.answer_callback_query(call.id)
        return smart_render(call, "📥 <b>Tiklash</b>\n\nOldin olingan <b>.json</b> backup faylini shu chatga yuboring. "
                                  "Avval o'zgarishlar ro'yxati ko'rsatiladi, tasdiqlagandan keyingina qo'llanadi.", kb)
    if act == "grp":
        text, kb = _oc_groups_screen(int(parts[2]))
        bot.answer_callback_query(call.id)
        return smart_render(call, text, kb)
    if act == "g":
        text, kb = _oc_group_screen(int(parts[2]))
        bot.answer_callback_query(call.id)
        return smart_render(call, text, kb)
    if act == "gk":
        chat_id, idx = int(parts[2]), int(parts[3])
        if not (0 <= idx < len(GS_DEFS)):
            return bot.answer_callback_query(call.id, "❌ Topilmadi.", show_alert=True)
        text, kb = _oc_group_key_screen(chat_id, idx)
        bot.answer_callback_query(call.id)
        return smart_render(call, text, kb)
    if act == "gv":
        chat_id, idx, val = int(parts[2]), int(parts[3]), parts[4]
        if not (0 <= idx < len(GS_DEFS)) or not _oc_group_known(chat_id):
            return bot.answer_callback_query(call.id, "❌ Topilmadi.", show_alert=True)
        d = GS_DEFS[idx]
        old = gs_get(chat_id, d["key"])
        if val in [c[0] for c in d["choices"]] and old != val:
            if gs_set(chat_id, d["key"], val):
                oc_log_external(uid, f"gs:{chat_id}:{d['key']}", f"{d['title']} (guruh {chat_id})", old, val, "change", scope=f"group:{chat_id}")
        bot.answer_callback_query(call.id, "✅ Saqlandi.")
        text, kb = _oc_group_screen(chat_id)
        return smart_render(call, text, kb)
    bot.answer_callback_query(call.id, "❌ Noma'lum amal.", show_alert=True)


def _oc_group_known(chat_id):
    with db_lock:
        cur.execute("SELECT 1 FROM known_groups WHERE chat_id=?", (chat_id,))
        return cur.fetchone() is not None


@bot.callback_query_handler(func=lambda c: (c.data or "").startswith("oc|"))
def cb_owner_center(call):
    if not _oc_guard(call):
        return
    try:
        _oc_route(call)
    except Exception:
        _logger.exception("OWNER CENTER callback xatosi: %s", call.data)
        try:
            bot.answer_callback_query(call.id, "❌ Xatolik yuz berdi.", show_alert=True)
        except Exception:
            pass


# ----------------------------------------------------------------- ⌨️ MATN KIRITISH
def oc_handle_input(message):
    """private_message_router'dan chaqiriladi (faqat _OC_INPUT'da turgan owner uchun)."""
    uid = message.from_user.id
    if not is_owner(uid):
        _OC_INPUT.pop(uid, None)
        return
    st = _OC_INPUT.get(uid)
    if not st or time.time() - st["ts"] > OC_STATE_TTL:
        _OC_INPUT.pop(uid, None)
        bot.send_message(message.chat.id, "ℹ️ Kiritish muddati tugadi. /owner_center orqali qayta oching.")
        return
    raw = (message.text or "").strip()
    target = (st["chat"], st["mid"])
    try:
        safe_delete(message)
    except Exception:
        pass
    mode = st["mode"]
    if mode == "value":
        p = OC_BY_KEY.get(st["key"])
        if not p:
            _OC_INPUT.pop(uid, None)
            return
        val, err = oc_parse(p, raw)
        if err:
            text, kb = _oc_edit_screen(p, err=err)
            return _oc_show(target, text, kb)
        old = p["get"]()
        if val == old:
            text, kb = _oc_edit_screen(p, err="Bu qiymat hozirgi qiymat bilan bir xil.")
            return _oc_show(target, text, kb)
        _OC_INPUT.pop(uid, None)
        tok = _oc_new_token(uid, "set", [(p["key"], old, val)], risky=oc_is_risky(p, old, val))
        text, kb = _oc_confirm_screen(tok)
        return _oc_show(target, text, kb)
    if mode == "search":
        _OC_INPUT.pop(uid, None)
        res = _oc_search_results(raw)
        kb = types.InlineKeyboardMarkup(row_width=1)
        if res:
            text = f"{_oc_crumb()} › 🔎 \"{esc(raw)[:40]}\"\n\nTopildi: <b>{len(res)}</b>"
            for p in res:
                kb.add(_oc_btn(f"🌍 {p['label'][:30]}: {oc_fmt(p, p['get']())}", f"oc|e|{p['key']}"))
        else:
            text = f"{_oc_crumb()} › 🔎\n\n❌ \"{esc(raw)[:40]}\" bo'yicha hech narsa topilmadi (kamida 2 ta harf yozing)."
        kb.add(_oc_btn("🔎 Qayta qidirish", "oc|q"), _oc_btn("⬅️ Orqaga", "oc|home"))
        return _oc_show(target, text, kb)
    if mode == "resetcat":
        _OC_INPUT.pop(uid, None)
        cat = st["cat"]
        if raw != "RESET":
            kb = types.InlineKeyboardMarkup()
            kb.add(_oc_btn("⬅️ Orqaga", f"oc|c|{cat}"))
            return _oc_show(target, "❌ Bekor qilindi: <code>RESET</code> yozilmadi.", kb)
        items = [(p["key"], p["get"](), p["default"]) for p in OC_PARAMS if p["cat"] == cat and p["get"]() != p["default"]]
        if not items:
            kb = types.InlineKeyboardMarkup()
            kb.add(_oc_btn("⬅️ Orqaga", f"oc|c|{cat}"))
            return _oc_show(target, "ℹ️ Bu bo'limda barcha qiymatlar allaqachon standart.", kb)
        tok = _oc_new_token(uid, "reset", items)
        text, kb = _oc_confirm_screen(tok)
        text = text.replace("<b>BO'LIMNI DEFAULTGA QAYTARISH</b>", "<b>BO'LIMNI DEFAULTGA QAYTARISH</b>\n⚠️ Barcha default qiymatga qaytarilsinmi?", 1)
        return _oc_show(target, text, kb)
    _OC_INPUT.pop(uid, None)


