# ================================================================================
# 🛡 O'YIN BOSQICHLARI UCHUN "BEST-EFFORT" XABAR YUBORISH
# Tun/kun/ovoz/osish bosqichlari guruhga xabar yuboradi. Agar Telegram qayta urinishlardan
# keyin ham xabarni qabul qilmasa, oldin istisno butun bosqichni o'rtada to'xtatib, o'yinni
# muzlatib qo'yardi. Endi shu funksiyalar ichida yuborilmagan xabar faqat logga yoziladi,
# o'yin esa keyingi bosqichga o'tishda davom etadi.
# ================================================================================
_PHASE_TL = threading.local()
_phase_inner_send = bot.send_message

# 📮 Telegram 429 ("juda tez-tez yuboryapsiz") bo'lganda o'yin bosqichi o'yin qulfini ushlab uxlab
# QOLMASLIGI uchun xabar shu chat uchun tartibli NAVBATga olinadi va alohida oqim Telegram aytgan
# muddatdan keyin yuboradi (tartib saqlanadi, hech narsa yo'qolmaydi, o'yin to'xtamaydi).
_OUTBOX = {}
_OUTBOX_LOCK = threading.Lock()
_OUTBOX_MAX_PER_CHAT = 200


def _outbox_worker(chat_id, delay):
    time.sleep(max(0.0, delay))
    while True:
        with _OUTBOX_LOCK:
            q = _OUTBOX.get(chat_id)
            if not q:
                _OUTBOX.pop(chat_id, None)
                return
            a, k = q[0]
        wait = 0.0
        try:
            _phase_inner_send(*a, **k)
        except telebot.apihelper.ApiTelegramException as e:
            if getattr(e, "error_code", None) == 429:
                wait = min(_tg_retry_after_seconds(e) + 1, 120)
                time.sleep(wait)
                continue   # xuddi shu xabarni qayta urinamiz
            _logger.warning("Navbatdagi xabar yuborilmadi (chat=%s): %s", chat_id, e)
        except Exception as e:
            _logger.warning("Navbatdagi xabar yuborilmadi (chat=%s): %s", chat_id, e)
        with _OUTBOX_LOCK:
            q = _OUTBOX.get(chat_id)
            if q:
                q.popleft()


def _outbox_put(chat_id, a, k, delay):
    import collections as _c
    with _OUTBOX_LOCK:
        q = _OUTBOX.get(chat_id)
        if q is not None:
            if len(q) < _OUTBOX_MAX_PER_CHAT:
                q.append((a, k))
            return
        _OUTBOX[chat_id] = _c.deque([(a, k)])
    threading.Thread(target=_outbox_worker, args=(chat_id, delay), daemon=True, name=f"outbox-{chat_id}").start()


class _DeferredMessage:
    """Navbatga olingan (hali yuborilmagan) xabar uchun "bo'sh" natija: chaqiruvchi kod
    `sent.message_id` kabi atributlarga murojaat qilsa ham yiqilmaydi (qiymat None)."""
    deferred = True

    def __init__(self, chat_id, text=None):
        self.chat = types.Chat(id=chat_id, type="supergroup" if isinstance(chat_id, int) and chat_id < 0 else "private") if hasattr(types, "Chat") else None
        self.text = text

    def __getattr__(self, name):
        if name.startswith("__"):
            raise AttributeError(name)
        return None


def _phase_aware_send(*a, **k):
    chat_id = a[0] if a else k.get("chat_id")
    _txt = a[1] if len(a) > 1 else k.get("text")
    if chat_id in _OUTBOX:   # shu chatda navbat bor — tartib buzilmasligi uchun orqasiga qo'shamiz
        _outbox_put(chat_id, a, k, 0)
        return _DeferredMessage(chat_id, _txt)
    in_phase = getattr(_PHASE_TL, "depth", 0) > 0
    try:
        return _phase_inner_send(*a, **k)
    except telebot.apihelper.ApiTelegramException as exc:
        if getattr(exc, "error_code", None) == 429:
            delay = _tg_retry_after_seconds(exc) + 1
            _logger.warning("📮 429: xabar navbatga olindi (chat=%s, %s soniyadan keyin yuboriladi)", chat_id, delay)
            _outbox_put(chat_id, a, k, delay)
            return _DeferredMessage(chat_id, _txt)
        if in_phase:
            _logger.warning("⚠️ Bosqich xabari yuborilmadi (o'yin davom etadi): %s", exc)
            return None
        raise
    except Exception as exc:
        if in_phase:
            _logger.warning("⚠️ Bosqich xabari yuborilmadi (o'yin davom etadi): %s", exc)
            return None
        raise


bot.send_message = _phase_aware_send


def _phase_best_effort(fn):
    @functools.wraps(fn)
    def w(*a, **k):
        _PHASE_TL.depth = getattr(_PHASE_TL, "depth", 0) + 1
        try:
            return fn(*a, **k)
        finally:
            _PHASE_TL.depth -= 1
    return w


for _pf in ("resolve_night", "resolve_day", "open_day_voting", "resolve_hang_confirmation", "finish_day_phase"):
    if _pf in globals():
        globals()[_pf] = _phase_best_effort(globals()[_pf])


