def _chpost_now_local():
    return time.gmtime(time.time() + _CHPOST_TZ_OFFSET)


def _chpost_markup():
    global BOT_USERNAME
    try:
        if BOT_USERNAME is None:
            BOT_USERNAME = bot.get_me().username
        kb = types.InlineKeyboardMarkup()
        kb.add(types.InlineKeyboardButton("🎮 Botga o'tish", url=f"https://t.me/{BOT_USERNAME}"))
        return kb
    except Exception:
        return None


def _chpost_build(day_no, slot):
    """('text', html) yoki ('poll', dict) qaytaradi. Kun raqami va slotga qarab aylanadi."""
    kinds_morning = ["tip", "role", "tip", "feature"]
    kinds_evening = ["top", "quiz", "challenge", "feature", "quiz", "top", "role"]
    kinds = kinds_morning if slot == 1 else kinds_evening
    kind = kinds[day_no % len(kinds)]
    if kind == "tip":
        title, body = CHANNEL_TIPS[(day_no * 2 + slot) % len(CHANNEL_TIPS)]
        return "text", f"💡 <b>KUN MASLAHATI</b>\n\n<b>{title}</b>\n{body}\n\n#maslahat #strategiya"
    if kind == "feature":
        title, body = CHANNEL_FEATURES[(day_no + slot) % len(CHANNEL_FEATURES)]
        return "text", f"✨ <b>BOT IMKONIYATI</b>\n\n<b>{title}</b>\n{body}\n\n#imkoniyat"
    if kind == "challenge":
        ch = CHANNEL_CHALLENGES[day_no % len(CHANNEL_CHALLENGES)]
        return "text", f"🎯 <b>KUNLIK VAZIFA</b>\n\n{ch}\n\n💬 Bajarganlar — izohlarda yozing!\n\n#vazifa"
    if kind == "role":
        roles = list(ROLES_INFO.items())
        name, desc = roles[(day_no * 3 + slot) % len(roles)]
        return "text", f"🎭 <b>KUN ROLI</b>\n\n<b>{name}</b>\n{desc}\n\n💭 Siz bu rolda qanday o'ynagan bo'lardingiz?\n\n#rollar"
    if kind == "top":
        try:
            txt = build_points_top_text("kun")
        except Exception:
            txt = ""
        try:
            gtxt = build_top_groups_text(limit=5)
        except Exception:
            gtxt = ""
        if "hozircha bo'sh" in txt or not txt:
            return _chpost_build(day_no + 1, 1)   # bo'sh reyting o'rniga maslahat
        return "text", f"🏆 <b>KUN YAKUNI</b>\n\n{txt}\n\n{gtxt}\n\n🔥 Ertaga siz ham ro'yxatda bo'lishingiz mumkin!\n#reyting"
    # quiz — ROLES_INFO dan avtomatik viktorina
    roles = list(ROLES_INFO.items())
    rnd = random.Random(day_no * 10 + slot)
    correct_name, desc = roles[rnd.randrange(len(roles))]
    others = [n for n, _ in roles if n != correct_name]
    opts = rnd.sample(others, 3) + [correct_name]
    rnd.shuffle(opts)
    q = f"Qaysi rol haqida? {desc}"
    if len(q) > 290:
        q = q[:287] + "..."
    return "poll", {"question": q, "options": [o[:100] for o in opts], "correct": opts.index(correct_name),
                    "explanation": f"To'g'ri javob: {correct_name}"[:200]}


def post_to_owner_channel(slot=None, force=False):
    """Kanalga bitta post yuboradi. (ok, xabar) qaytaradi."""
    ch = OWNER_CHANNEL_ID
    if not ch:
        return False, "Kanal o'rnatilmagan (/shu_kanal)."
    lt = _chpost_now_local()
    if slot is None:
        slot = 1 if lt.tm_hour < 15 else 2
    day_no = int(time.time() + _CHPOST_TZ_OFFSET) // 86400
    key = f"chpost_{lt.tm_year}{lt.tm_yday}_{slot}"
    if not force and get_setting(key):
        return False, "Bu slot allaqachon joylangan."
    kind, payload = _chpost_build(day_no, slot)
    try:
        if kind == "poll":
            bot.send_poll(ch, payload["question"], payload["options"], is_anonymous=True, type="quiz",
                          correct_option_id=payload["correct"], explanation=payload["explanation"])
            bot.send_message(ch, "🧠 <b>Viktorina!</b> Javobingizni tanlang 👆", reply_markup=_chpost_markup())
        else:
            bot.send_message(ch, payload, reply_markup=_chpost_markup(), disable_web_page_preview=True)
    except Exception as e:
        _logger.warning("📣 Kanal posti yuborilmadi: %s", e)
        return False, f"Yuborilmadi: {e}"
    set_setting(key, "1")
    return True, "Joylandi."


def _channel_posts_enabled():
    """📣 Kanal avto-postlari STANDARTDA O'CHIQ. Faqat egasi /kanal_post_toggle bilan yoqsa ishlaydi
    (sozlama 'channel_posts_off' = '0'). Qo'lda /kanal_post har doim ishlaydi."""
    return get_setting("channel_posts_off") == "0"


def _channel_post_loop():
    while True:
        try:
            time.sleep(60)
            if not _channel_posts_enabled() or not OWNER_CHANNEL_ID:
                continue
            lt = _chpost_now_local()
            for slot, hr in enumerate(CHANNEL_POST_HOURS, start=1):
                if lt.tm_hour == hr:   # shu soat ichida bir marta (dedupe — setting kaliti)
                    post_to_owner_channel(slot)
        except Exception:
            _logger.warning("📣 kanal post sikli xatosi", exc_info=True)


def start_channel_post_loop():
    threading.Thread(target=_channel_post_loop, daemon=True).start()


@bot.message_handler(commands=["kanal_post"])
def cmd_kanal_post(message):
    maybe_capture_owner(message.from_user)
    if not is_owner(message.from_user.id):
        return
    safe_delete(message)
    parts = (message.text or "").split()
    slot = int(parts[1]) if len(parts) > 1 and parts[1] in ("1", "2") else None
    ok, msg = post_to_owner_channel(slot, force=True)
    bot.send_message(message.chat.id, ("✅ " if ok else "⚠️ ") + msg)


@bot.message_handler(commands=["kanal_post_toggle"])
def cmd_kanal_post_toggle(message):
    maybe_capture_owner(message.from_user)
    if not is_owner(message.from_user.id):
        return
    safe_delete(message)
    off = not _channel_posts_enabled()
    set_setting("channel_posts_off", "0" if off else "1")
    bot.send_message(message.chat.id, "📣 Kanal avto-postlari " + ("YOQILDI ✅" if off else "O'CHIRILDI ⏸"))



