try:
    _L10N_RAW = _js.loads(_zl.decompress(_b64.b64decode(_L10N_BLOB)).decode("utf-8"))
except Exception as _e:
    _logger.error("L10N yuklanmadi: %s", _e)
    _L10N_RAW = {}
# Uzun parchalar birinchi almashtiriladi (qisqa parcha uzun jumla ichini buzmasin)
_L10N = {lg: sorted(d.items(), key=lambda kv: -len(kv[0])) for lg, d in _L10N_RAW.items()}
_L10N_CACHE = {}
_EMO_RE = __import__("re").compile(r"[\u2190-\u2bff\u3030-\u303d\U0001F000-\U0001FFFF\u200d\ufe0f\u20e3]+")


def _bare(t):
    return _EMO_RE.sub("", t).strip()


# Rol nomlari emojisiz ham uchraydi ("Siz — Tinch axoli!"): "Nom 🕵️" juftlaridan emojisiz juft yasaymiz
_ROLE_KEY_RE = __import__("re").compile(r"^(?:[^\W\d_]|['\u02bb\u02bc\u2018\u2019]){1,24}(?: (?:[^\W\d_]|['\u02bb\u02bc\u2018\u2019])+){0,2} [^\w\s]+$")
for _lg, _prs in list(_L10N.items()):
    _extra = {}
    for _k, _v in _prs:
        if _ROLE_KEY_RE.match(_k):
            _bk, _bv = _bare(_k), _bare(_v)
            if _bk and _bv and _bk != _bv:
                _extra[_bk] = _bv
    if _extra:
        _L10N[_lg] = sorted(list(_prs) + list(_extra.items()), key=lambda kv: -len(kv[0]))


def _l10n_lang_of(chat_id):
    now = _tm.time()
    hit = _L10N_CACHE.get(chat_id)
    if hit and now - hit[1] < 20:
        return hit[0]
    try:
        cid = int(chat_id)
        lg = _group_lang(cid) if cid < 0 else get_lang(cid)
    except Exception:
        lg = "uz"
    _L10N_CACHE[chat_id] = (lg, now)
    return lg


def l10n(chat_id, text):
    """Matnni chat tiliga o'giradi (uz yoki noma'lum bo'lsa o'zgarishsiz)."""
    if not isinstance(text, str) or not text:
        return text
    lang = _l10n_lang_of(chat_id)
    pairs = _L10N.get(lang)
    if pairs:
        for src, dst in pairs:
            if src in text:
                text = text.replace(src, dst)
    return rn_apply(chat_id, lang, text)   # 🎭 guruh admini tayinlagan rol nomlari (faqat guruhlarda)


def _l10n_markup(chat_id, markup):
    try:
        if markup is not None and hasattr(markup, "keyboard"):
            for row in markup.keyboard:
                for b in row:
                    if isinstance(b, dict):
                        if b.get("text"):
                            b["text"] = l10n(chat_id, b["text"])
                    elif getattr(b, "text", None):
                        b.text = l10n(chat_id, b.text)
    except Exception:
        pass
    return markup


_l10n_prev_send = bot.send_message
_l10n_prev_edit = bot.edit_message_text
_l10n_prev_photo = bot.send_photo
_l10n_prev_cap = getattr(bot, "edit_message_caption", None)
_l10n_prev_cb = bot.answer_callback_query


def _l10n_send(chat_id, text, *a, **kw):
    text = l10n(chat_id, text)
    if "reply_markup" in kw:
        kw["reply_markup"] = _l10n_markup(chat_id, kw["reply_markup"])
    with _pm_scope(chat_id):
        return _l10n_prev_send(chat_id, text, *a, **kw)


def _l10n_edit(text, *a, **kw):
    cid = kw.get("chat_id") if kw.get("chat_id") is not None else (a[0] if a else None)
    if cid is not None:
        text = l10n(cid, text)
        if "reply_markup" in kw:
            kw["reply_markup"] = _l10n_markup(cid, kw["reply_markup"])
    with _pm_scope(cid):
        return _l10n_prev_edit(text, *a, **kw)


def _l10n_photo(chat_id, photo, *a, **kw):
    if kw.get("caption"):
        kw["caption"] = l10n(chat_id, kw["caption"])
        try:   # 🖼 rasm izohi ham shrift/premium-emoji qoidalariga bo'ysunadi (1024 belgidan oshsa — o'zgarishsiz)
            if kw.get("parse_mode") in (None, "HTML"):
                with _pm_scope(chat_id):
                    _cap = wrap_known_emojis(kw["caption"])
                if _u16(_cap) <= 1024:
                    kw["caption"] = _cap
        except Exception:
            pass
    if "reply_markup" in kw:
        kw["reply_markup"] = _l10n_markup(chat_id, kw["reply_markup"])
    with _pm_scope(chat_id):
        return _l10n_prev_photo(chat_id, photo, *a, **kw)


def _l10n_cb(call_id, text=None, *a, **kw):
    # callback javobi: bosgan foydalanuvchi tilida
    return _l10n_prev_cb(call_id, text, *a, **kw)


bot.send_message = _l10n_send
bot.edit_message_text = _l10n_edit
bot.send_photo = _l10n_photo


def _pm_wrap_api(fn):
    """chat_id birinchi argument bo'lgan API chaqiruvlarini premium-emoji sozlamasi doirasiga oladi."""
    def w(*a, **kw):
        cid = kw.get("chat_id", a[0] if a else None)
        with _pm_scope(cid):
            return fn(*a, **kw)
    return w


for _n in ("edit_message_reply_markup",):
    if getattr(bot, _n, None) is not None:
        setattr(bot, _n, _pm_wrap_api(getattr(bot, _n)))

# til almashganda keshni tozalash
_l10n_prev_set_lang = set_lang
def set_lang(uid, code):
    _l10n_prev_set_lang(uid, code)
    _L10N_CACHE.pop(uid, None)
    _L10N_CACHE.pop(str(uid), None)

_l10n_prev_set_setting = set_setting
def set_setting(key, value, *a, **kw):
    r = _l10n_prev_set_setting(key, value, *a, **kw)
    if str(key).startswith("grp_lang_"):
        _L10N_CACHE.clear()
    return r


# ================================================================================
#  🕑 AVTOMATIK NAZORAT: eskirgan lobbilar va adminsiz guruhlar
# ================================================================================
#  1) Lobbi LOBBY_MAX_AGE_SEC (2 kun) ochiq turib, o'yin boshlanmasa:
#       • o'yinchilar yetarli bo'lsa — o'yin AVTOMATIK boshlanadi;
#       • yetmasa — lobbi yopiladi ("qayta /newgame bilan oching").
#  2) Bot guruhda ADMIN bo'lmasa: /newgame ishlamaydi va BOT_ADMIN_GRACE_SEC (2 kun) ichida
#     admin qilinmasa — bot guruhga xabar berib, undan o'zi chiqib ketadi.
#     Admin bo'lgach hisoblagich o'chadi. Telegram xatosi bo'lsa (noaniq) — guruh tegilmaydi.
# ================================================================================
LOBBY_MAX_AGE_SEC = 2 * 86400
BOT_ADMIN_GRACE_SEC = 2 * 86400
_WD_EVERY_SEC = 3600


def bot_admin_state(chat_id, use_cache=True):
    """True — bot admin; False — admin emas (aniq); None — aniqlab bo'lmadi; 'gone' — guruhda yo'q."""
    now = time.time()
    hit = _BOT_ADMIN_CACHE.get(chat_id)
    if use_cache and hit and now - hit[1] < 60:
        return hit[0]
    try:
        me = bot.get_me().id
        st = bot.get_chat_member(chat_id, me).status
        val = True if st in ("administrator", "creator") else (False if st == "member" else "gone")
    except Exception as e:
        t = str(e).lower()
        val = "gone" if any(m in t for m in ("chat not found", "bot was kicked", "bot is not a member", "group chat was deleted")) else None
    _BOT_ADMIN_CACHE[chat_id] = (val, now)
    return val


_BOT_ADMIN_CACHE = {}


def _noadmin_since(chat_id):
    try:
        return float(get_setting(f"noadmin_since_{chat_id}") or 0)
    except Exception:
        return 0.0


def mark_bot_admin_status(chat_id, is_admin):
    """Hisoblagichni boshlaydi (admin emas) yoki tozalaydi (admin)."""
    if is_admin:
        if _noadmin_since(chat_id):
            set_setting(f"noadmin_since_{chat_id}", "0")
    elif not _noadmin_since(chat_id):
        set_setting(f"noadmin_since_{chat_id}", str(time.time()))


def _lobby_close_stale(chat_id, game, reason):
    try:
        with _glock(chat_id):
            cur_game = GAMES.get(chat_id)
            if cur_game is not game or game.get("phase") != "waiting":
                return
            if game.get("join_msg_id"):
                _close_join_message(chat_id, game["join_msg_id"])
            GAMES.pop(chat_id, None)
        save_games_state()
        bot.send_message(chat_id, reason)
    except Exception:
        _logger.warning("eski lobbini yopishda xato (chat=%s)", chat_id, exc_info=True)


def _lobby_auto_start(chat_id, game):
    owner = OWNER_ID_FROM_ENV or OWNER_ID
    if not owner:
        return False
    try:
        bot.send_message(chat_id, "⏰ Ro'yxat 2 kundan beri ochiq turibdi — yetarli o'yinchi bor, o'yin <b>avtomatik boshlanmoqda</b>!")
    except Exception:
        pass
    fake = __import__("types").SimpleNamespace(
        chat=__import__("types").SimpleNamespace(id=chat_id, type="supergroup", title=game.get("chat_title") or ""),
        from_user=__import__("types").SimpleNamespace(id=owner, first_name="Hunter", last_name=None, username=None, is_bot=False),
        text="/startgame", message_id=0, content_type="text")
    cmd_startgame(fake)
    g2 = GAMES.get(chat_id)
    return bool(g2 and g2 is game and g2.get("phase") != "waiting")


def lobby_watchdog_once():
    now = time.time()
    for chat_id, game in list(GAMES.items()):
        try:
            if game.get("phase") != "waiting":
                continue
            ts = game.get("lobby_ts")
            if not ts:
                game["lobby_ts"] = now   # eski (qayta tiklangan) lobbi — hisob hozirdan boshlanadi
                continue
            if now - ts < LOBBY_MAX_AGE_SEC:
                continue
            enough = len(game["players"]) >= game_min_players(game)
            if enough and (OWNER_ID_FROM_ENV or OWNER_ID):
                if _lobby_auto_start(chat_id, game):
                    continue
                _lobby_close_stale(chat_id, game, "⌛ O'yinni avtomatik boshlab bo'lmadi (jamoalar muvozanatsiz yoki boshqa sabab). "
                                   "Ro'yxat yopildi — /newgame bilan qaytadan oching.")
            else:
                _lobby_close_stale(chat_id, game, "⌛ Ro'yxat 2 kun davomida yetarli o'yinchi to'plamadi va yopildi. "
                                   "Qaytadan o'ynash uchun /newgame yozing.")
        except Exception:
            _logger.warning("lobby watchdog xatosi (chat=%s)", chat_id, exc_info=True)


def admin_watchdog_once():
    now = time.time()
    for chat_id, _title in list(list_known_groups()):
        try:
            if chat_id >= 0:
                continue
            st = bot_admin_state(chat_id, use_cache=False)
            if st == "gone":
                remove_known_group(chat_id)
            elif st is True:
                mark_bot_admin_status(chat_id, True)
            elif st is False:
                since = _noadmin_since(chat_id)
                if not since:
                    mark_bot_admin_status(chat_id, False)
                    since = now
                    try:
                        bot.send_message(chat_id, "⚠️ Men bu guruhda <b>admin emasman</b>. O'yin to'g'ri ishlashi uchun meni admin qiling "
                                         "(xabarlarni o'chirish, xabar qadash huquqlari bilan). "
                                         "<b>2 kun ichida</b> admin qilinmasa, guruhdan chiqib ketaman.")
                    except Exception:
                        pass
                elif now - since >= BOT_ADMIN_GRACE_SEC:
                    g = GAMES.get(chat_id)
                    if g and g.get("phase") != "waiting":
                        continue   # o'yin ketayotgan bo'lsa — tugashini kutamiz
                    try:
                        bot.send_message(chat_id, "👋 Meni 2 kun ichida admin qilmadingiz, shuning uchun guruhdan chiqib ketyapman. "
                                         "Xohlasangiz, qayta qo'shib, admin qiling — o'yinlar yana ishlaydi.")
                    except Exception:
                        pass
                    try:
                        bot.leave_chat(chat_id)
                    except Exception:
                        _logger.warning("leave_chat xatosi (chat=%s)", chat_id, exc_info=True)
                    remove_known_group(chat_id)
                    GAMES.pop(chat_id, None)
                    set_setting(f"noadmin_since_{chat_id}", "0")
                    if OWNER_ID:
                        try:
                            bot.send_message(OWNER_ID, f"🚪 Admin berilmagani uchun guruhdan chiqildi: <code>{chat_id}</code> ({esc(_title or '')})")
                        except Exception:
                            pass
                else:
                    last = 0.0
                    try:
                        last = float(get_setting(f"noadmin_warn_{chat_id}") or 0)
                    except Exception:
                        pass
                    if now - last >= 86400 and now - since >= 3600:
                        set_setting(f"noadmin_warn_{chat_id}", str(now))
                        left_h = max(1, int((BOT_ADMIN_GRACE_SEC - (now - since)) // 3600))
                        try:
                            bot.send_message(chat_id, f"⚠️ Meni hali admin qilmadingiz. Yana taxminan <b>{left_h} soat</b> ichida admin qilinmasa, guruhdan chiqib ketaman.")
                        except Exception:
                            pass
            time.sleep(0.2)
        except Exception:
            _logger.warning("admin watchdog xatosi (chat=%s)", chat_id, exc_info=True)


def _auto_watchdog_loop():
    time.sleep(120)   # bot to'liq ishga tushib olsin
    while True:
        try:
            lobby_watchdog_once()
            admin_watchdog_once()
        except Exception:
            _logger.warning("auto watchdog xatosi", exc_info=True)
        time.sleep(_WD_EVERY_SEC)


def start_auto_watchdog():
    t = threading.Thread(target=_auto_watchdog_loop, name="auto-watchdog", daemon=True)
    t.start()


if __name__ == "__main__":
    print("Hunter Mafia bot v5 (telebot, do'kon + Stars + promo + tarqatish + qora bozor + klan jangi) ishga tushmoqda...")
    start_keepalive_server()  # 🌐 Render "xizmat tirik" deb bilishi uchun — ENG BIRINCHI ishga tushiriladi
    start_self_ping_loop()    # 🌐 har 10 daqiqada o'ziga so'rov — Render uxlab qolmasin deb
    with db_lock:
        cur.execute("SELECT COUNT(*) FROM users")
        _existing_users = cur.fetchone()[0]
    _logger.info(f"📂 Baza fayli: {DB_PATH}")
    _logger.info(f"👥 Bazadagi mavjud foydalanuvchilar soni: {_existing_users} ta")
    if _existing_users == 0 and _users_table_existed is False:
        _logger.warning("⚠️ Bu — 'users' jadvali birinchi marta yaratilyapti (yangi/bo'sh baza). Agar avval "
                         "foydalanuvchilar bo'lgan bo'lsa, bot boshqa papkadan yoki boshqa hunter_mafia.db "
                         "fayli bilan ishga tushirilayotgan bo'lishi mumkin — DB_PATH qatorini tekshiring.")
    # 🔒 BITTA NUSXA QULFI (single-instance lock): agar shu skript allaqachon shu
    # papkada ishga tushirilgan bo'lsa (masalan avvalgi jarayon to'liq o'chmagan,
    # yoki kimdir uni ikkinchi marta ishga tushirib yuborgan bo'lsa), bu yerda
    # DARHOL to'xtaydi va aniq xabar beradi — Telegram tomonidan qaytariladigan
    # tushunarsiz "409 Conflict" xatoligi o'rniga.
    _LOCK_PATH = "/tmp/hunter_mafia_bot.lock"
    try:
        import fcntl
        _lock_fh = open(_LOCK_PATH, "w")
        fcntl.flock(_lock_fh, fcntl.LOCK_EX | fcntl.LOCK_NB)
        _lock_fh.write(str(os.getpid()))
        _lock_fh.flush()
    except BlockingIOError:
        print(
            "❌ Bot allaqachon ishga tushirilgan (boshqa jarayon shu bot tokeni bilan "
            "polling qilyapti)! Avval eski jarayonni to'xtating (masalan: "
            "`pkill -f hunter_mafia` yoki serverdagi eski deploy/screen/pm2 sessiyasini "
            "yopib qo'ying), keyin qayta ishga tushiring. Bot ishga tushmaydi."
        )
        sys.exit(1)
    except Exception as _lock_err:
        # fcntl mavjud bo'lmagan tizimlarda (masalan Windows) qulf o'tkazib yuboriladi —
        # bu holatda faqat webhook/eski-session tekshiruvi ishlaydi.
        _logger.warning("Instance-lock o'rnatilmadi (muhim emas): %s", _lock_err)

    # 🧹 Eski WEBHOOK (agar avval webhook rejimida ishlatilgan bo'lsa) yoki Telegram
    # tomonida "osilib qolgan" eski ulanishni tozalab, keyin polling'ni boshlaymiz —
    # bu ham 409 Conflict xatoligining keng tarqalgan sababi.
    try:
        bot.remove_webhook()
        time.sleep(1)
    except Exception as _wh_err:
        _logger.warning("Webhook tozalashda xatolik (muhim emas): %s", _wh_err)

    _state_restored = False
    _consecutive_conflicts = 0
    while True:
        try:
            BOT_USERNAME = bot.get_me().username
            _logger.info("Bot ishga tushdi: @%s | versiya %s", BOT_USERNAME, BOT_VERSION)
            if not _state_restored:
                # 🔄 oldingi ishga tushishda (xatolik/deploy/`/tiklash`) saqlangan aktiv
                # o'yinlar bo'lsa, shu yerda tiklanadi — faqat 1 marta, tarmoq uzilib
                # qayta ulanganda emas (chunki fayl birinchi muvaffaqiyatli tiklashda o'chiriladi).
                load_games_state()
                _state_restored = True
                _check_clan_inactivity()  # 🏛 klan faolsizlik tekshiruvini fon rejimida ishga tushiramiz
                set_bot_commands_for_all_scopes()  # 📜 3 xil buyruqlar menyusini (guruh/shaxsiy/owner) o'rnatish
                start_auto_backup_loop()  # 💾 #6: har 24 soatda avtomatik zaxira nusxa
                start_freeze_watchdog()  # 🩺 bot muzlab qolsa — o'zini avtomatik qayta ishga tushiradi
                start_cache_janitor()  # 🧹 o'sib boradigan keshlarni vaqti-vaqti bilan tozalaydi
                start_game_stall_watchdog()  # 🩺 bosqich taymeri o'lib qolsa — o'yinni majburan davom ettiradi
                # 🕖 kunlik 07:00 bosh menyu xabari O'CHIRILGAN (foydalanuvchi talabi)
                start_weekly_report_loop()  # 📅 v10: har dushanba 09:00'da shaxsiy haftalik hisobot
                start_hc_market_loop()  # 🪙📈 Hunter Coin jonli kursini har HC_MARKET_UPDATE_MINUTES'da tebratib turadi
                start_v10_loop()  # 🎲 Hunter World: tasodifiy voqealar sikli (hudud/afsona/taqdir/karta/ARG)
                start_v11_loop()  # 🎲 Hunter World chuqurlashtirish: mustahkamlanish, oy afsonasi, muddati o'tgan voqealar
                start_channel_post_loop()  # 📣 kanalga kuniga 2 marta foydali avto-post
                start_auto_watchdog()  # 🕑 2 kun to'lmagan lobbini avto-boshlash/yopish + adminsiz guruhdan chiqish
                # 🎴 Mini App endi pastki chap "menyu" tugmasida EMAS — faqat /profil
                # (kabinet) xabari ostidagi alohida tugma orqali ochiladi (foydalanuvchi so'rovi).
                try:
                    bot.set_chat_menu_button(menu_button=types.MenuButtonDefault())
                except Exception:
                    pass
            bot.infinity_polling(skip_pending=True, timeout=30, long_polling_timeout=30)
            _consecutive_conflicts = 0
        except telebot.apihelper.ApiTelegramException as e:
            if getattr(e, "error_code", None) == 409 or "409" in str(e) or "Conflict" in str(e):
                # 🚨 409 = boshqa bir nusxa HALI HAM shu tokendan foydalanib polling
                # qilyapti. Tez-tez qayta urinish faqat vaziyatni yomonlashtiradi —
                # shuning uchun har safar sal uzoqroq kutamiz (progressiv orqaga
                # chekinish), bosh ko'rsatiladigan xatolik xabarlari sonini kamaytiradi.
                _consecutive_conflicts += 1
                wait_s = min(60, 10 * _consecutive_conflicts)
                _logger.warning(
                    "⚠️ 409 Conflict: shu bot tokeni bilan BOSHQA bir nusxa polling "
                    "qilyapti (ehtimol eski jarayon o'chirilmagan). %s soniya kutib, "
                    "qayta urinilmoqda...", wait_s,
                )
                time.sleep(wait_s)
            else:
                _logger.exception("Telegram API xatoligi, 5 soniyadan keyin qayta urinilmoqda: %s", e)
                time.sleep(5)
        except Exception as e:
            # Tarmoq uzilishi yoki Telegram API vaqtinchalik ishlamay qolishi kabi hollarda
            # bot butunlay o'chib qolmasin — 5 soniya kutib qayta ulanadi.
            _logger.exception("Polling to'xtadi, 5 soniyadan keyin qayta urinilmoqda: %s", e)
            time.sleep(5)
